.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 64px 32px;
}

.empty__icon {
  font-size: 56px;
  margin-bottom: 16px;
}

.empty__text {
  color: var(--color-text-secondary);
  font-size: 14px;
}

.empty__action {
  margin-top: 24px;
  padding: 12px 40px;
  border-radius: 999px;
  background: var(--color-primary);
}

.empty__action-text {
  color: #fff;
  font-size: 14px;
}
