import { useEffect, useMemo, useRef, useState } from 'react'
import { View, Text, Textarea, Input, ScrollView } from '@tarojs/components'
import Taro from '@tarojs/taro'
import Popup from '@/components/SheetPopup'
import { LOTTERY_LIST, normalizeLotteryCode, type LotteryCode } from '@/constants/lottery'
import { fetchHistoryReview } from '@/services/api'
import { STORAGE_KEYS } from '@/utils/storage'
import { historyReviewLabels as labels } from '@/labels/tools'
import Empty from '@/components/Empty'
import PopupCloseIcon from '@/components/PopupCloseIcon'
import './index.css'

/** 彩种规则（Web PRD §6.8.3）：定数范围与总位数 */
const RULES: Record<LotteryCode, { counts: number[]; positions: number }> = {
  '350133': { counts: [2, 3, 4, 5], positions: 5 },
  '04': { counts: [2, 3, 4], positions: 7 },
  '3d': { counts: [2, 3], positions: 3 },
}
const POSITION_NAMES = ['百万位', '十万位', '万位', '千位', '百位', '十位', '个位']
type ReviewCount = number | 'all'
const PERIOD_OPTIONS: ReviewCount[] = ['all', 10, 30, 50, 100, 200]
const PAGE_SIZE = 20

type YearMode = 'all' | 'single' | 'multiple'
type ReviewLevel = 'extreme' | 'high' | 'normal'

interface ReviewRow {
  issue: string
  result: string
  drawTime?: string
  positionCode: string
  hit: boolean
}

interface PeriodGroup {
  key: string
  latestIssue: string
  earliestIssue: string
  latestDrawTime?: string
  earliestDrawTime?: string
  total: number
  hitCount: number
  missCount: number
  hitRate: number
  children: ReviewRow[]
}

interface MonthRow {
  key: string
  month: string
  hitCount: number
  missCount: number
  hitRate: number
  hitRatio: number
  level: ReviewLevel
}

interface YearRow {
  key: string
  year: string
  hitCount: number
  missCount: number
  hitRate: number
  hitRatio: number
  level: ReviewLevel
  children: MonthRow[]
}

function toast(title: string) {
  Taro.showToast({ title, icon: 'none' })
}

/** 开奖号只保留数字位 */
function normalizeDigits(value?: string) {
  return (String(value || '').match(/\d/g) || []).join('')
}

/** 期号解析年份：前 4 位 20xx 直接取，前 2 位补 20 前缀 */
function getIssueYear(issue: string) {
  const digits = issue.replace(/\D/g, '')
  return /^20\d{2}$/.test(digits.slice(0, 4))
    ? digits.slice(0, 4)
    : /^\d{2}$/.test(digits.slice(0, 2))
      ? `20${digits.slice(0, 2)}`
      : ''
}

function getDrawMonth(drawTime?: string) {
  const matched = String(drawTime || '').match(/(?:19|20)\d{2}[-/.](0?[1-9]|1[0-2])/)
  return matched ? matched[1].padStart(2, '0') : '未知'
}

function formatDrawDate(drawTime?: string) {
  const matched = String(drawTime || '').match(/(?:19|20)\d{2}[-/.](?:0?[1-9]|1[0-2])[-/.](?:0?[1-9]|[12]\d|3[01])/)
  return matched ? matched[0].replace(/[/.]/g, '-') : '未知日期'
}

function formatRate(rate: number) {
  return `${(rate * 100).toFixed(1)}%`
}

function getReviewLevel(ratio: number): ReviewLevel {
  return ratio > 0.8 ? 'extreme' : ratio > 0.6 ? 'high' : 'normal'
}

function levelLabel(level: ReviewLevel) {
  return level === 'extreme' ? labels.levelExtreme : level === 'high' ? labels.levelHigh : labels.levelNormal
}

/** 默认位置：末 N 位 */
function defaultPositions(code: LotteryCode, digitCount: number) {
  const total = RULES[code].positions
  return Array.from({ length: digitCount }, (_, i) => total - digitCount + i)
}

/** 逐期命中判定：取开奖号指定位置数字拼接，判断是否命中大底 */
function judgeRows(rows: { issue: string; result: string; drawTime?: string }[], baseSet: ReadonlySet<string>, positions: number[]): ReviewRow[] {
  const sorted = [...positions].sort((a, b) => a - b)
  return rows.map((item) => {
    const numbers = normalizeDigits(item.result)
    const positionCode = sorted.map((p) => numbers[p] || '').join('')
    return {
      issue: String(item.issue || ''),
      result: String(item.result || ''),
      drawTime: item.drawTime,
      positionCode,
      hit: baseSet.has(positionCode),
    }
  })
}

/** 年回查聚合：按年（期号）与月（drawTime）聚合对错与命中率，命中等级 = 命中数 ÷ 最大命中数 */
function aggregateYears(
  rows: { issue: string; result: string; drawTime?: string }[],
  baseCodes: string[],
  positions: number[],
  mode: YearMode,
  selectedYears: string[],
): YearRow[] {
  const baseSet = new Set(baseCodes)
  const selectedSet = new Set(selectedYears)
  const judged = judgeRows(rows, baseSet, positions)
  const filtered = judged.filter((row) => {
    const year = getIssueYear(row.issue)
    return year && (mode === 'all' || selectedSet.has(year))
  })
  const byYear = new Map<string, ReviewRow[]>()
  const byMonth = new Map<string, ReviewRow[]>()
  filtered.forEach((row) => {
    const year = getIssueYear(row.issue)
    const monthKey = `${year}-${getDrawMonth(row.drawTime)}`
    byYear.set(year, [...(byYear.get(year) || []), row])
    byMonth.set(monthKey, [...(byMonth.get(monthKey) || []), row])
  })
  const summarize = (list: ReviewRow[]) => {
    const hitCount = list.filter((item) => item.hit).length
    return { hitCount, missCount: list.length - hitCount, hitRate: list.length ? hitCount / list.length : 0 }
  }
  const yearSummaries = [...byYear.entries()].map(([year, list]) => ({ year, ...summarize(list) }))
  const monthSummaries = [...byMonth.entries()].map(([key, list]) => ({
    year: key.slice(0, 4),
    month: key.slice(5),
    ...summarize(list),
  }))
  const yearBaseline = Math.max(0, ...yearSummaries.map((item) => item.hitCount))
  const monthBaseline = Math.max(0, ...monthSummaries.map((item) => item.hitCount))
  return yearSummaries
    .map((yearItem) => {
      const hitRatio = yearBaseline > 0 ? yearItem.hitCount / yearBaseline : 0
      const children = monthSummaries
        .filter((monthItem) => monthItem.year === yearItem.year)
        .map((monthItem) => {
          const monthRatio = monthBaseline > 0 ? monthItem.hitCount / monthBaseline : 0
          return {
            key: `month-${yearItem.year}-${monthItem.month}`,
            month: monthItem.month,
            hitCount: monthItem.hitCount,
            missCount: monthItem.missCount,
            hitRate: monthItem.hitRate,
            hitRatio: monthRatio,
            level: getReviewLevel(monthRatio),
          }
        })
        .sort((a, b) => b.month.localeCompare(a.month))
      return {
        key: `year-${yearItem.year}`,
        year: yearItem.year,
        hitCount: yearItem.hitCount,
        missCount: yearItem.missCount,
        hitRate: yearItem.hitRate,
        hitRatio,
        level: getReviewLevel(hitRatio),
        children,
      }
    })
    .sort((a, b) => b.year.localeCompare(a.year))
}

/** 历史回查工具（免费，Web PRD §6.8.3）：期数回查 + 年回查 */
export default function HistoryReviewPage() {
  // 入口携带的彩种 code（如首页开奖卡「回查」直达），非法或缺省回落排列五
  const initialCode = normalizeLotteryCode(Taro.getCurrentInstance().router?.params?.code)
  const [code, setCode] = useState<LotteryCode>(initialCode)
  const [digitCount, setDigitCount] = useState(2)
  const [positions, setPositions] = useState<number[]>(() => defaultPositions(initialCode, 2))
  const [baseInput, setBaseInput] = useState('')
  const [issueOptions, setIssueOptions] = useState<string[]>([])
  const [issuesLoading, setIssuesLoading] = useState(false)
  const [endIssue, setEndIssue] = useState('')
  const [issueSheetVisible, setIssueSheetVisible] = useState(false)
  const [reviewCount, setReviewCount] = useState<ReviewCount>('all')
  const [yearMode, setYearMode] = useState<YearMode>('all')
  const [years, setYears] = useState<string[]>([])
  const [yearsLoading, setYearsLoading] = useState(false)
  const [selectedYears, setSelectedYears] = useState<string[]>([])
  const [yearSheetVisible, setYearSheetVisible] = useState(false)
  const [results, setResults] = useState<ReviewRow[]>([])
  const [yearRows, setYearRows] = useState<YearRow[]>([])
  const [resultMode, setResultMode] = useState<'period' | 'year'>('period')
  const [reviewed, setReviewed] = useState(false)
  const [loading, setLoading] = useState(false)
  const [yearLoading, setYearLoading] = useState(false)
  const [keyword, setKeyword] = useState('')
  const [displayCount, setDisplayCount] = useState(PAGE_SIZE)
  const [expandedKeys, setExpandedKeys] = useState<Record<string, boolean>>({})
  const issueReqId = useRef(0)
  const yearReqId = useRef(0)

  const rule = RULES[code]
  const positionLabels = POSITION_NAMES.slice(-rule.positions)
  const exampleCode = '012345'.slice(0, digitCount)

  const baseCount = useMemo(() => {
    const tokens = baseInput.split(/[\s,，;；]+/).map((item) => item.trim()).filter(Boolean)
    return new Set(tokens.filter((item) => new RegExp(`^\\d{${digitCount}}$`).test(item))).size
  }, [baseInput, digitCount])

  const loadIssues = async (target: LotteryCode) => {
    const id = ++issueReqId.current
    setIssuesLoading(true)
    setIssueOptions([])
    try {
      const res = await fetchHistoryReview({ lotteryCode: target, count: 10 })
      if (id !== issueReqId.current) return
      const options = [...new Set((res?.rows || []).map((item) => String(item.issue || '')).filter(Boolean))]
      setIssueOptions(options)
      setEndIssue(options[0] || '')
    } catch {
      if (id === issueReqId.current) setIssueOptions([])
    } finally {
      if (id === issueReqId.current) setIssuesLoading(false)
    }
  }

  const loadYears = async (target: LotteryCode) => {
    const id = ++yearReqId.current
    setYearsLoading(true)
    try {
      const res = await fetchHistoryReview({ lotteryCode: target, metadata: 1 })
      if (id !== yearReqId.current) return
      setYears([...new Set(res?.years || [])])
    } catch {
      if (id === yearReqId.current) setYears([])
    } finally {
      if (id === yearReqId.current) setYearsLoading(false)
    }
  }

  // 跨工具 payload：读取后即删除，含大底/定数/彩种时预填（Web PRD §5.7）
  useEffect(() => {
    void (async () => {
      let initialCode: LotteryCode = '350133'
      let raw = ''
      try {
        const res = await Taro.getStorage({ key: STORAGE_KEYS.historyReviewPayload })
        raw = String(res.data || '')
      } catch {
        raw = ''
      }
      if (raw) {
        Taro.removeStorage({ key: STORAGE_KEYS.historyReviewPayload }).catch(() => {})
        try {
          const payload = JSON.parse(raw) as { lotteryType?: string; digitCount?: number; codes?: string[] }
          const meta = LOTTERY_LIST.find((item) => item.toolKey === payload.lotteryType)
          const digit = Number(payload.digitCount)
          const valid =
            meta &&
            RULES[meta.code].counts.includes(digit) &&
            Array.isArray(payload.codes) &&
            payload.codes.length > 0 &&
            payload.codes.every((item) => new RegExp(`^\\d{${digit}}$`).test(item))
          if (!valid) throw new Error('invalid history review payload')
          initialCode = meta.code
          setCode(meta.code)
          setDigitCount(digit)
          setPositions(defaultPositions(meta.code, digit))
          setBaseInput([...new Set(payload.codes!)].join(' '))
        } catch {
          toast(labels.errors.payloadInvalid)
        }
      }
      loadIssues(initialCode)
    })()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const resetResults = () => {
    setResults([])
    setYearRows([])
    setReviewed(false)
    setResultMode('period')
    setKeyword('')
    setDisplayCount(PAGE_SIZE)
    setExpandedKeys({})
  }

  const changeLottery = (next: LotteryCode) => {
    if (next === code) return
    const counts = RULES[next].counts
    const nextDigit = counts.includes(digitCount) ? digitCount : counts[0]
    setCode(next)
    setDigitCount(nextDigit)
    setPositions(defaultPositions(next, nextDigit))
    setEndIssue('')
    setSelectedYears([])
    setYears([])
    resetResults()
    loadIssues(next)
    if (yearMode !== 'all') loadYears(next)
  }

  const changeDigit = (next: number) => {
    if (next === digitCount) return
    setDigitCount(next)
    setPositions(defaultPositions(code, next))
    resetResults()
  }

  const togglePosition = (index: number) => {
    if (positions.includes(index)) {
      setPositions(positions.filter((item) => item !== index))
    } else if (positions.length < digitCount) {
      setPositions([...positions, index])
    }
  }

  const changeYearMode = (mode: YearMode) => {
    setYearMode(mode)
    if (mode !== 'all' && !years.length && !yearsLoading) loadYears(code)
  }

  const toggleYear = (year: string) => {
    setSelectedYears(
      selectedYears.includes(year) ? selectedYears.filter((item) => item !== year) : [...selectedYears, year],
    )
  }

  const parseBaseCodes = (): string[] | null => {
    const tokens = baseInput.split(/[\s,，;；]+/).map((item) => item.trim()).filter(Boolean)
    if (!tokens.length) {
      toast(labels.errors.baseRequired)
      return null
    }
    const invalid = tokens.find((item) => !new RegExp(`^\\d{${digitCount}}$`).test(item))
    if (invalid) {
      toast(labels.errors.baseInvalid(digitCount, invalid))
      return null
    }
    return [...new Set(tokens)]
  }

  const checkForm = (): string[] | null => {
    const baseCodes = parseBaseCodes()
    if (!baseCodes?.length) return null
    if (positions.length !== digitCount) {
      toast(labels.errors.positionMismatch)
      return null
    }
    if (!endIssue.trim()) {
      toast(labels.errors.endIssueRequired)
      return null
    }
    return baseCodes
  }

  const runReview = async () => {
    const baseCodes = checkForm()
    if (!baseCodes || loading) return
    setLoading(true)
    try {
      const res = await fetchHistoryReview({ lotteryCode: code, endIssue: endIssue.trim(), count: 'all' })
      if (res?.message) toast(res.message)
      setResults(judgeRows(res?.rows || [], new Set(baseCodes), positions))
      setResultMode('period')
      setReviewed(true)
      setDisplayCount(PAGE_SIZE)
      setExpandedKeys({})
    } catch {
      toast(labels.errors.reviewFailed)
    } finally {
      setLoading(false)
    }
  }

  const runYearReview = async () => {
    const baseCodes = checkForm()
    if (!baseCodes || yearLoading) return
    if (yearMode !== 'all' && !selectedYears.length) {
      toast(labels.errors.yearRequired)
      return
    }
    setYearLoading(true)
    try {
      const res = await fetchHistoryReview({ lotteryCode: code, endIssue: endIssue.trim(), count: 'all' })
      if (res?.message) {
        toast(res.message)
        return
      }
      setYearRows(aggregateYears(res?.rows || [], baseCodes, positions, yearMode, selectedYears))
      setKeyword('')
      setResultMode('year')
      setReviewed(true)
      setDisplayCount(PAGE_SIZE)
      setExpandedKeys({})
    } catch {
      toast(labels.errors.yearReviewFailed)
    } finally {
      setYearLoading(false)
    }
  }

  const clearReview = () => {
    setBaseInput('')
    setEndIssue(issueOptions[0] || '')
    resetResults()
  }

  const hitCount = useMemo(() => results.filter((item) => item.hit).length, [results])

  const periodGroups = useMemo<PeriodGroup[]>(() => {
    if (reviewCount === 'all') return []
    const interval = reviewCount
    return Array.from({ length: Math.ceil(results.length / interval) }, (_, index) => {
      const children = results.slice(index * interval, (index + 1) * interval)
      const hits = children.filter((item) => item.hit).length
      return {
        key: `${children[0]?.issue || index}-${children[children.length - 1]?.issue || index}`,
        latestIssue: children[0]?.issue || '',
        earliestIssue: children[children.length - 1]?.issue || '',
        latestDrawTime: children[0]?.drawTime,
        earliestDrawTime: children[children.length - 1]?.drawTime,
        total: children.length,
        hitCount: hits,
        missCount: children.length - hits,
        hitRate: children.length ? hits / children.length : 0,
        children,
      }
    })
  }, [results, reviewCount])

  const filteredYearRows = useMemo(() => {
    const kw = keyword.trim()
    if (!kw) return yearRows
    return yearRows
      .map((row) => {
        if (row.year.includes(kw)) return row
        const children = row.children.filter((child) => `${row.year}-${child.month}`.includes(kw))
        return children.length ? { ...row, children } : null
      })
      .filter((row): row is YearRow => Boolean(row))
  }, [yearRows, keyword])

  const toggleExpand = (key: string) => {
    setExpandedKeys((prev) => ({ ...prev, [key]: !prev[key] }))
  }

  const summaryText =
    resultMode === 'year'
      ? labels.yearSummary(filteredYearRows.length)
      : reviewCount === 'all'
        ? labels.hitSummary(hitCount, results.length)
        : labels.groupSummary(periodGroups.length, hitCount, results.length)

  const renderLevelBall = (level: ReviewLevel, ratio: number) => (
    <View className='level'>
      <View className={`level__ball level__ball--${level}`} />
      <Text className='level__ratio'>{formatRate(ratio)}</Text>
    </View>
  )

  const renderDetailRow = (row: ReviewRow) => (
    <View key={row.issue} className='rv-row'>
      <Text className='rv-row__issue'>{row.issue}</Text>
      <Text className='rv-row__result'>{row.result}</Text>
      <Text className='rv-row__pos'>{row.positionCode}</Text>
      <Text className={`rv-tag${row.hit ? ' rv-tag--hit' : ''}`}>{row.hit ? labels.hit : labels.miss}</Text>
    </View>
  )

  return (
    <View className='hr-page'>
      {/* 表单 */}
      <View className='hr-card'>
        <Text className='hr-label'>{labels.lotterySection}</Text>
        <View className='chips'>
          {LOTTERY_LIST.map((item) => (
            <View
              key={item.code}
              className={`chip${item.code === code ? ' chip--active' : ''}`}
              onClick={() => changeLottery(item.code)}
            >
              <Text className={`chip__text${item.code === code ? ' chip__text--active' : ''}`}>{item.label}</Text>
            </View>
          ))}
        </View>

        <Text className='hr-label'>{labels.digitSection}</Text>
        <View className='chips'>
          {rule.counts.map((count) => (
            <View
              key={count}
              className={`chip${count === digitCount ? ' chip--active' : ''}`}
              onClick={() => changeDigit(count)}
            >
              <Text className={`chip__text${count === digitCount ? ' chip__text--active' : ''}`}>
                {labels.digitUnit(count)}
              </Text>
            </View>
          ))}
        </View>

        <View className='hr-label-row'>
          <Text className='hr-label'>{labels.baseSection}</Text>
          <Text className='hr-hint'>{labels.baseHint}</Text>
        </View>
        <Textarea
          className='hr-textarea'
          value={baseInput}
          placeholder={labels.basePlaceholder(digitCount, exampleCode)}
          maxlength={-1}
          onInput={(e) => setBaseInput(e.detail.value)}
        />
        {baseInput.trim() ? <Text className='hr-hint'>{labels.baseCount(baseCount)}</Text> : null}

        <View className='hr-label-row'>
          <Text className='hr-label'>{labels.positionSection}</Text>
          <Text className='hr-hint'>{labels.positionHint(digitCount)}</Text>
        </View>
        <View className='chips'>
          {positionLabels.map((name, index) => {
            const active = positions.includes(index)
            const disabled = !active && positions.length >= digitCount
            return (
              <View
                key={name}
                className={`chip${active ? ' chip--active' : ''}${disabled ? ' chip--disabled' : ''}`}
                onClick={() => togglePosition(index)}
              >
                <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>{name}</Text>
              </View>
            )
          })}
        </View>

        <Text className='hr-label'>{labels.issueSection}</Text>
        <View className='field-row' onClick={() => issueOptions.length > 0 && setIssueSheetVisible(true)}>
          <Text className={`field-row__value${endIssue ? '' : ' field-row__value--placeholder'}`}>
            {issuesLoading ? labels.issueLoading : endIssue || labels.issuePlaceholder}
          </Text>
          <Text className='field-row__arrow'>›</Text>
        </View>

        <Text className='hr-label'>{labels.periodSection}</Text>
        <View className='chips'>
          {PERIOD_OPTIONS.map((option) => (
            <View
              key={String(option)}
              className={`chip${option === reviewCount ? ' chip--active' : ''}`}
              onClick={() => {
                setReviewCount(option)
                setDisplayCount(PAGE_SIZE)
              }}
            >
              <Text className={`chip__text${option === reviewCount ? ' chip__text--active' : ''}`}>
                {option === 'all' ? labels.periodAll : labels.periodEvery(option)}
              </Text>
            </View>
          ))}
        </View>
        <Text className='hr-hint'>
          {reviewCount === 'all' ? labels.periodDescAll : labels.periodDescGroup(reviewCount)}
        </Text>

        <Text className='hr-label'>{labels.yearSection}</Text>
        <View className='chips'>
          {(['all', 'single', 'multiple'] as YearMode[]).map((mode) => (
            <View
              key={mode}
              className={`chip${mode === yearMode ? ' chip--active' : ''}`}
              onClick={() => changeYearMode(mode)}
            >
              <Text className={`chip__text${mode === yearMode ? ' chip__text--active' : ''}`}>
                {mode === 'all' ? labels.yearAll : mode === 'single' ? labels.yearSingle : labels.yearMultiple}
              </Text>
            </View>
          ))}
        </View>
        {yearMode === 'single' ? (
          <View className='field-row' onClick={() => years.length > 0 && setYearSheetVisible(true)}>
            <Text className={`field-row__value${selectedYears[0] ? '' : ' field-row__value--placeholder'}`}>
              {yearsLoading ? labels.yearLoading : selectedYears[0] || labels.yearPlaceholder}
            </Text>
            <Text className='field-row__arrow'>›</Text>
          </View>
        ) : null}
        {yearMode === 'multiple' ? (
          <View className='chips'>
            {yearsLoading ? (
              <Text className='hr-hint'>{labels.yearLoading}</Text>
            ) : (
              years.map((year) => (
                <View
                  key={year}
                  className={`chip${selectedYears.includes(year) ? ' chip--active' : ''}`}
                  onClick={() => toggleYear(year)}
                >
                  <Text className={`chip__text${selectedYears.includes(year) ? ' chip__text--active' : ''}`}>
                    {year}
                  </Text>
                </View>
              ))
            )}
          </View>
        ) : null}

        <View className='hr-actions'>
          <View className='hr-btn hr-btn--plain' onClick={clearReview}>
            <Text className='hr-btn__text hr-btn__text--plain'>{labels.clear}</Text>
          </View>
          <View
            className={`hr-btn${yearLoading ? ' hr-btn--disabled' : ''}`}
            onClick={runYearReview}
          >
            <Text className='hr-btn__text'>{yearLoading ? labels.reviewing : labels.runYearReview}</Text>
          </View>
          <View className={`hr-btn${loading ? ' hr-btn--disabled' : ''}`} onClick={runReview}>
            <Text className='hr-btn__text'>{loading ? labels.reviewing : labels.runReview}</Text>
          </View>
        </View>
      </View>

      {/* 结果 */}
      <View className='hr-card'>
        <View className='hr-result-head'>
          <Text className='hr-label'>{resultMode === 'year' ? labels.yearResultTitle : labels.resultTitle}</Text>
          {reviewed ? <Text className='hr-hint'>{summaryText}</Text> : null}
        </View>

        {resultMode === 'year' && reviewed ? (
          <Input
            className='hr-search'
            value={keyword}
            placeholder={labels.yearSearchPlaceholder}
            onInput={(e) => {
              setKeyword(e.detail.value)
              setDisplayCount(PAGE_SIZE)
            }}
          />
        ) : null}

        {!reviewed ? (
          <Empty text={labels.resultEmpty} />
        ) : resultMode === 'period' && results.length === 0 ? (
          <Empty text={labels.noHistory} />
        ) : resultMode === 'year' && filteredYearRows.length === 0 ? (
          <Empty text={labels.noHistory} />
        ) : resultMode === 'period' && reviewCount === 'all' ? (
          <>
            <View className='rv-row rv-row--head'>
              <Text className='rv-row__issue'>{labels.columnIssue}</Text>
              <Text className='rv-row__result'>{labels.columnResult}</Text>
              <Text className='rv-row__pos'>{labels.columnPosition}</Text>
              <Text className='rv-tag rv-tag--head'>{labels.columnStatus}</Text>
            </View>
            {results.slice(0, displayCount).map(renderDetailRow)}
            {displayCount < results.length ? (
              <View className='load-more' onClick={() => setDisplayCount(displayCount + PAGE_SIZE)}>
                <Text className='load-more__text'>{labels.loadMore}</Text>
              </View>
            ) : null}
          </>
        ) : resultMode === 'period' ? (
          <>
            {periodGroups.slice(0, displayCount).map((group) => (
              <View key={group.key} className='rv-group'>
                <View className='rv-group__head' onClick={() => toggleExpand(group.key)}>
                  <View className='rv-group__range'>
                    <Text className='rv-group__issues'>{labels.groupRange(group.latestIssue, group.earliestIssue)}</Text>
                    <Text className='rv-group__dates'>
                      {labels.groupDateRange(formatDrawDate(group.earliestDrawTime), formatDrawDate(group.latestDrawTime))}
                    </Text>
                  </View>
                  <View className='rv-group__stats'>
                    <Text className='rv-group__stat'>
                      {labels.columnTotal} {group.total}
                    </Text>
                    <Text className='rv-group__stat rv-group__stat--hit'>
                      {labels.columnHit} {group.hitCount}
                    </Text>
                    <Text className='rv-group__stat'>
                      {labels.columnMiss} {group.missCount}
                    </Text>
                    <Text className='rv-group__stat'>{formatRate(group.hitRate)}</Text>
                    <Text className='rv-group__toggle'>{expandedKeys[group.key] ? labels.collapse : labels.expand}</Text>
                  </View>
                </View>
                {expandedKeys[group.key] ? (
                  <View className='rv-group__detail'>{group.children.map(renderDetailRow)}</View>
                ) : null}
              </View>
            ))}
            {displayCount < periodGroups.length ? (
              <View className='load-more' onClick={() => setDisplayCount(displayCount + PAGE_SIZE)}>
                <Text className='load-more__text'>{labels.loadMore}</Text>
              </View>
            ) : null}
          </>
        ) : (
          <>
            <View className='level-legend'>
              <Text className='hr-hint'>{labels.levelTitle}：</Text>
              {(['extreme', 'high', 'normal'] as ReviewLevel[]).map((level) => (
                <View key={level} className='level'>
                  <View className={`level__ball level__ball--${level}`} />
                  <Text className='level__name'>{levelLabel(level)}</Text>
                </View>
              ))}
            </View>
            {filteredYearRows.slice(0, displayCount).map((yearRow) => (
              <View key={yearRow.key} className='rv-group'>
                <View className='rv-group__head' onClick={() => toggleExpand(yearRow.key)}>
                  <View className='rv-group__range'>
                    <Text className='rv-group__issues'>{yearRow.year}</Text>
                    <Text className='rv-group__dates'>
                      {labels.columnHit} {yearRow.hitCount} / {labels.columnMiss} {yearRow.missCount} /{' '}
                      {formatRate(yearRow.hitRate)}
                    </Text>
                  </View>
                  <View className='rv-group__stats'>
                    {renderLevelBall(yearRow.level, yearRow.hitRatio)}
                    <Text className='rv-group__toggle'>
                      {expandedKeys[yearRow.key] ? labels.collapse : labels.expand}
                    </Text>
                  </View>
                </View>
                {expandedKeys[yearRow.key] ? (
                  <View className='rv-group__detail'>
                    <Text className='rv-group__detail-title'>{labels.monthDetailTitle(yearRow.year)}</Text>
                    {yearRow.children.map((monthRow) => (
                      <View key={monthRow.key} className='rv-row'>
                        <Text className='rv-row__issue'>{monthRow.month}</Text>
                        <Text className='rv-row__result'>
                          {labels.columnHit} {monthRow.hitCount} / {labels.columnMiss} {monthRow.missCount}
                        </Text>
                        <Text className='rv-row__pos'>{formatRate(monthRow.hitRate)}</Text>
                        {renderLevelBall(monthRow.level, monthRow.hitRatio)}
                      </View>
                    ))}
                  </View>
                ) : null}
              </View>
            ))}
            {displayCount < filteredYearRows.length ? (
              <View className='load-more' onClick={() => setDisplayCount(displayCount + PAGE_SIZE)}>
                <Text className='load-more__text'>{labels.loadMore}</Text>
              </View>
            ) : null}
          </>
        )}
      </View>

      {/* 截至期号选择弹层 */}
      <Popup
        visible={issueSheetVisible}
        closeable
        closeIcon={<PopupCloseIcon />}
        onClose={() => setIssueSheetVisible(false)}
      >
        <View className='sheet'>
          <Text className='sheet__title'>{labels.issueSection}</Text>
          <ScrollView scrollY className='sheet__list'>
            {issueOptions.map((issue) => (
              <View
                key={issue}
                className={`sheet__item${issue === endIssue ? ' sheet__item--active' : ''}`}
                onClick={() => {
                  setEndIssue(issue)
                  setIssueSheetVisible(false)
                }}
              >
                <Text className={`sheet__item-text${issue === endIssue ? ' sheet__item-text--active' : ''}`}>
                  {issue}
                </Text>
              </View>
            ))}
          </ScrollView>
        </View>
      </Popup>

      {/* 年份选择弹层（某年模式） */}
      <Popup
        visible={yearSheetVisible}
        closeable
        closeIcon={<PopupCloseIcon />}
        onClose={() => setYearSheetVisible(false)}
      >
        <View className='sheet'>
          <Text className='sheet__title'>{labels.yearPlaceholder}</Text>
          <ScrollView scrollY className='sheet__list'>
            {years.map((year) => (
              <View
                key={year}
                className={`sheet__item${year === selectedYears[0] ? ' sheet__item--active' : ''}`}
                onClick={() => {
                  setSelectedYears([year])
                  setYearSheetVisible(false)
                }}
              >
                <Text className={`sheet__item-text${year === selectedYears[0] ? ' sheet__item-text--active' : ''}`}>
                  {year}
                </Text>
              </View>
            ))}
          </ScrollView>
        </View>
      </Popup>
    </View>
  )
}
