// ---------- 彩种维度 ----------

export function drawCountOf(lotteryCode: string) {
  if (lotteryCode === '04') return 7
  if (lotteryCode === '3d') return 3
  return 5
}

/** 前后分区：七星彩与排列五第 4 位后为后区（源 1036 行） */
export function rearDigitStartIndexOf(lotteryCode: string) {
  if (lotteryCode === '04') return 4
  if (lotteryCode === '350133') return 4
  return -1
}

/** 引擎层只有位数时的等价推断：7 位（七星彩）/5 位（排列五）→ 4，3 位（3D）→ -1 */
export function rearDigitStartIndexFromCount(drawCount: number) {
  return drawCount >= 5 ? 4 : -1
}

export function isRearDigitColumnByCount(drawCount: number, index: number) {
  const rearStart = rearDigitStartIndexFromCount(drawCount)
  return rearStart >= 0 && index >= rearStart
}

export function splitAfterIndexOf(lotteryCode: string) {
  const rearStart = rearDigitStartIndexOf(lotteryCode)
  return rearStart > 0 ? rearStart - 1 : -1
}

export function sumDigitCountOf(lotteryCode: string) {
  const rearStart = rearDigitStartIndexOf(lotteryCode)
  return rearStart > 0 ? rearStart : drawCountOf(lotteryCode)
}

export function isRearDigitColumn(lotteryCode: string, index: number) {
  const rearStart = rearDigitStartIndexOf(lotteryCode)
  return rearStart >= 0 && index >= rearStart
}

/** 每 4 行一条分区粗线（源 isSectionEndRow） */
export function isSectionEndRow(rowIndex: number) {
  return (rowIndex + 1) % 4 === 0
}

// ---------- 奖表行计算 ----------

export function normalizeNumbers(numbers: unknown, count: number) {
  const values = Array.isArray(numbers) ? numbers : []
  return values
    .slice(0, count)
    .map((item) => String(item ?? '').trim())
    .filter(Boolean)
}

export function issueSuffix(raw?: string) {
  const value = String(raw || '').trim()
  if (!value) return ''
  return value.length > 5 ? value.slice(-5) : value
}

export function nextIssue(issue: string, offset = 1) {
  const value = String(issue || '').trim()
  if (!value) return ''
  const numeric = Number(value)
  if (!Number.isFinite(numeric)) return ''
  return String(numeric + offset).padStart(value.length, '0')
}

export function sumNumbers(numbers: string[]) {
  if (!numbers.length) return ''
  const sum = numbers.reduce((total, item) => total + Number(item || 0), 0)
  return Number.isFinite(sum) ? String(sum) : ''
}

export function dateWeekLabel(raw?: string) {
  const value = String(raw || '').trim()
  if (!value) return ''
  const dateParts = value.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/)
  const date = dateParts
    ? new Date(Number(dateParts[1]), Number(dateParts[2]) - 1, Number(dateParts[3]))
    : new Date(value)
  if (!Number.isFinite(date.getTime())) return ''
  const mm = String(date.getMonth() + 1).padStart(2, '0')
  const dd = String(date.getDate()).padStart(2, '0')
  const weekMap = ['日', '一', '二', '三', '四', '五', '六']
  return `${mm}/${dd} 周${weekMap[date.getDay()]}`
}

/**
 * 奖表行：历史期（升序展示）+ 末尾 5 个未来期占位行 + 1 空行（源 1074 行 boardRows）。
 * history 入参为期数倒序（最新在前），内部截取 periodCount 后反转为升序。
 */
export function buildBoardRows(
  history: DrawHistoryInput[],
  periodCount: number,
  drawCount: number,
  sumDigitCount: number,
): BoardRow[] {
  const historyRows = history
    .filter((row) => normalizeNumbers(row.numbers, drawCount).length)
    .slice(0, periodCount)
    .reverse()

  const rows: BoardRow[] = historyRows.map((row, index) => {
    const numbers = normalizeNumbers(row.numbers, drawCount)
    return {
      key: row.drawNum ? `row-${row.drawNum}` : `row-${index}`,
      issue: issueSuffix(row.drawNum),
      weekLabel: dateWeekLabel(row.drawTime),
      sumText: sumNumbers(numbers.slice(0, sumDigitCount)),
      numbers,
      placeholder: false,
      drawable: true,
    }
  })

  const latestIssue = rows[rows.length - 1]?.issue || ''
  for (let index = 0; index < PREDICTION_FUTURE_ROW_COUNT; index += 1) {
    rows.push({
      key: `prediction-issue-${index + 1}`,
      issue: nextIssue(latestIssue, index + 1),
      weekLabel: '',
      sumText: '',
      numbers: [],
      placeholder: false,
      drawable: true,
      prediction: true,
    })
  }

  const total = historyRows.length + PREDICTION_FUTURE_ROW_COUNT + FUTURE_BLANK_ROW_COUNT
  while (rows.length < total) {
    rows.push({
      key: `placeholder-${rows.length}`,
      issue: '',
      weekLabel: '',
      sumText: '',
      numbers: [],
      placeholder: true,
      drawable: true,
    })
  }

  return rows
}

// ---------- 棋盘几何 ----------

export function computeBoardGeometry(viewportWidth: number, drawCount: number, rowCount: number): BoardGeometry {
  const baseBoardWidth = BASE_ISSUE_COLUMN_WIDTH + BASE_SUM_COLUMN_WIDTH + drawCount * BASE_DIGIT_CELL_WIDTH
  const compact = viewportWidth > 0 && viewportWidth <= MOBILE_LAYOUT_MAX_WIDTH
  const scale = compact ? Math.min(1, viewportWidth / baseBoardWidth) : 1
  const issueColumnWidth = BASE_ISSUE_COLUMN_WIDTH * scale
  const sumColumnWidth = BASE_SUM_COLUMN_WIDTH * scale
  const digitStartX = issueColumnWidth + sumColumnWidth
  const digitCellWidth = compact ? Math.max(1, (viewportWidth - digitStartX) / drawCount) : BASE_DIGIT_CELL_WIDTH
  const rowHeight = BASE_ROW_HEIGHT * scale
  const boardWidth = compact ? viewportWidth : digitStartX + drawCount * digitCellWidth
  return {
    scale,
    issueColumnWidth,
    sumColumnWidth,
    digitCellWidth,
    rowHeight,
    digitStartX,
    boardWidth,
    boardHeight: rowCount * rowHeight,
    digitMarkRadius: Math.max(13, BASE_DIGIT_MARK_RADIUS * scale),
    issueFontSize: Math.max(11, 16 * scale),
    issueWeekFontSize: Math.max(10, 12 * scale),
    sumFontSize: Math.max(12, 16 * scale),
    digitFontSize: Math.max(22, 34 * scale),
    rearDigitFontSize: Math.max(18, 26 * scale),
  }
}

// ---------- 数字格定位 ----------

export function digitCellKey(rowKey: string, columnIndex: number) {
  return `${rowKey}-${columnIndex}`
}

export function digitCellAt(
  geometry: BoardGeometry,
  rows: BoardRow[],
  rowIndex: number,
  columnIndex: number,
  drawCount: number,
): DigitCellTarget | null {
  const row = rows[rowIndex]
  if (!row || !row.drawable) return null
  const y = rowIndex * geometry.rowHeight + geometry.rowHeight / 2
  if (columnIndex === SUM_COLUMN_INDEX) {
    return {
      key: digitCellKey(row.key, columnIndex),
      rowKey: row.key,
      rowIndex,
      columnIndex,
      value: row.sumText || '',
      x: geometry.issueColumnWidth + geometry.sumColumnWidth / 2,
      y,
    }
  }
  if (columnIndex < 0 || columnIndex >= drawCount) return null
  return {
    key: digitCellKey(row.key, columnIndex),
    rowKey: row.key,
    rowIndex,
    columnIndex,
    value: row.numbers[columnIndex] || '',
    x: geometry.digitStartX + columnIndex * geometry.digitCellWidth + geometry.digitCellWidth / 2,
    y,
  }
}

export function cellCenterFromRowKey(
  geometry: BoardGeometry,
  rows: BoardRow[],
  rowKey: string,
  columnIndex: number,
  drawCount: number,
) {
  const rowIndex = rows.findIndex((row) => row.key === rowKey)
  if (rowIndex < 0) return null
  return digitCellAt(geometry, rows, rowIndex, columnIndex, drawCount)
}

export function resolveDigitCell(
  geometry: BoardGeometry,
  rows: BoardRow[],
  point: DrawPoint,
  drawCount: number,
): DigitCellTarget | null {
  if (
    point.x < geometry.issueColumnWidth ||
    point.x > geometry.boardWidth ||
    point.y < 0 ||
    point.y > geometry.boardHeight
  ) {
    return null
  }
  const rowIndex = Math.floor(point.y / geometry.rowHeight)
  if (point.x < geometry.digitStartX) {
    return digitCellAt(geometry, rows, rowIndex, SUM_COLUMN_INDEX, drawCount)
  }
  const columnIndex = Math.floor((point.x - geometry.digitStartX) / geometry.digitCellWidth)
  return digitCellAt(geometry, rows, rowIndex, columnIndex, drawCount)
}

// ---------- 智能线 ----------

export function digitCellAnchor(cell: DigitCellTarget): DrawCellAnchor {
  return { rowKey: cell.rowKey, columnIndex: cell.columnIndex }
}

export function smartLineBasePoints(item: DrawItem, geometry: BoardGeometry, rows: BoardRow[], drawCount: number) {
  if (item.lineKind === 'smart' && item.smartStart && item.smartEnd) {
    const startCell = cellCenterFromRowKey(geometry, rows, item.smartStart.rowKey, item.smartStart.columnIndex, drawCount)
    const endCell = cellCenterFromRowKey(geometry, rows, item.smartEnd.rowKey, item.smartEnd.columnIndex, drawCount)
    if (startCell && endCell) {
      return [startCell.x, startCell.y, endCell.x, endCell.y]
    }
  }
  return Array.isArray(item.points) ? item.points : []
}

export function lineMidPoint(points?: number[]) {
  if (!Array.isArray(points) || points.length < 4) return null
  return { x: (points[0] + points[2]) / 2, y: (points[1] + points[3]) / 2 }
}

export function controlPointVectorFromPoint(points: number[] | undefined, controlPoint: DrawPoint) {
  if (!Array.isArray(points) || points.length < 4) return null
  const start = { x: points[0], y: points[1] }
  const end = { x: points[2], y: points[3] }
  const dx = end.x - start.x
  const dy = end.y - start.y
  const distance = Math.hypot(dx, dy)
  if (!distance) return null
  const unit = { x: dx / distance, y: dy / distance }
  const perpendicular = { x: -unit.y, y: unit.x }
  const cx = controlPoint.x - start.x
  const cy = controlPoint.y - start.y
  return {
    along: (cx * unit.x + cy * unit.y) / distance,
    offset: (cx * perpendicular.x + cy * perpendicular.y) / distance,
  }
}

export function controlPointFromVector(points: number[] | undefined, vector: SmartLineControlVector) {
  if (!Array.isArray(points) || points.length < 4) return null
  const start = { x: points[0], y: points[1] }
  const end = { x: points[2], y: points[3] }
  const dx = end.x - start.x
  const dy = end.y - start.y
  const distance = Math.hypot(dx, dy)
  if (!distance) return null
  const unit = { x: dx / distance, y: dy / distance }
  const perpendicular = { x: -unit.y, y: unit.x }
  return {
    x: start.x + unit.x * vector.along * distance + perpendicular.x * vector.offset * distance,
    y: start.y + unit.y * vector.along * distance + perpendicular.y * vector.offset * distance,
  }
}

export function defaultSmartLineControlPoint(points: number[] | undefined, shape: SmartLineShape) {
  const mid = lineMidPoint(points)
  if (!mid || !Array.isArray(points) || points.length < 4 || shape === 'straight') return null
  const dx = points[2] - points[0]
  const dy = points[3] - points[1]
  const distance = Math.hypot(dx, dy)
  if (!distance) return null
  const offset = Math.max(42, distance * SMART_LINE_CURVE_OFFSET_RATIO)
  const perpendicular = { x: -dy / distance, y: dx / distance }
  const direction = shape === 'up' ? -1 : 1
  return {
    x: mid.x + perpendicular.x * offset * direction,
    y: mid.y + perpendicular.y * offset * direction,
  }
}

export function smartLineControlPoint(item: DrawItem, geometry: BoardGeometry, rows: BoardRow[], drawCount: number) {
  if (item.controlPoint) return item.controlPoint
  const points = smartLineBasePoints(item, geometry, rows, drawCount)
  if (item.controlPointVector) {
    const vectorPoint = controlPointFromVector(points, item.controlPointVector)
    if (vectorPoint) return vectorPoint
  }
  if (item.smartShape === 'straight') return null
  return defaultSmartLineControlPoint(points, item.smartShape || 'straight')
}

/** 渲染点集：直线 4 点，曲线插入控制点（Konva tension / svg 二次贝塞尔共用） */
export function smartLineRenderPoints(item: DrawItem, geometry: BoardGeometry, rows: BoardRow[], drawCount: number) {
  const points = smartLineBasePoints(item, geometry, rows, drawCount)
  if (points.length < 4) return points
  const controlPoint = smartLineControlPoint(item, geometry, rows, drawCount)
  if (!controlPoint) return points
  return [points[0], points[1], controlPoint.x, controlPoint.y, points[2], points[3]]
}

export function isCurvedSmartLine(item: DrawItem, geometry: BoardGeometry, rows: BoardRow[], drawCount: number) {
  return item.lineKind === 'smart' && Boolean(smartLineControlPoint(item, geometry, rows, drawCount))
}

/** 拖拽控制点后的补丁：转成与缩放/换期无关的相对向量（源 smartLineControlPatch） */
export function smartLineControlPatch(
  item: DrawItem,
  controlPoint: DrawPoint,
  geometry: BoardGeometry,
  rows: BoardRow[],
  drawCount: number,
): Partial<DrawItem> {
  if (item.lineKind !== 'smart') return { controlPoint }
  const controlPointVector = controlPointVectorFromPoint(
    smartLineBasePoints(item, geometry, rows, drawCount),
    controlPoint,
  )
  if (!controlPointVector) return { controlPoint }
  return { controlPoint: undefined, controlPointVector }
}

export function buildSmartLineSegments(
  geometry: BoardGeometry,
  rows: BoardRow[],
  drawCount: number,
  startCell: DigitCellTarget,
  targetCell: DigitCellTarget,
  penCount: number,
  gap: number,
  colorMode: SmartPenColorMode,
  activeColor: string,
): SmartLineSegment[] {
  const count = Math.max(1, penCount)
  const rowStep = gap + 1
  return Array.from({ length: count }, (_, index) => {
    const start = digitCellAt(geometry, rows, startCell.rowIndex - index * rowStep, startCell.columnIndex, drawCount)
    const target = digitCellAt(geometry, rows, targetCell.rowIndex - index * rowStep, targetCell.columnIndex, drawCount)
    if (!start || !target || start.key === target.key) return null
    return { start, target, color: smartLineColor(index, count, colorMode, activeColor) }
  }).filter((segment): segment is SmartLineSegment => Boolean(segment))
}

export function buildSmartLineDraftSegments(
  geometry: BoardGeometry,
  rows: BoardRow[],
  drawCount: number,
  startCell: DigitCellTarget,
  targetCell: DigitCellTarget | null,
  pointer: DrawPoint,
  penCount: number,
  gap: number,
  colorMode: SmartPenColorMode,
  activeColor: string,
): SmartLineDraftSegment[] {
  const count = Math.max(1, penCount)
  const rowStep = gap + 1
  const segments: SmartLineDraftSegment[] = []
  for (let index = 0; index < count; index += 1) {
    const start = digitCellAt(geometry, rows, startCell.rowIndex - index * rowStep, startCell.columnIndex, drawCount)
    if (!start) continue
    const target = targetCell
      ? digitCellAt(geometry, rows, targetCell.rowIndex - index * rowStep, targetCell.columnIndex, drawCount)
      : null
    const endPoint: DrawPoint = target || { x: pointer.x, y: pointer.y - index * rowStep * geometry.rowHeight }
    segments.push({
      start,
      endPoint,
      target: target || undefined,
      color: smartLineColor(index, count, colorMode, activeColor),
    })
  }
  return segments
}

export function smartLineColor(index: number, count: number, colorMode: SmartPenColorMode, activeColor: string) {
  if (colorMode === 'single') return activeColor
  const colors = MULTI_PEN_COLOR_SETS[count] || MULTI_PEN_COLOR_SETS[5]
  const visualIndex = Math.max(0, count - 1 - index)
  return colors[visualIndex % colors.length]
}

/** 智能线草稿的渲染点集（无锚点，直接以起止点 + 默认控制点计算） */
export function smartDraftRenderPoints(points: number[], shape: SmartLineShape) {
  if (points.length < 4) return points
  const controlPoint = defaultSmartLineControlPoint(points, shape)
  if (!controlPoint) return points
  return [points[0], points[1], controlPoint.x, controlPoint.y, points[2], points[3]]
}

// ---------- 通用几何 ----------

export function pointDistance(start: DrawPoint, end: DrawPoint) {
  return Math.hypot(end.x - start.x, end.y - start.y)
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

export function normalizeRect(start: DrawPoint, end: DrawPoint) {
  return {
    x: Math.min(start.x, end.x),
    y: Math.min(start.y, end.y),
    width: Math.max(1, Math.abs(end.x - start.x)),
    height: Math.max(1, Math.abs(end.y - start.y)),
  }
}

export function normalizeEllipse(start: DrawPoint, end: DrawPoint) {
  const rect = normalizeRect(start, end)
  return {
    x: rect.x + rect.width / 2,
    y: rect.y + rect.height / 2,
    radiusX: Math.max(1, rect.width / 2),
    radiusY: Math.max(1, rect.height / 2),
  }
}

export function rotatePoint(point: DrawPoint, center: DrawPoint, angleDegree: number) {
  const angle = (angleDegree * Math.PI) / 180
  const dx = point.x - center.x
  const dy = point.y - center.y
  return {
    x: center.x + dx * Math.cos(angle) - dy * Math.sin(angle),
    y: center.y + dx * Math.sin(angle) + dy * Math.cos(angle),
  }
}

export function colorWithAlpha(color: string, alpha: number) {
  const value = String(color || '').trim()
  const hexMatch = value.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i)
  if (!hexMatch) return value
  const hex = hexMatch[1]
  const normalized = hex.length === 3 ? hex.split('').map((item) => `${item}${item}`).join('') : hex
  const r = Number.parseInt(normalized.slice(0, 2), 16)
  const g = Number.parseInt(normalized.slice(2, 4), 16)
  const b = Number.parseInt(normalized.slice(4, 6), 16)
  return `rgba(${r}, ${g}, ${b}, ${alpha})`
}

export function isShapeTool(tool: DrawTool) {
  return tool === '实心圆形' || tool === '实心矩形' || tool === '空心圆形' || tool === '空心矩形'
}

export function shapeFillColor(tool: DrawTool, activeColor: string) {
  if (!tool.startsWith('实心')) return undefined
  return colorWithAlpha(activeColor, SOLID_SHAPE_FILL_OPACITY)
}

export function createDrawId() {
  return `draw-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
}

// ---------- 文字 ----------

export function measureTextWidth(text: string) {
  return Math.max(TEXT_DEFAULT_WIDTH, Array.from(text).length * TEXT_FONT_SIZE + 22)
}

export function measureTextItemWidth(item: DrawItem) {
  return item.width || measureTextWidth(item.text || '')
}

export function textItemCenterFromTopLeft(item: DrawItem, width: number, height: number) {
  const scale = item.scale || 1
  return {
    x: (item.x || 0) + (width * scale) / 2,
    y: (item.y || 0) + (height * scale) / 2,
  }
}

export function textItemCenter(item: DrawItem) {
  return textItemCenterFromTopLeft(item, measureTextItemWidth(item), item.height || TEXT_DEFAULT_HEIGHT)
}

export function textPositionPatchFromCenter(item: DrawItem, center: DrawPoint) {
  const width = measureTextItemWidth(item)
  const height = item.height || TEXT_DEFAULT_HEIGHT
  const scale = item.scale || 1
  return {
    x: center.x - (width * scale) / 2,
    y: center.y - (height * scale) / 2,
  }
}

// ---------- 命中测试（RN 手势层用；H5 由 Konva 原生处理） ----------

function distanceToSegment(point: DrawPoint, a: DrawPoint, b: DrawPoint) {
  const dx = b.x - a.x
  const dy = b.y - a.y
  const lengthSquared = dx * dx + dy * dy
  if (!lengthSquared) return pointDistance(point, a)
  const t = clamp(((point.x - a.x) * dx + (point.y - a.y) * dy) / lengthSquared, 0, 1)
  return pointDistance(point, { x: a.x + t * dx, y: a.y + t * dy })
}

export function hitTestDrawItem(
  items: DrawItem[],
  point: DrawPoint,
  geometry: BoardGeometry,
  rows: BoardRow[],
  drawCount: number,
): DrawItem | null {
  for (let index = items.length - 1; index >= 0; index -= 1) {
    const item = items[index]
    const tolerance = Math.max(0, item.strokeWidth || 0) / 2 + 6
    if (item.type === 'polyline' || item.type === 'freeLine') {
      const rawPoints = item.lineKind === 'smart'
        ? smartLineRenderPoints(item, geometry, rows, drawCount)
        : item.points || []
      if (rawPoints.length < 4) continue
      const offsetX = item.x || 0
      const offsetY = item.y || 0
      const threshold = Math.max((item.strokeWidth || 2) / 2 + 4, 8)
      let hit = false
      for (let i = 0; i + 3 < rawPoints.length; i += 2) {
        const a = { x: rawPoints[i] + offsetX, y: rawPoints[i + 1] + offsetY }
        const b = { x: rawPoints[i + 2] + offsetX, y: rawPoints[i + 3] + offsetY }
        if (distanceToSegment(point, a, b) <= threshold) {
          hit = true
          break
        }
      }
      // 曲线智能线按二次贝塞尔采样补判（直线段近似误差大时兜底）
      if (!hit && item.lineKind === 'smart' && rawPoints.length === 6) {
        const [sx, sy, cx, cy, ex, ey] = rawPoints
        for (let step = 0; step < 20 && !hit; step += 1) {
          const t0 = step / 20
          const t1 = (step + 1) / 20
          const quad = (t: number) => ({
            x: (1 - t) * (1 - t) * sx + 2 * (1 - t) * t * cx + t * t * ex + offsetX,
            y: (1 - t) * (1 - t) * sy + 2 * (1 - t) * t * cy + t * t * ey + offsetY,
          })
          if (distanceToSegment(point, quad(t0), quad(t1)) <= threshold) hit = true
        }
      }
      if (hit) return item
      continue
    }
    if (item.type === 'circle') {
      const radiusX = (item.radiusX || item.radius || 1) + tolerance
      const radiusY = (item.radiusY || item.radius || 1) + tolerance
      const nx = (point.x - (item.x || 0)) / radiusX
      const ny = (point.y - (item.y || 0)) / radiusY
      if (nx * nx + ny * ny <= 1) return item
      continue
    }
    if (item.type === 'rect') {
      const x = (item.x || 0) - tolerance
      const y = (item.y || 0) - tolerance
      const width = (item.width || 1) + tolerance * 2
      const height = (item.height || 1) + tolerance * 2
      if (point.x >= x && point.x <= x + width && point.y >= y && point.y <= y + height) return item
      continue
    }
    if (item.type === 'text') {
      const width = measureTextItemWidth(item)
      const height = item.height || TEXT_DEFAULT_HEIGHT
      const center = textItemCenter(item)
      const local = rotatePoint(point, center, -(item.rotation || 0))
      const scale = item.scale || 1
      const halfWidth = (width * scale) / 2 + tolerance
      const halfHeight = (height * scale) / 2 + tolerance
      if (Math.abs(local.x - center.x) <= halfWidth && Math.abs(local.y - center.y) <= halfHeight) return item
    }
  }
  return null
}

// ---------- 数字标记 ----------

/** 已圈选数字格 → 渲染单元（源 markedDigitCells computed） */
export function computeMarkedDigitCells(
  geometry: BoardGeometry,
  rows: BoardRow[],
  drawCount: number,
  markedDigitKeys: ReadonlySet<string>,
  markedDigitColors: Record<string, string>,
  activeColor: string,
): DigitCellTarget[] {
  const cells: DigitCellTarget[] = []
  rows.forEach((row, rowIndex) => {
    if (row.prediction) return
    const sumKey = digitCellKey(row.key, SUM_COLUMN_INDEX)
    if (markedDigitKeys.has(sumKey)) {
      const sumCell = digitCellAt(geometry, rows, rowIndex, SUM_COLUMN_INDEX, drawCount)
      if (sumCell) cells.push({ ...sumCell, color: markedDigitColors[sumKey] || activeColor })
    }
    for (let index = 0; index < drawCount; index += 1) {
      const key = digitCellKey(row.key, index)
      if (!markedDigitKeys.has(key)) continue
      cells.push({
        key,
        rowKey: row.key,
        rowIndex,
        columnIndex: index,
        value: row.numbers[index] || '',
        color: markedDigitColors[key] || activeColor,
        x: geometry.digitStartX + index * geometry.digitCellWidth + geometry.digitCellWidth / 2,
        y: rowIndex * geometry.rowHeight + geometry.rowHeight / 2,
      })
    }
  })
  return cells
}

export function computeSimplePredictionCells(
  geometry: BoardGeometry,
  rows: BoardRow[],
  drawCount: number,
  marks: SimplePredictionMark[],
): DigitCellTarget[] {
  const cells: DigitCellTarget[] = []
  marks.forEach((mark) => {
    const cell = cellCenterFromRowKey(geometry, rows, mark.rowKey, mark.columnIndex, drawCount)
    if (!cell) return
    cells.push({ ...cell, key: mark.id, value: mark.value, color: mark.color })
  })
  return cells
}

export function computePredictionRenderMarks(
  geometry: BoardGeometry,
  rows: BoardRow[],
  drawCount: number,
  marks: PredictionMark[],
): PredictionRenderMark[] {
  return marks
    .map((mark) => {
      const cell = cellCenterFromRowKey(geometry, rows, mark.rowKey, mark.columnIndex, drawCount)
      if (!cell) return null
      return { ...mark, rowIndex: cell.rowIndex, x: cell.x, y: cell.y }
    })
    .filter((mark): mark is PredictionRenderMark => Boolean(mark))
}

// ---------- 预测面板逻辑（源 2909 行 confirmPredictionPanel 等，纯前端） ----------

export function isFrontPredictionColumn(columnIndex: number, drawCount: number) {
  return columnIndex >= 0 && columnIndex <= 3 && columnIndex < drawCount
}

export function isSumColumnCell(cell?: DigitCellTarget | null) {
  return cell?.columnIndex === SUM_COLUMN_INDEX
}

/** 各前区列可选的高级条件（源 currentPredictionAdvancedOptions） */
export function predictionConditionsForColumn(columnIndex: number, drawCount: number): PredictionCondition[] {
  if (!isFrontPredictionColumn(columnIndex, drawCount)) return []
  const conditionValuesByColumn: Record<number, PredictionCondition[]> = {
    0: ['headTailSum', 'thousandHundredSum', 'thousandTenSum'],
    1: ['hundredTenSum', 'thousandHundredSum', 'hundredUnitSum'],
    2: ['hundredTenSum', 'thousandTenSum', 'tenUnitSum'],
    3: ['headTailSum', 'hundredUnitSum', 'tenUnitSum'],
  }
  return [...(conditionValuesByColumn[columnIndex] || []), ...PREDICTION_COMMON_CONDITIONS]
}

export function isFixedNumberCondition(condition: ActivePredictionCondition) {
  if (condition === 'none') return false
  return Boolean(PREDICTION_FIXED_NUMBER_SETS[condition])
}

export function isSinglePositionCondition(condition: ActivePredictionCondition) {
  return condition === 'kill' || condition === 'x' || isFixedNumberCondition(condition)
}

export function stablePredictionColumns(drawCount: number) {
  return [0, 1, 2, 3].filter((columnIndex) => columnIndex < drawCount)
}

export function predictionPositionForColumn(columnIndex: number) {
  const entry = Object.entries(PREDICTION_POSITION_COLUMNS).find(([, value]) => value === columnIndex)
  return entry?.[0] as PredictionPreviewPosition | undefined
}

export function predictionPositionsForCondition(condition: PredictionCondition) {
  return PREDICTION_CONDITION_POSITIONS[condition] || []
}

export function predictionColumnsForCondition(condition: PredictionCondition, drawCount: number) {
  return predictionPositionsForCondition(condition)
    .map((position) => PREDICTION_POSITION_COLUMNS[position])
    .filter((columnIndex, index, columns) => (
      columnIndex >= 0 && columnIndex < drawCount && columns.indexOf(columnIndex) === index
    ))
}

export function predictionPositionsForActiveCondition(
  condition: ActivePredictionCondition,
  cell: DigitCellTarget | null,
  drawCount: number,
): PredictionPreviewPosition[] {
  if (condition === 'none' || condition === 'x') {
    if (!cell || !isFrontPredictionColumn(cell.columnIndex, drawCount)) return []
    return [predictionPositionForColumn(cell.columnIndex)].filter((position): position is PredictionPreviewPosition =>
      Boolean(position)
    )
  }
  if (condition === 'stable') return PREDICTION_PREVIEW_ITEMS.map((item) => item.value)
  if (!isSinglePositionCondition(condition)) return predictionPositionsForCondition(condition)
  if (!cell || !isFrontPredictionColumn(cell.columnIndex, drawCount)) return []
  return [predictionPositionForColumn(cell.columnIndex)].filter((position): position is PredictionPreviewPosition =>
    Boolean(position)
  )
}

export function predictionColumnsForActiveCondition(
  condition: ActivePredictionCondition,
  cell: DigitCellTarget | null,
  drawCount: number,
): number[] {
  if (condition === 'none' || condition === 'x') {
    if (!cell || !isFrontPredictionColumn(cell.columnIndex, drawCount)) return []
    return [cell.columnIndex]
  }
  if (condition === 'stable') return stablePredictionColumns(drawCount)
  if (!isSinglePositionCondition(condition)) return predictionColumnsForCondition(condition, drawCount)
  if (!cell || !isFrontPredictionColumn(cell.columnIndex, drawCount)) return []
  return [cell.columnIndex]
}

export function predictionColumnsForMark(mark: PredictionMark, drawCount: number): number[] {
  const condition = mark.condition
  if (condition === 'none' || condition === 'x') return [mark.columnIndex]
  if (condition === 'stable') return stablePredictionColumns(drawCount)
  if (isSinglePositionCondition(condition)) return [mark.columnIndex]
  return predictionColumnsForCondition(condition, drawCount)
}

/** 稳码整行只落一列（源 predictionMarkColumnsForCommit） */
export function predictionMarkColumnsForCommit(condition: ActivePredictionCondition, columns: number[]) {
  if (condition === 'stable') return columns.length ? [columns[0]] : []
  return columns
}

export function currentPredictionLimit(condition: ActivePredictionCondition) {
  if (condition === 'none') return PREDICTION_DEFAULT_LIMIT
  if (isFixedNumberCondition(condition)) return PREDICTION_DEFAULT_LIMIT
  if (condition === 'kill') return PREDICTION_KILL_LIMIT
  if (condition === 'stable') return PREDICTION_STABLE_LIMIT
  return PREDICTION_DEFAULT_LIMIT
}

export function isPredictionSelectionComplete(condition: ActivePredictionCondition, numbers: string[]) {
  const count = numbers.length
  if (condition === 'x') return true
  if (isFixedNumberCondition(condition)) return count > 0
  if (condition === 'kill') return count === PREDICTION_KILL_LIMIT
  if (condition === 'stable') return count > 0 && count <= PREDICTION_STABLE_LIMIT
  return count > 0
}

/** 预测标记文本行（源 predictionTextLines；「稳上一码」前缀由调用方从 labels 拼接） */
export function predictionTextLines(
  mark: Pick<PredictionMark, 'conditionLabel' | 'numbers' | 'condition'>,
  stablePrefix: (numbers: string) => string,
) {
  if (mark.condition === 'x') return ['X']
  if (mark.condition === 'none') {
    return [mark.numbers.slice(0, 3).join(''), mark.numbers.slice(3, 6).join('')].filter(Boolean)
  }
  if (mark.condition === 'stable') return [stablePrefix(mark.numbers.slice(0, 2).join(''))]
  if (mark.condition === 'kill') {
    return [mark.conditionLabel, mark.numbers.slice(0, 2).join('')]
  }
  return [mark.conditionLabel, mark.numbers.slice(0, 3).join(''), mark.numbers.slice(3, 6).join('')]
}

// ---------- 导出裁剪 ----------

export function drawItemBoundsY(
  item: DrawItem,
  geometry: BoardGeometry,
  rows: BoardRow[],
  drawCount: number,
): { top: number; bottom: number } | null {
  const strokeOffset = Math.max(0, item.strokeWidth || 0) / 2
  if (item.type === 'polyline' || item.type === 'freeLine') {
    const points = item.lineKind === 'smart'
      ? smartLineRenderPoints(item, geometry, rows, drawCount)
      : item.points || []
    const yValues = points.filter((_, index) => index % 2 === 1).map((value) => value + (item.y || 0))
    if (!yValues.length) return null
    return { top: Math.min(...yValues) - strokeOffset, bottom: Math.max(...yValues) + strokeOffset }
  }
  if (item.type === 'circle') {
    const radiusY = item.radiusY || item.radius || 1
    return { top: (item.y || 0) - radiusY - strokeOffset, bottom: (item.y || 0) + radiusY + strokeOffset }
  }
  if (item.type === 'rect') {
    return { top: (item.y || 0) - strokeOffset, bottom: (item.y || 0) + (item.height || 1) + strokeOffset }
  }
  if (item.type === 'text') return textItemBoundsY(item)
  return null
}

export function textItemBoundsY(item: DrawItem) {
  const width = measureTextItemWidth(item)
  const height = item.height || TEXT_DEFAULT_HEIGHT
  const scale = item.scale || 1
  const center = textItemCenter(item)
  const left = item.x || 0
  const top = item.y || 0
  const corners = [
    { x: left, y: top },
    { x: left + width * scale, y: top },
    { x: left + width * scale, y: top + height * scale },
    { x: left, y: top + height * scale },
  ]
  const rotation = item.rotation || 0
  const yValues = corners.map((point) => rotatePoint(point, center, rotation).y)
  return { top: Math.min(...yValues), bottom: Math.max(...yValues) }
}

export function predictionMarkTopY(mark: PredictionRenderMark) {
  return mark.y - 27
}

/** 导出图片的裁剪顶行（源 exportContentTopY / userContentTopY） */
export function exportContentTopY(
  items: DrawItem[],
  markedCells: DigitCellTarget[],
  simpleCells: DigitCellTarget[],
  predictionMarks: PredictionRenderMark[],
  geometry: BoardGeometry,
  rows: BoardRow[],
  drawCount: number,
) {
  const yValues = [
    ...items.map((item) => {
      const bounds = drawItemBoundsY(item, geometry, rows, drawCount)
      return bounds ? bounds.top : Number.POSITIVE_INFINITY
    }),
    ...markedCells.map((cell) => cell.y - geometry.digitMarkRadius),
    ...simpleCells.map((cell) => cell.y - geometry.digitMarkRadius),
    ...predictionMarks.map(predictionMarkTopY),
  ].filter((value) => Number.isFinite(value))
  const topY = yValues.length ? Math.min(...yValues) : 0
  if (!Number.isFinite(topY)) return 0
  const rowTopY = Math.floor(Math.max(0, topY) / geometry.rowHeight) * geometry.rowHeight
  return clamp(rowTopY, 0, Math.max(0, geometry.boardHeight - geometry.rowHeight))
}

// ---------- 绘制引擎共享接口（engine.h5.tsx / engine.rn.tsx 同一签名） ----------

export interface DrawEngineProps {
  geometry: BoardGeometry
  rows: BoardRow[]
  drawCount: number
  items: DrawItem[]
  digitMarks: DigitCellTarget[]
  predictionMarks: PredictionRenderMark[]
  previewStartCells: DigitCellTarget[]
  previewTargetCells: DigitCellTarget[]
  draft: DraftState | null
  /** 画规模式=true；滚动模式=false（引擎不拦截手势） */
  interactive: boolean
  /** 当前滚动偏移（H5 视窗化渲染用；RN 全量渲染忽略） */
  scrollTop: number
  activeTool: DrawTool
  activeSmartControlLineId: string | null
  activeTextItemId: string | null
  smartPenEnabled: boolean
  /** 稳码标记的整行宽度前缀列起始 x（digitStartX）由 geometry 提供 */
  onPointerDown(point: DrawPoint, hit: DrawEngineHit): void
  onPointerMove(point: DrawPoint): void
  onPointerUp(point: DrawPoint | null): void
  onTap(point: DrawPoint, hit: DrawEngineHit): void
  /** RN 拖拽过程中的实时位置回传（H5 由 Konva draggable 原生处理，不回调） */
  onItemDragMove?(id: string, position: DrawPoint): void
  onItemDragEnd(id: string, position: DrawPoint): void
  /** 智能线控制点拖拽：final=false 为过程值（RN 用），final=true 为落定 */
  onSmartControlDrag(id: string, point: DrawPoint, final: boolean): void
  /** 双击（H5）/ 长按（RN）编辑文字 */
  onTextEdit(id: string): void
  /** 文字「实/透」切换（H5 控制钮） */
  onTextOpacityToggle(id: string): void
  /** 文字旋转/缩放落定（H5 控制钮；patch 由引擎按模型计算） */
  onTextTransform(id: string, patch: Partial<DrawItem>): void
}

export interface DrawEngineRef {
  /** 导出整张画规图（奖表背景 + 全部绘制内容）为 PNG dataURL；失败返回 null */
  capturePngDataURL(): Promise<string | null>
}
