.live-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

/* ---------- 品牌条 ---------- */

.brand-strip {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
}

.brand-strip__title {
  font-size: 20px;
  font-weight: 700;
}

.brand-strip__schedule {
  font-size: 13px;
  color: var(--color-text-secondary);
}

/* ---------- 播放器卡 ---------- */

.player {
  margin: 0 16px 8px;
  padding: 20px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.player__head {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: space-between;
}

.player__head-main {
  flex: 1;
  min-width: 0;
  margin-right: 12px;
}

.player__title {
  display: block;
  font-size: 18px;
  font-weight: 700;
}

.player__desc {
  display: block;
  margin-top: 6px;
  font-size: 13px;
  color: var(--color-text-secondary);
}

.player__status {
  display: flex;
  flex-direction: row;
  align-items: center;
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--color-bg);
  flex-shrink: 0;
}

.player__status--live {
  background: var(--color-primary-light);
}

.player__status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-text-placeholder);
  margin-right: 6px;
}

.player__status--live .player__status-dot {
  background: var(--color-primary);
}

.player__status-text {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.player__status--live .player__status-text {
  color: var(--color-primary);
}

.player__meta {
  display: flex;
  flex-direction: row;
  margin-top: 12px;
}

.player__meta-item {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-right: 16px;
}

.player__frame {
  margin-top: 14px;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: #080a10;
}

.player__media {
  width: 100%;
  height: 220px;
  display: block;
  background: #000;
}

.player__placeholder {
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background-color: #0f1320; /* RN 端不支持渐变，降级为纯色 */
  background-image: linear-gradient(160deg, #05070d 0%, #0f1320 56%, #171f30 100%);
}

.player__placeholder-name {
  font-size: 24px;
  font-weight: 700;
  color: #fff;
}

.player__placeholder-hint {
  margin-top: 12px;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.74);
}

.player__placeholder-countdown {
  margin-top: 12px;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: 2px;
  color: #fff;
}

.player__placeholder-btn {
  margin-top: 20px;
  min-height: 44px;
  padding: 0 28px;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-primary);
}

.player__placeholder-btn-text {
  font-size: 14px;
  color: #fff;
}

/* ---------- 其他直播源 ---------- */

.source-row {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  padding-top: 16px;
}

.source-row__label {
  font-size: 13px;
  color: var(--color-text-placeholder);
}

.source-row__link {
  min-height: 44px;
  display: flex;
  align-items: center;
  margin-right: 16px;
  font-size: 13px;
  color: var(--color-primary);
}

/* ---------- 频道列表 ---------- */

.channel-card {
  margin: 8px 16px 0;
  padding: 8px 20px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.channel-card__title {
  display: block;
  padding: 12px 0;
  font-size: 15px;
  font-weight: 600;
  border-bottom: 1px solid var(--color-border);
}

.channel-item {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 44px;
  padding: 12px 0;
  border-bottom: 1px solid var(--color-border);
}

.channel-item:last-child {
  border-bottom-width: 0; /* RN 端不支持 border-bottom: none */
}

.channel-item--active {
  background: var(--color-primary-light);
  border-radius: var(--radius-sm);
}

.channel-item__icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background-color: #f0ae1e; /* RN 端不支持渐变，降级为纯色 */
  background-image: linear-gradient(160deg, #ffe5a2 0%, #f0ae1e 48%, #a36710 100%);
}

.channel-item:nth-child(3) .channel-item__icon {
  background-color: #8a84ff; /* RN 端不支持渐变，降级为纯色 */
  background-image: linear-gradient(160deg, #e8e7ff 0%, #8a84ff 46%, #363fb0 100%);
}

.channel-item:nth-child(4) .channel-item__icon {
  background-color: #ff8fab; /* RN 端不支持渐变，降级为纯色 */
  background-image: linear-gradient(160deg, #ffe7ee 0%, #ff8fab 46%, #d63f6d 100%);
}

.channel-item__icon-text {
  font-size: 15px;
  font-weight: 800;
  color: #2a2244;
}

.channel-item:nth-child(3) .channel-item__icon-text,
.channel-item:nth-child(4) .channel-item__icon-text {
  color: #fff;
}

.channel-item__copy {
  flex: 1;
  min-width: 0;
  margin-left: 14px;
}

.channel-item__name {
  display: block;
  font-size: 15px;
  font-weight: 600;
}

.channel-item__schedule {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  color: var(--color-text-placeholder);
}
