/* 画规工具页样式（RN 约束：无 grid/gap/box-shadow，圆角用数值，安全区用 var(--sa-N, ...)） */

.draw-rule-page {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: #eef0f2;
}

/* H5：禁用页面级滚动后撑满视口（RN 端 100vh 会转整窗高度，单独类隔离） */
.draw-rule-page--h5 {
  height: 100vh;
  overflow: hidden;
}

/* ---------- 顶部工具条 ---------- */

.draw-rule-toolbar {
  display: flex;
  flex-direction: row;
  height: 48px;
  background: #ffffff;
  border-bottom-width: 1px;
  border-bottom-color: #e5e7eb;
}

.draw-rule-toolbar__btn {
  flex: 1;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-rule-toolbar__text {
  font-size: 15px;
  font-weight: 700;
  color: #242832;
}

.draw-rule-toolbar__btn.is-disabled .draw-rule-toolbar__text {
  color: #b9b9b9;
}

/* ---------- 奖表区 ---------- */

.draw-rule-body {
  flex: 1;
  position: relative;
  overflow: hidden;
}

.draw-rule-scroll {
  height: 100%;
}

.draw-rule-loading {
  flex: 1;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-rule-loading__text {
  font-size: 15px;
  color: #6b7280;
}

.draw-rule-board {
  position: relative;
  background: #f8fff4;
  border-width: 1px;
  border-color: rgba(110, 155, 104, 0.22);
}

.draw-board__row {
  display: flex;
  flex-direction: row;
}

.draw-board__issue {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #8dc17b;
}

.draw-board__issue-num {
  color: #ffffff;
  font-weight: 700;
  line-height: 1.2;
}

.draw-board__issue-week {
  color: #ffffff;
  font-weight: 700;
  line-height: 1.2;
}

.draw-board__sum {
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f0ffd1;
  border-right-width: 2px;
  border-right-color: #77a86e;
}

.draw-board__sum-text {
  color: #85bc7d;
  font-weight: 700;
}

.draw-board__digit {
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-board__digit-text {
  color: #88bd83;
  font-weight: 700;
  line-height: 1;
}

/* ---------- H5 Konva 引擎容器（RN 端引擎用内联样式 + PanResponder） ---------- */

.draw-rule-engine {
  position: absolute;
  left: 0;
  z-index: 2;
  touch-action: none;
}

.draw-rule-engine.is-scroll-mode {
  pointer-events: none;
  touch-action: pan-y;
}

.draw-rule-engine__host {
  width: 100%;
  height: 100%;
}

/* ---------- 文字编辑输入框（双端） ---------- */

.draw-text-editor {
  position: absolute;
  z-index: 4;
  width: 200px;
  height: 44px;
  padding-left: 10px;
  padding-right: 10px;
  border-width: 2px;
  border-style: solid;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.94);
  font-size: 20px;
  font-weight: 700;
}

/* ---------- 底部悬浮钮 ---------- */

.draw-rule-fab {
  position: absolute;
  z-index: 6;
  bottom: var(--sa-12, calc(12px + env(safe-area-inset-bottom)));
  display: flex;
  flex-direction: row;
  align-items: center;
}

.draw-rule-fab--color {
  left: 10px;
  width: 50px;
  height: 50px;
  border-radius: 25px;
  border-width: 6px;
  border-color: rgba(90, 90, 90, 0.86);
  background: #ffffff;
  justify-content: center;
}

.draw-rule-fab__color-dot {
  width: 22px;
  height: 22px;
  border-radius: 11px;
}

.draw-rule-fab--lock {
  left: 50%;
  margin-left: -25px;
  width: 50px;
  height: 50px;
  border-radius: 25px;
  background: rgba(82, 82, 82, 0.78);
  justify-content: center;
}

.draw-rule-fab__lock-text {
  color: #ffffff;
  font-size: 20px;
}

.draw-rule-fab--tool {
  right: 10px;
  height: 50px;
  border-radius: 25px;
  background: rgba(78, 78, 78, 0.86);
}

.draw-rule-fab__smart {
  height: 50px;
  min-width: 64px;
  padding-left: 14px;
  padding-right: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-right-width: 1px;
  border-right-color: rgba(255, 255, 255, 0.45);
}

.draw-rule-fab__smart-text {
  color: #ffffff;
  font-size: 15px;
  font-weight: 700;
}

.draw-rule-fab__tool-btn {
  width: 50px;
  height: 50px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-rule-fab__tool-icon {
  color: #ffffff;
  font-size: 22px;
  font-weight: 700;
}

/* ---------- Popup 面板通用 ---------- */

.draw-sheet {
  padding: 14px 16px var(--sa-16, calc(16px + env(safe-area-inset-bottom)));
  background: #ffffff;
}

.draw-sheet__header {
  position: relative;
  min-height: 48px;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
}

.draw-sheet__title {
  font-size: 17px;
  font-weight: 700;
  color: #30343b;
}

.draw-sheet__close {
  position: absolute;
  right: 0;
  top: -4px;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-sheet__close-text {
  font-size: 22px;
  color: #6b7280;
}

.draw-sheet__tool-grid {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  margin-top: 12px;
}

.draw-sheet__tool {
  width: 33.33%;
  height: 64px;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  border-bottom-width: 1px;
  border-bottom-color: #f0f1f3;
}

.draw-sheet__tool.is-active {
  background: #f9efef;
}

.draw-sheet__tool-icon {
  font-size: 18px;
  font-weight: 700;
  color: #4b5563;
  margin-right: 6px;
}

.draw-sheet__tool.is-active .draw-sheet__tool-icon,
.draw-sheet__tool.is-active .draw-sheet__tool-name {
  color: #b83237;
}

.draw-sheet__tool-name {
  font-size: 14px;
  font-weight: 700;
  color: #374151;
}

.draw-sheet__smart-entry {
  margin-top: 12px;
  height: 44px;
  border-radius: 8px;
  background: #b83237;
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-sheet__smart-entry-text {
  color: #ffffff;
  font-size: 15px;
  font-weight: 700;
}

/* 颜色 / 线宽 */

.draw-sheet__color-grid {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  margin-top: 12px;
}

.draw-sheet__color {
  width: 44px;
  height: 44px;
  margin-right: 12px;
  margin-bottom: 12px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-sheet__color.is-active {
  border-width: 2px;
  border-color: #1f2937;
}

.draw-sheet__color-check {
  color: #ffffff;
  font-size: 18px;
  font-weight: 700;
}

.draw-sheet__stroke-row {
  display: flex;
  flex-direction: row;
  margin-top: 4px;
}

.draw-sheet__stroke {
  flex: 1;
  height: 48px;
  margin-right: 10px;
  border-radius: 8px;
  background: #f5f6f8;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.draw-sheet__stroke.is-active {
  background: #f9efef;
  border-width: 1px;
  border-color: #b83237;
}

.draw-sheet__stroke-line {
  width: 28px;
  background: #374151;
  border-radius: 2px;
}

.draw-sheet__stroke-label {
  margin-top: 4px;
  font-size: 12px;
  color: #374151;
}

/* 设置行 */

.draw-sheet__row {
  margin-top: 14px;
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
}

.draw-sheet__row-label {
  width: 64px;
  font-size: 15px;
  font-weight: 700;
  color: #374151;
}

.draw-sheet__row-hint {
  flex: 1;
  font-size: 12px;
  color: #b6b6b6;
}

.draw-sheet__options {
  flex: 1;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
}

.draw-sheet__option {
  min-width: 58px;
  height: 44px;
  padding-left: 12px;
  padding-right: 12px;
  margin-right: 10px;
  margin-bottom: 8px;
  border-width: 1px;
  border-color: #e6e9ef;
  border-radius: 4px;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-sheet__option.is-active {
  border-color: #b83237;
  background: #f9efef;
}

.draw-sheet__option.is-disabled {
  background: #fafafa;
  border-color: #eef1f5;
}

.draw-sheet__option.is-disabled .draw-sheet__option-text {
  color: #c3c7cf;
}

.draw-sheet__option-text {
  font-size: 14px;
  font-weight: 700;
  color: #374151;
}

.draw-sheet__option.is-active .draw-sheet__option-text {
  color: #b83237;
}

.draw-sheet__switch-hit {
  min-width: 58px;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
}

.draw-sheet__switch {
  width: 50px;
  height: 28px;
  border-radius: 14px;
  background: #e5e7eb;
  padding: 3px;
}

.draw-sheet__switch.is-on {
  background: #b83237;
}

.draw-sheet__switch-dot {
  width: 22px;
  height: 22px;
  border-radius: 11px;
  background: #ffffff;
}

.draw-sheet__switch.is-on .draw-sheet__switch-dot {
  margin-left: 22px;
}

.draw-sheet__confirm {
  margin-top: 16px;
  height: 46px;
  border-radius: 8px;
  background: #b83237;
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-sheet__confirm.is-disabled {
  background: #e5c0c2;
}

.draw-sheet__confirm-text {
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
}

/* ---------- 数字选择器 ---------- */

.draw-sheet--prediction {
  padding-bottom: var(--sa-16, calc(16px + env(safe-area-inset-bottom)));
}

.draw-sheet__mode-switch {
  position: absolute;
  right: 44px;
  top: 0;
  display: flex;
  flex-direction: row;
  background: #f0f1f3;
  border-radius: 6px;
  padding: 2px;
}

.draw-sheet__mode {
  min-width: 52px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
}

.draw-sheet__mode.is-active {
  background: #ffffff;
}

.draw-sheet__mode-text {
  font-size: 14px;
  font-weight: 700;
  color: #b6bcc5;
}

.draw-sheet__mode.is-active .draw-sheet__mode-text {
  color: #b83237;
}

.draw-sheet__prediction-scroll {
  max-height: 60vh;
  margin-top: 12px;
}

.draw-sheet__prediction-body {
  display: flex;
  flex-direction: column;
}

.draw-sheet__section-label {
  font-size: 15px;
  font-weight: 700;
  color: #111827;
  margin-top: 12px;
  margin-bottom: 8px;
}

.draw-sheet__number-grid {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
}

.draw-sheet__number {
  width: 44px;
  height: 44px;
  margin-right: 10px;
  margin-bottom: 10px;
  border-radius: 4px;
  background: #f5f6f8;
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-sheet__number.is-active {
  background: #b83237;
}

.draw-sheet__number.is-disabled {
  opacity: 0.5;
}

.draw-sheet__number-text {
  font-size: 15px;
  font-weight: 700;
  color: #0f172a;
}

.draw-sheet__number.is-active .draw-sheet__number-text {
  color: #ffffff;
}

.draw-sheet__fill-row {
  display: flex;
  flex-direction: row;
}

.draw-sheet__fill {
  display: flex;
  flex-direction: row;
  align-items: center;
  height: 44px;
  margin-right: 28px;
}

.draw-sheet__fill-dot {
  width: 18px;
  height: 18px;
  border-radius: 9px;
  margin-right: 8px;
  background: #f0f1f3;
}

.draw-sheet__fill.is-active .draw-sheet__fill-dot--solid {
  background: #8c8c8c;
}

.draw-sheet__fill.is-active .draw-sheet__fill-dot--hollow {
  background: #8c8c8c;
  border-width: 4px;
  border-color: #8c8c8c;
}

.draw-sheet__fill-text {
  font-size: 14px;
  font-weight: 700;
  color: #0f172a;
}

.draw-sheet__preview-row {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
}

.draw-sheet__preview-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-right: 10px;
  margin-bottom: 8px;
}

.draw-sheet__preview-card {
  width: 64px;
  height: 64px;
  border-radius: 7px;
  background: #f2f3f5;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-width: 1px;
  border-color: #f2f3f5;
}

.draw-sheet__preview-card.is-stable {
  width: 220px;
}

.draw-sheet__preview-card.is-hollow {
  background: #ffffff;
}

.draw-sheet__preview-line {
  font-size: 13px;
  font-weight: 700;
  color: #ffffff;
  line-height: 1.2;
}

.draw-sheet__preview-label {
  margin-top: 5px;
  font-size: 12px;
  color: #8a8f98;
}
