import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * 验证码发送倒计时（登录/注册/忘记密码页 + 修改密码弹层共用）：
 * - start() 幂等：先清掉旧计时器再开新的，慢网下重复点击不会叠出多个 interval
 *   （旧实现不清理旧 interval，双重发送后倒计时倍速递减直至变负并永久泄漏）
 * - 卸载自动清理；常驻组件（如弹层）关闭时应手动调 stop()，不留 1Hz 空转计时器
 */
export function useSmsCountdown(seconds = 60) {
  const [countdown, setCountdown] = useState(0)
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null)

  const stop = useCallback(() => {
    if (timerRef.current) {
      clearInterval(timerRef.current)
      timerRef.current = null
    }
  }, [])

  useEffect(() => stop, [stop])

  const start = useCallback(() => {
    stop()
    setCountdown(seconds)
    timerRef.current = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          stop()
          return 0
        }
        return prev - 1
      })
    }, 1000)
  }, [seconds, stop])

  return { countdown, start, stop }
}
