import { useState } from 'react'
import { View, Text, Textarea } from '@tarojs/components'
import { publishLabels } from '@/labels/publish'
import {
  countNumberTokens,
  findNonNumericTokens,
  FREE_MODE_BASE_MIN,
  FREE_MODE_FOCUS_RATIO,
  FREE_MODE_MAIN_RATIO,
} from '@/utils/freeMode'
import ChipGroup from '../ChipGroup'
import type { DimensionCode } from '@/constants/forecast'
import type { FreeRangeType } from '../types'
import './index.css'

interface FreeModePanelsProps {
  dimension: DimensionCode
  rangeType: FreeRangeType
  base: string
  focus: string
  main: string
  onRangeChange: (value: FreeRangeType) => void
  onBaseChange: (value: string) => void
  onFocusChange: (value: string) => void
  onMainChange: (value: string) => void
}

type SectionKey = 'base' | 'focus' | 'main'

/** 自由模式三栏（大底/重点/主攻）折叠面板，校验提示内联显示（产品方案 §6.6、Web PRD §12.3） */
export default function FreeModePanels({
  dimension,
  rangeType,
  base,
  focus,
  main,
  onRangeChange,
  onBaseChange,
  onFocusChange,
  onMainChange,
}: FreeModePanelsProps) {
  // 默认仅展开大底
  const [expanded, setExpanded] = useState<Record<SectionKey, boolean>>({ base: true, focus: false, main: false })

  const baseCount = countNumberTokens(base)
  const focusCount = countNumberTokens(focus)
  const mainCount = countNumberTokens(main)
  const focusLimit = Math.floor(baseCount * FREE_MODE_FOCUS_RATIO)
  const mainLimit = Math.floor(baseCount * FREE_MODE_MAIN_RATIO)

  const baseInvalid = findNonNumericTokens(base)
  const focusInvalid = findNonNumericTokens(focus)
  const mainInvalid = findNonNumericTokens(main)

  const rangeOptions = publishLabels.rangeOptionsByDimension[dimension] || []

  const sections: Array<{
    key: SectionKey
    label: string
    value: string
    placeholder: string
    hint: string
    over: boolean
    invalid: string[]
    onChange: (value: string) => void
  }> = [
    {
      key: 'base',
      label: publishLabels.freeBase,
      value: base,
      placeholder: publishLabels.freeBasePlaceholder,
      hint: publishLabels.baseHint(baseCount, FREE_MODE_BASE_MIN),
      over: baseCount > 0 && baseCount < FREE_MODE_BASE_MIN,
      invalid: baseInvalid,
      onChange: onBaseChange,
    },
    {
      key: 'focus',
      label: publishLabels.freeFocus,
      value: focus,
      placeholder: publishLabels.freeFocusPlaceholder,
      hint: publishLabels.focusHint(focusCount, focusLimit),
      over: focusCount > focusLimit,
      invalid: focusInvalid,
      onChange: onFocusChange,
    },
    {
      key: 'main',
      label: publishLabels.freeMain,
      value: main,
      placeholder: publishLabels.freeMainPlaceholder,
      hint: publishLabels.mainHint(mainCount, mainLimit),
      over: mainCount > mainLimit,
      invalid: mainInvalid,
      onChange: onMainChange,
    },
  ]

  return (
    <View className='free-mode'>
      {rangeOptions.length ? (
        <View className='free-mode__range'>
          <Text className='free-mode__range-label'>{publishLabels.rangeLabel}</Text>
          <ChipGroup options={rangeOptions} value={rangeType} onChange={(v) => onRangeChange(v as FreeRangeType)} />
        </View>
      ) : null}

      {sections.map((section) => (
        <View key={section.key} className='free-panel'>
          <View
            className='free-panel__head'
            onClick={() => setExpanded((prev) => ({ ...prev, [section.key]: !prev[section.key] }))}
          >
            <Text className='free-panel__label'>{section.label}</Text>
            <Text className={`free-panel__hint${section.over || section.invalid.length ? ' free-panel__hint--over' : ''}`}>
              {section.hint}
            </Text>
            <Text className='free-panel__arrow'>{expanded[section.key] ? '▾' : '▸'}</Text>
          </View>
          {expanded[section.key] ? (
            <View className='free-panel__body'>
              <Textarea
                className={`free-panel__textarea free-panel__textarea--${section.key}`}
                value={section.value}
                placeholder={section.placeholder}
                maxlength={-1}
                onInput={(e) => section.onChange(e.detail.value)}
              />
              {section.invalid.length ? (
                <Text className='free-panel__error'>
                  {publishLabels.nonNumeric(section.label, section.invalid.join(' '))}
                </Text>
              ) : null}
            </View>
          ) : null}
        </View>
      ))}
    </View>
  )
}
