.sp-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

.sp-card {
  margin: 16px;
  padding: 20px 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.sp-label {
  display: block;
  margin: 16px 0 8px;
  font-size: 15px;
  font-weight: 600;
  color: var(--color-text);
}

.sp-card .sp-label:first-child {
  margin-top: 0;
}

.sp-label-row {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  margin: 16px 0 8px;
}

.sp-label-row .sp-label {
  margin: 0;
  margin-right: 8px;
}

.sp-hint {
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.5;
}

.sp-tip {
  display: block;
  margin-top: 8px;
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.5;
}

/* Chips 单选（与 history-review 同款） */
.chips {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 16px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.chip--active {
  background: var(--color-primary-light);
}

.chip__text {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.chip__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

/* 号码组输入 */
.sp-textarea {
  width: 100%;
  min-height: 120px;
  padding: 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
  font-size: 14px;
  box-sizing: border-box;
}

/* 交换号码组 */
.sp-swap-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 12px 0;
}

.sp-swap-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 22px;
  background: var(--color-primary-light);
}

.sp-swap-btn__icon {
  font-size: 20px;
  color: var(--color-primary);
}

/* 操作按钮 */
.sp-actions {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin-top: 24px;
}

.sp-result-actions {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--color-border);
}

.sp-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  border-radius: 999px;
  background: var(--color-primary);
}

.sp-btn--plain {
  background: var(--color-bg);
}

.sp-btn__text {
  font-size: 15px;
  font-weight: 600;
  color: #fff;
}

.sp-btn__text--plain {
  color: var(--color-text-secondary);
}

/* 结果区 */
.sp-result-head {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  justify-content: space-between;
}

.sp-result-head .sp-label {
  margin-top: 0;
}

.sp-result-count {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-primary);
}

.sp-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 44px;
  border-top: 1px solid var(--color-border);
}

.sp-row--head {
  border-top-width: 0; /* RN 端不支持 border-top: none */
}

.sp-row--head .sp-row__index,
.sp-row--head .sp-row__code {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.sp-row__index {
  width: 64px;
  font-size: 13px;
  color: var(--color-text-secondary);
}

.sp-row__code {
  flex: 1;
  font-size: 14px;
  color: var(--color-text);
  letter-spacing: 1px;
}

/* 加载更多 */
.load-more {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
}

.load-more__text {
  font-size: 13px;
  color: var(--color-primary);
}

/* 复制弹层 */
.sp-sheet {
  padding: 16px 16px var(--sa-16, calc(16px + env(safe-area-inset-bottom)));
}

.sp-sheet__title {
  display: block;
  text-align: center;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 12px;
}

.sp-copy-preview {
  max-height: 30vh;
  padding: 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
}

.sp-copy-preview__text {
  font-size: 13px;
  color: var(--color-text);
  line-height: 1.6;
}

.sp-sheet__settings {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 16px;
}

.sp-sheet__actions {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin-top: 20px;
}
