import { useCallback, useEffect, useRef, useState } from 'react'
import { ScrollView, Text, View } from '@tarojs/components'
import Taro, { usePullDownRefresh } from '@tarojs/taro'
import Popup from '@/components/SheetPopup'
import { LOTTERY_OPTIONS, RANK_TYPE_OPTIONS } from '@/constants/lottery'
import {
  FORECAST_DIMENSION_OPTIONS,
  getCodeModeOptions,
  getPrecisionOptions,
  toBackendCodeMode,
  type DimensionCode,
  type ForecastLotteryCode,
} from '@/constants/forecast'
import { fetchExpertRank, fetchIsFollowing } from '@/services/api'
import { useAuth } from '@/store/auth'
import { goExpert } from '@/utils/nav'
import { rankLabels } from '@/labels/rank'
import { commonLabels } from '@/labels'
import type { Expert } from '@/types'
import Avatar from '@/components/Avatar'
import FollowButton from '@/components/FollowButton'
import Skeleton from '@/components/Skeleton'
import Empty from '@/components/Empty'
import './index.css'

/** 排行榜筛选（Web PRD §6.4）：彩种/统计期数为必需参数取默认首项，其余默认空值不筛选 */
interface RankFilters {
  lotteryCode: string
  rankType: string
  rankCategory: string
  forecastPhase: string
  dimension: string
  codeMode: string
  precision: string
  followFilter: string
}

const DEFAULT_FILTERS: RankFilters = {
  lotteryCode: '350133',
  rankType: '10',
  rankCategory: '',
  forecastPhase: '',
  dimension: '',
  codeMode: '',
  precision: '',
  followFilter: '',
}

/** 位置/选号规模选项失效时自动清空已选值（彩种或维度变化后原选项可能不存在） */
function sanitizeFilters(filters: RankFilters): RankFilters {
  const next = { ...filters }
  const codeModes = next.dimension
    ? getCodeModeOptions(next.lotteryCode as ForecastLotteryCode, next.dimension as DimensionCode)
    : []
  if (next.codeMode && !codeModes.includes(next.codeMode)) next.codeMode = ''
  const precisions = getPrecisionOptions(next.dimension as DimensionCode | '')
  if (next.precision && !precisions.includes(next.precision)) next.precision = ''
  return next
}

interface ChipOption {
  label: string
  value: string
}

/** 排行榜（产品方案 §6.3）：两行横滑筛选条 + 弹层面板收纳剩余维度，卡片列表 + 下拉刷新 */
export default function RankPage() {
  const { isLoggedIn } = useAuth()
  const [filters, setFilters] = useState<RankFilters>(DEFAULT_FILTERS)
  const [draft, setDraft] = useState<RankFilters>(DEFAULT_FILTERS)
  const [panelVisible, setPanelVisible] = useState(false)
  const [experts, setExperts] = useState<Expert[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [followMap, setFollowMap] = useState<Record<string, boolean>>({})
  const seqRef = useRef(0)

  const loadRank = useCallback(async (f: RankFilters) => {
    const seq = ++seqRef.current
    setLoading(true)
    setError('')
    try {
      const list = await fetchExpertRank({
        lotteryCode: f.lotteryCode || undefined,
        rankType: f.rankType || undefined,
        forecastPhase: f.forecastPhase || undefined,
        planMode: f.dimension || undefined,
        codeMode: toBackendCodeMode(f.codeMode) || undefined,
        precision: f.precision || undefined,
        identity: 'T',
        followFilter: f.followFilter || undefined,
        rankCategory: f.rankCategory || undefined,
      })
      if (seq !== seqRef.current) return
      setExperts(list || [])
      setFollowMap({}) // 列表刷新后关注态重新逐行补齐
    } catch (err: any) {
      if (seq !== seqRef.current) return
      setExperts([])
      setError(err?.message || rankLabels.loadFailed)
    } finally {
      if (seq === seqRef.current) setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadRank(DEFAULT_FILTERS)
  }, [loadRank])

  usePullDownRefresh(async () => {
    await loadRank(filters)
    Taro.stopPullDownRefresh()
  })

  // 登录后逐行补关注态（静默失败忽略，对齐首页实现）
  useEffect(() => {
    if (!isLoggedIn || experts.length === 0) return
    experts.forEach((expert) => {
      const key = String(expert.id)
      fetchIsFollowing(expert.id)
        .then((res) => {
          if (typeof res?.followed === 'boolean') {
            setFollowMap((prev) => (key in prev ? prev : { ...prev, [key]: res.followed }))
          }
        })
        .catch(() => {})
    })
  }, [isLoggedIn, experts])

  /** 顶部筛选条点击：立即生效并请求（不做防抖） */
  const applyTopFilter = useCallback(
    (patch: Partial<RankFilters>) => {
      setFilters((prev) => {
        const next = sanitizeFilters({ ...prev, ...patch })
        loadRank(next)
        return next
      })
    },
    [loadRank],
  )

  const openPanel = useCallback(() => {
    setDraft(filters)
    setPanelVisible(true)
  }, [filters])

  /** 面板内草稿改动：位置/选号规模随维度联动清空失效值，确定前不发请求 */
  const patchDraft = useCallback((patch: Partial<RankFilters>) => {
    setDraft((prev) => sanitizeFilters({ ...prev, ...patch }))
  }, [])

  const confirmPanel = useCallback(() => {
    setFilters(draft)
    setPanelVisible(false)
    loadRank(draft)
  }, [draft, loadRank])

  const resetPanel = useCallback(() => {
    setDraft((prev) => ({ ...prev, dimension: '', codeMode: '', precision: '', followFilter: '' }))
  }, [])

  /** 弹层面板生效的筛选数（用于筛选按钮角标提示） */
  const panelActiveCount = [filters.dimension, filters.codeMode, filters.precision, filters.followFilter].filter(
    Boolean,
  ).length

  const renderChips = (
    options: readonly ChipOption[],
    current: string,
    onPick: (value: string) => void,
    clearable = true,
  ) => (
    <>
      {options.map((item) => (
        <View
          key={item.value}
          className={`chip${item.value === current ? ' chip--active' : ''}`}
          onClick={() => onPick(clearable && item.value === current ? '' : item.value)}
        >
          <Text className={`chip__text${item.value === current ? ' chip__text--active' : ''}`}>{item.label}</Text>
        </View>
      ))}
    </>
  )

  const draftCodeModes = draft.dimension
    ? getCodeModeOptions(draft.lotteryCode as ForecastLotteryCode, draft.dimension as DimensionCode).map((mode) => ({
        label: mode,
        value: mode,
      }))
    : []
  const draftPrecisions = getPrecisionOptions(draft.dimension as DimensionCode | '').map((value) => ({
    label: value,
    value,
  }))

  return (
    <View className='rank-page'>
      {/* 顶部两行横滑筛选条（产品方案 §6.3） */}
      <View className='filter-bars'>
        <ScrollView scrollX className='filter-bar'>
          <View className='filter-bar__inner'>
            <Text className='filter-bar__label'>{rankLabels.groups.lottery}</Text>
            {renderChips(LOTTERY_OPTIONS, filters.lotteryCode, (value) => applyTopFilter({ lotteryCode: value || '350133' }), false)}
            <Text className='filter-bar__label'>{rankLabels.groups.rankType}</Text>
            {renderChips(RANK_TYPE_OPTIONS, filters.rankType, (value) => applyTopFilter({ rankType: value || '10' }), false)}
          </View>
        </ScrollView>
        <ScrollView scrollX className='filter-bar'>
          <View className='filter-bar__inner'>
            <Text className='filter-bar__label'>{rankLabels.groups.rankCategory}</Text>
            {renderChips(rankLabels.rankCategoryOptions, filters.rankCategory, (value) => applyTopFilter({ rankCategory: value }))}
            <Text className='filter-bar__label'>{rankLabels.groups.forecastPhase}</Text>
            {renderChips(rankLabels.forecastPhaseOptions, filters.forecastPhase, (value) => applyTopFilter({ forecastPhase: value }))}
            <View className='filter-trigger' onClick={openPanel}>
              <Text className='filter-trigger__text'>
                {rankLabels.filter}
                {panelActiveCount > 0 ? ` ·${panelActiveCount}` : ''}
              </Text>
            </View>
          </View>
        </ScrollView>
      </View>

      {/* 榜单卡片列表（rank 接口一次返回全量，无上拉加载） */}
      {loading && experts.length === 0 ? (
        <Skeleton rows={5} />
      ) : error && experts.length === 0 ? (
        <Empty text={error} actionText={commonLabels.networkError} onAction={() => loadRank(filters)} />
      ) : experts.length === 0 ? (
        <Empty text={rankLabels.empty} />
      ) : (
        experts.map((expert) => {
          const followed = followMap[String(expert.id)] ?? !!expert.isFollowed
          const badge = expert.rankBadge ?? expert.rank
          const trendText =
            expert.recentTrend === 'up'
              ? rankLabels.trend.up
              : expert.recentTrend === 'down'
                ? rankLabels.trend.down
                : rankLabels.trend.stable
          return (
            <View key={expert.id} className='expert-card' onClick={() => goExpert(expert.id)}>
              <View className='expert-card__head'>
                <Text className={`expert-card__badge${badge >= 1 && badge <= 3 ? ` expert-card__badge--${badge}` : ''}`}>
                  {badge}
                </Text>
                <Avatar src={expert.avatar} name={expert.nickName} size={44} />
                <View className='expert-card__info'>
                  <View className='expert-card__name-row'>
                    <Text className='expert-card__name'>{expert.nickName}</Text>
                    {expert.isVerified ? <Text className='expert-card__verified'>{rankLabels.verified}</Text> : null}
                  </View>
                  <View className='expert-card__meta'>
                    <Text className='expert-card__rate'>
                      {rankLabels.winRate} {expert.winRate}%
                    </Text>
                    {filters.rankCategory === 'subscribe' ? (
                      <Text className='expert-card__meta-item'>{rankLabels.subscribeCount(expert.fanCount ?? 0)}</Text>
                    ) : null}
                    {expert.lastDrawNum ? (
                      <Text className='expert-card__meta-item'>{rankLabels.lastDraw(expert.lastDrawNum)}</Text>
                    ) : null}
                  </View>
                </View>
                <View className='expert-card__follow' onClick={(e) => e.stopPropagation()}>
                  <FollowButton
                    key={`${expert.id}-${followed}`}
                    userId={expert.id}
                    isFollowed={followed}
                    onChange={(next) => setFollowMap((prev) => ({ ...prev, [String(expert.id)]: next }))}
                  />
                </View>
              </View>
              <View className='expert-card__record'>
                <Text className='expert-card__record-text'>{expert.record || rankLabels.recordEmpty}</Text>
                <Text className={`expert-card__trend expert-card__trend--${expert.recentTrend}`}>{trendText}</Text>
              </View>
            </View>
          )
        })
      )}

      {/* 底部静态宣传 banner（Web PRD §6.4） */}
      <View className='banner banner--primary'>
        <Text className='banner__title banner__title--light'>{rankLabels.banners[0].title}</Text>
        <Text className='banner__desc banner__desc--light'>{rankLabels.banners[0].desc}</Text>
      </View>
      <View className='banner'>
        <Text className='banner__title'>{rankLabels.banners[1].title}</Text>
        <Text className='banner__desc'>{rankLabels.banners[1].desc}</Text>
      </View>

      {/* 筛选面板：剩余维度收纳，确定后才触发请求 */}
      <Popup visible={panelVisible} onClose={() => setPanelVisible(false)}>
        <View className='panel'>
          <Text className='panel__title'>{rankLabels.filterTitle}</Text>
          <View className='panel__group'>
            <Text className='panel__label'>{rankLabels.groups.dimension}</Text>
            <View className='panel__chips'>
              {renderChips(FORECAST_DIMENSION_OPTIONS, draft.dimension, (value) =>
                patchDraft({ dimension: value }),
              )}
            </View>
          </View>
          {draftCodeModes.length > 0 ? (
            <View className='panel__group'>
              <Text className='panel__label'>{rankLabels.groups.codeMode}</Text>
              <View className='panel__chips'>{renderChips(draftCodeModes, draft.codeMode, (value) => patchDraft({ codeMode: value }))}</View>
            </View>
          ) : null}
          {draftPrecisions.length > 0 ? (
            <View className='panel__group'>
              <Text className='panel__label'>{rankLabels.groups.precision}</Text>
              <View className='panel__chips'>
                {renderChips(draftPrecisions, draft.precision, (value) => patchDraft({ precision: value }))}
              </View>
            </View>
          ) : null}
          {isLoggedIn ? (
            <View className='panel__group'>
              <Text className='panel__label'>{rankLabels.groups.followFilter}</Text>
              <View className='panel__chips'>
                {renderChips(rankLabels.followFilterOptions, draft.followFilter, (value) => patchDraft({ followFilter: value }))}
              </View>
            </View>
          ) : null}
          <View className='panel__footer'>
            <View className='panel__btn' onClick={resetPanel}>
              <Text className='panel__btn-text'>{rankLabels.reset}</Text>
            </View>
            <View className='panel__btn panel__btn--primary' onClick={confirmPanel}>
              <Text className='panel__btn-text panel__btn-text--primary'>{rankLabels.confirm}</Text>
            </View>
          </View>
        </View>
      </Popup>
    </View>
  )
}
