.comment-section {
  margin: 12px 16px 0;
  padding: 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.comment-section__title {
  display: block;
  margin-bottom: 12px;
  font-size: 16px;
  font-weight: 600;
  color: var(--color-text);
}

.comment-thread {
  padding: 14px 0;
  border-bottom: 1px solid var(--color-border);
}

.comment-thread:last-child {
  border-bottom-width: 0; /* RN 端不支持 border-bottom: none */
}

.comment-thread__replies {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 12px;
  margin-left: 40px;
  padding: 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
}

.comment-thread__more {
  display: flex;
  align-items: center;
  min-height: 44px;
  margin-left: 40px;
}

.comment-thread__more-text {
  font-size: 12px;
  color: var(--color-primary);
}

.comment-section__more {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
}

.comment-section__more-text {
  font-size: 13px;
  color: var(--color-primary);
}

/* 吸底评论输入栏：fixed + 安全区（产品方案 §6.7） */
.comment-bar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 90;
  background: var(--color-bg-card);
  border-top: 1px solid var(--color-border);
  padding: 8px 12px var(--sa-8, calc(8px + env(safe-area-inset-bottom)));
}

.comment-bar__target {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  min-height: 36px;
  padding: 0 4px;
}

.comment-bar__target-text {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.comment-bar__target-cancel {
  font-size: 12px;
  color: var(--color-primary);
  padding: 8px;
}

.comment-bar__row {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.comment-bar__input {
  flex: 1;
  min-width: 0;
  height: 40px;
  padding: 0 14px;
  background: var(--color-bg);
  border-radius: 999px;
  font-size: 14px;
}

.comment-bar__send {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 56px;
  min-height: 44px;
  margin-left: 8px;
}

.comment-bar__send-text {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-primary);
}
