/** 直播窗口判定（北京时间 21:00–22:00），移植自 lottery_web utils/liveLottery.ts */

export interface LiveWindowState {
  isLive: boolean
  countdownMs: number
  buttonText: string
  badgeText: string
  statusText: string
}

const BEIJING_TIME_ZONE = 'Asia/Shanghai'
const BEIJING_UTC_OFFSET = 8
const LIVE_START_HOUR = 21
const LIVE_END_HOUR = 22
const ONE_DAY_MS = 24 * 60 * 60 * 1000

function pad(value: number) {
  return String(value).padStart(2, '0')
}

/** 格式化器开销大（ICU 构造），模块级缓存复用（home 30s 轮询、live 页 1s 轮询共用） */
let beijingPartsFormatter: Intl.DateTimeFormat | null = null
function getBeijingPartsFormatter() {
  if (!beijingPartsFormatter) {
    beijingPartsFormatter = new Intl.DateTimeFormat('en-CA', {
      timeZone: BEIJING_TIME_ZONE,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
    })
  }
  return beijingPartsFormatter
}

function getBeijingDateParts(date = new Date()) {
  const formatter = getBeijingPartsFormatter()

  const mapped = Object.fromEntries(
    formatter
      .formatToParts(date)
      .filter((part) => part.type !== 'literal')
      .map((part) => [part.type, part.value]),
  )

  return {
    year: Number(mapped.year || 0),
    month: Number(mapped.month || 0),
    day: Number(mapped.day || 0),
    hour: Number(mapped.hour || 0) % 24,
    minute: Number(mapped.minute || 0),
    second: Number(mapped.second || 0),
  }
}

function toBeijingTimestamp(parts: {
  year: number
  month: number
  day: number
  hour: number
  minute: number
  second: number
}) {
  return Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour - BEIJING_UTC_OFFSET,
    parts.minute,
    parts.second,
  )
}

function formatCountdown(countdownMs: number) {
  const safeMs = Math.max(0, countdownMs)
  const totalSeconds = Math.floor(safeMs / 1000)
  const hours = Math.floor(totalSeconds / 3600)
  const minutes = Math.floor((totalSeconds % 3600) / 60)
  const seconds = totalSeconds % 60
  return `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`
}

export function getLiveWindowState(now = new Date()): LiveWindowState {
  const nowParts = getBeijingDateParts(now)
  const nowTimestamp = toBeijingTimestamp(nowParts)
  const todayStartTimestamp = toBeijingTimestamp({ ...nowParts, hour: LIVE_START_HOUR, minute: 0, second: 0 })
  const todayEndTimestamp = toBeijingTimestamp({ ...nowParts, hour: LIVE_END_HOUR, minute: 0, second: 0 })

  if (nowTimestamp >= todayStartTimestamp && nowTimestamp < todayEndTimestamp) {
    return {
      isLive: true,
      countdownMs: 0,
      buttonText: '观看直播',
      badgeText: '直播时段',
      statusText: '北京时间 21:00 - 22:00 正在直播',
    }
  }

  const nextStartTimestamp = nowTimestamp < todayStartTimestamp ? todayStartTimestamp : todayStartTimestamp + ONE_DAY_MS
  const countdownMs = nextStartTimestamp - nowTimestamp

  return {
    isLive: false,
    countdownMs,
    buttonText: formatCountdown(countdownMs),
    badgeText: '即将开播',
    statusText: nowTimestamp < todayStartTimestamp ? '距今晚 21:00 开播还有' : '距明晚 21:00 开播还有',
  }
}

export function formatBeijingDateTime(raw?: string | null) {
  if (!raw) return '--'
  const date = new Date(raw)
  if (Number.isNaN(date.getTime())) return String(raw)

  return getBeijingDisplayFormatter()
    .format(date)
    .replace(/\//g, '-')
}

/** 展示用格式化器同样模块级缓存（列表行级调用频繁） */
let beijingDisplayFormatter: Intl.DateTimeFormat | null = null
function getBeijingDisplayFormatter() {
  if (!beijingDisplayFormatter) {
    beijingDisplayFormatter = new Intl.DateTimeFormat('zh-CN', {
      timeZone: BEIJING_TIME_ZONE,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
    })
  }
  return beijingDisplayFormatter
}

export function isDirectVideoSource(url: string) {
  return /\.(mp4|webm|ogg)(\?.*)?$/i.test(url)
}
