import type { Dispatch, SetStateAction } from 'react'
import { ScrollView, Text, Textarea, View } from '@tarojs/components'
import Popup from '@/components/SheetPopup'
import { filterLabels as labels } from '@/labels/tools'
import PopupCloseIcon from '@/components/PopupCloseIcon'
import {
  COMPOSITE_DIGITS,
  DIGITS,
  EVEN_DIGITS,
  HISTORY_EXCLUDE_PERIODS,
  LARGE_DIGITS,
  ODD_DIGITS,
  PRIME_DIGITS,
  SMALL_DIGITS,
  getDifferencePairs,
  getPositionLabels,
  getRatioValues,
  getSumModeOptions,
  pickValuesByShortcut,
  ratioLabel,
  type ConditionKind,
  type ConditionMode,
  type ConditionState,
  type ValueShortcut,
} from '@/utils/tools/filterEngine'

/** 条件配置弹层标题（源 dialogTitle） */
const DIALOG_TITLES: Record<ConditionKind, string> = {
  position: labels.dialogTitlePosition,
  sum: labels.dialogTitleSum,
  sumTail: labels.dialogTitleSumTail,
  difference: labels.dialogTitleDifference,
  sizeParity: labels.dialogTitleSizeParity,
  size: labels.dialogTitleSize,
  parity: labels.dialogTitleParity,
  historyExclude: labels.dialogTitleHistoryExclude,
}

/** 条件配置弹层提示（源 valueDialogTip / 各 dialog-tip） */
function dialogTip(kind: ConditionKind): string {
  switch (kind) {
    case 'position':
      return labels.dialogPositionTip
    case 'sum':
      return labels.dialogSumTip
    case 'sumTail':
      return labels.dialogSumTailTip
    case 'difference':
      return labels.dialogDifferenceTip
    case 'size':
      return labels.dialogSizeTip
    case 'parity':
      return labels.dialogParityTip
    case 'historyExclude':
      return labels.historyExcludeTip
    default:
      return ''
  }
}

interface DigitGridProps {
  selected: number[]
  onToggle: (digit: number) => void
}

/** 0-9 数字 chip 网格（5 个一行，触控 ≥44px；主页逐位选号与定位弹层共用） */
export function DigitGrid({ selected, onToggle }: DigitGridProps) {
  return (
    <View className='ft-digit-grid'>
      {DIGITS.map((digit) => {
        const active = selected.includes(digit)
        return (
          <View
            key={digit}
            className={`ft-digit${active ? ' ft-digit--active' : ''}`}
            onClick={() => onToggle(digit)}
          >
            <Text className={`ft-digit__text${active ? ' ft-digit__text--active' : ''}`}>{digit}</Text>
          </View>
        )
      })}
    </View>
  )
}

interface ConditionPopupProps {
  visible: boolean
  kind: ConditionKind
  digitCount: number
  cond: ConditionState
  setCond: Dispatch<SetStateAction<ConditionState>>
  /** 「按往期开奖排除」拉取历史中（禁用确定/排除按钮） */
  applying: boolean
  /** 取消按钮：关闭并重置条件编辑状态（源 cancelConditionDialog） */
  onCancel: () => void
  /** 遮罩 / 关闭图标：仅关闭不重置（对齐源 el-dialog 右上角关闭） */
  onMaskClose: () => void
  onApply: (mode: ConditionMode) => void
}

/** 筛选条件配置弹层（源 el-dialog 全部 7 类条件面板，底部 Popup + 内部 ScrollView） */
export function ConditionPopup({
  visible,
  kind,
  digitCount,
  cond,
  setCond,
  applying,
  onCancel,
  onMaskClose,
  onApply,
}: ConditionPopupProps) {
  const positionLabels = getPositionLabels(digitCount)
  const differencePairs = getDifferencePairs(digitCount)
  const sumModeOptions = getSumModeOptions(digitCount)
  const ratioValues = getRatioValues(digitCount)
  const isSumKind = kind === 'sum' || kind === 'sumTail'

  const activeSumMode = kind === 'sumTail' ? cond.activeSumTailMode : cond.activeSumMode
  const activeSumDigitCount = activeSumMode === 'base' ? digitCount : Number(activeSumMode)
  const sumUseAny = kind === 'sumTail' ? cond.sumTailUseAnyPositions : cond.sumUseAnyPositions
  const sumSelectedPositions = kind === 'sumTail' ? cond.sumTailSelectedPositions : cond.sumSelectedPositions

  /** 当前值域（源 activeDialogValues）：和值为 0..N*9，合值/两码差为 0-9 */
  const activeDialogValues =
    kind === 'sum' ? Array.from({ length: activeSumDigitCount * 9 + 1 }, (_, index) => index) : DIGITS

  /** 当前激活值组读取（源 getActiveSelectionValues） */
  const getValues = (state: ConditionState): number[] => {
    if (kind === 'sum') {
      return state.activeSumMode === 'base' ? state.sumSelections : state.sumGroupSelections[state.activeSumMode] || []
    }
    if (kind === 'sumTail') {
      return state.activeSumTailMode === 'base'
        ? state.sumTailSelections
        : state.sumTailGroupSelections[state.activeSumTailMode] || []
    }
    return state.differenceSelections[state.activeDifferencePair] || []
  }

  /** 当前激活值组写回（源 setActiveSelectionValues） */
  const setValues = (values: number[]) =>
    setCond((prev) => {
      if (kind === 'sum') {
        return prev.activeSumMode === 'base'
          ? { ...prev, sumSelections: values }
          : { ...prev, sumGroupSelections: { ...prev.sumGroupSelections, [prev.activeSumMode]: values } }
      }
      if (kind === 'sumTail') {
        return prev.activeSumTailMode === 'base'
          ? { ...prev, sumTailSelections: values }
          : { ...prev, sumTailGroupSelections: { ...prev.sumTailGroupSelections, [prev.activeSumTailMode]: values } }
      }
      return { ...prev, differenceSelections: { ...prev.differenceSelections, [prev.activeDifferencePair]: values } }
    })

  const activeValues = getValues(cond)

  const toggleValue = (value: number) =>
    setValues(
      activeValues.includes(value)
        ? activeValues.filter((item) => item !== value)
        : [...activeValues, value].sort((a, b) => a - b),
    )

  // ---------- 定位条件 ----------
  const setAllPositions = (values: number[]) =>
    setCond((prev) => ({ ...prev, positionSelections: positionLabels.map(() => [...values]) }))
  const invertPositions = () =>
    setCond((prev) => ({
      ...prev,
      positionSelections: prev.positionSelections.map((selected) => DIGITS.filter((digit) => !selected.includes(digit))),
    }))
  const togglePositionDigit = (index: number, digit: number) =>
    setCond((prev) => ({
      ...prev,
      positionSelections: prev.positionSelections.map((selected, i) =>
        i === index
          ? selected.includes(digit)
            ? selected.filter((item) => item !== digit)
            : [...selected, digit].sort((a, b) => a - b)
          : selected,
      ),
    }))
  const invertPosition = (index: number) =>
    setCond((prev) => ({
      ...prev,
      positionSelections: prev.positionSelections.map((selected, i) =>
        i === index ? DIGITS.filter((digit) => !selected.includes(digit)) : selected,
      ),
    }))

  // ---------- 和值 / 合值 ----------
  const setSumMode = (key: string) =>
    setCond((prev) => (kind === 'sumTail' ? { ...prev, activeSumTailMode: key } : { ...prev, activeSumMode: key }))
  /** 「任意」开关（源 setSumUseAnyPositions / setSumTailUseAnyPositions） */
  const setUseAny = (useAny: boolean) =>
    setCond((prev) => {
      const positions =
        useAny || activeSumDigitCount !== digitCount ? [] : Array.from({ length: digitCount }, (_, index) => index)
      return kind === 'sumTail'
        ? { ...prev, sumTailUseAnyPositions: useAny, sumTailSelectedPositions: positions }
        : { ...prev, sumUseAnyPositions: useAny, sumSelectedPositions: positions }
    })
  const toggleSumPosition = (index: number) =>
    setCond((prev) => {
      const selected = kind === 'sumTail' ? prev.sumTailSelectedPositions : prev.sumSelectedPositions
      const next = selected.includes(index) ? selected.filter((item) => item !== index) : [...selected, index]
      return kind === 'sumTail' ? { ...prev, sumTailSelectedPositions: next } : { ...prev, sumSelectedPositions: next }
    })

  // ---------- 大小 / 奇偶比例 ----------
  const ratioSelections = kind === 'parity' ? cond.parityCountSelections : cond.sizeCountSelections
  const setRatioSelections = (values: number[]) =>
    setCond((prev) =>
      kind === 'parity' ? { ...prev, parityCountSelections: values } : { ...prev, sizeCountSelections: values },
    )
  const toggleRatioValue = (value: number) =>
    setRatioSelections(
      ratioSelections.includes(value)
        ? ratioSelections.filter((item) => item !== value)
        : [...ratioSelections, value].sort((a, b) => a - b),
    )

  // ---------- 历史排除 ----------
  const toggleHistoryPosition = (index: number) =>
    setCond((prev) => ({
      ...prev,
      historyExcludePositions: prev.historyExcludePositions.includes(index)
        ? prev.historyExcludePositions.filter((item) => item !== index)
        : [...prev.historyExcludePositions, index],
    }))

  const shortcutButtons: { key: ValueShortcut; text: string }[] = [
    { key: 'large', text: labels.quickLarge },
    { key: 'small', text: labels.quickSmall },
    { key: 'odd', text: labels.quickOdd },
    { key: 'even', text: labels.quickEven },
    { key: 'prime', text: labels.quickPrime },
    { key: 'composite', text: labels.quickComposite },
  ]

  const renderToolbar = (actions: { text: string; onClick: () => void }[]) => (
    <View className='chips ft-toolbar'>
      {actions.map((action) => (
        <View key={action.text} className='chip chip--small' onClick={action.onClick}>
          <Text className='chip__text'>{action.text}</Text>
        </View>
      ))}
    </View>
  )

  const renderValueGrid = (values: number[], selected: number[], onToggle: (value: number) => void) => (
    <View className='ft-value-grid'>
      {values.map((value) => {
        const active = selected.includes(value)
        return (
          <View
            key={value}
            className={`ft-value${active ? ' ft-value--active' : ''}`}
            onClick={() => onToggle(value)}
          >
            <Text className={`ft-value__text${active ? ' ft-value__text--active' : ''}`}>{value}</Text>
          </View>
        )
      })}
    </View>
  )

  return (
    <Popup visible={visible} closeable closeIcon={<PopupCloseIcon />} onClose={onMaskClose}>
      <View className='ft-sheet'>
        <Text className='ft-sheet__title'>{DIALOG_TITLES[kind]}</Text>
        <ScrollView scrollY className='ft-sheet__body'>
          <Text className='ft-hint'>{dialogTip(kind)}</Text>

          {kind === 'position' ? (
            <>
              {renderToolbar([
                { text: labels.selectAll, onClick: () => setAllPositions(DIGITS) },
                { text: labels.invert, onClick: invertPositions },
                { text: labels.quickLarge, onClick: () => setAllPositions(LARGE_DIGITS) },
                { text: labels.quickSmall, onClick: () => setAllPositions(SMALL_DIGITS) },
                { text: labels.quickOdd, onClick: () => setAllPositions(ODD_DIGITS) },
                { text: labels.quickEven, onClick: () => setAllPositions(EVEN_DIGITS) },
                { text: labels.quickPrime, onClick: () => setAllPositions(PRIME_DIGITS) },
                { text: labels.quickComposite, onClick: () => setAllPositions(COMPOSITE_DIGITS) },
              ])}
              {positionLabels.map((position, index) => (
                <View key={position} className='ft-position-block'>
                  <View className='ft-position-block__head'>
                    <Text className='ft-position-block__name'>{position}</Text>
                    <View className='ft-position-block__ops'>
                      <Text
                        className='ft-link'
                        onClick={() =>
                          setCond((prev) => ({
                            ...prev,
                            positionSelections: prev.positionSelections.map((selected, i) =>
                              i === index ? [...DIGITS] : selected,
                            ),
                          }))
                        }
                      >
                        {labels.selectAll}
                      </Text>
                      <Text className='ft-link' onClick={() => invertPosition(index)}>
                        {labels.invert}
                      </Text>
                    </View>
                  </View>
                  <DigitGrid
                    selected={cond.positionSelections[index] || []}
                    onToggle={(digit) => togglePositionDigit(index, digit)}
                  />
                </View>
              ))}
            </>
          ) : null}

          {kind === 'difference' ? (
            <>
              <View className='chips'>
                {differencePairs.map((pair) => {
                  const active = cond.activeDifferencePair === pair.key
                  return (
                    <View
                      key={pair.key}
                      className={`chip${active ? ' chip--active' : ''}`}
                      onClick={() => setCond((prev) => ({ ...prev, activeDifferencePair: pair.key }))}
                    >
                      <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>
                        {pair.key === 'any' ? labels.differencePairAny : pair.label}
                      </Text>
                    </View>
                  )
                })}
              </View>
              {renderToolbar([
                { text: labels.selectAll, onClick: () => setValues([...activeDialogValues]) },
                {
                  text: labels.invert,
                  onClick: () => setValues(activeDialogValues.filter((value) => !activeValues.includes(value))),
                },
                ...shortcutButtons.map((item) => ({
                  text: item.text,
                  onClick: () => setValues(pickValuesByShortcut(activeDialogValues, item.key)),
                })),
              ])}
              {renderValueGrid(activeDialogValues, activeValues, toggleValue)}
            </>
          ) : null}

          {isSumKind ? (
            <>
              <View className='chips'>
                {sumModeOptions.map((option) => {
                  const active = activeSumMode === option.key
                  return (
                    <View
                      key={option.key}
                      className={`chip${active ? ' chip--active' : ''}`}
                      onClick={() => setSumMode(option.key)}
                    >
                      <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>
                        {labels.sumModeOption(option.count, kind)}
                      </Text>
                    </View>
                  )
                })}
              </View>
              <View className='ft-sumpos'>
                <Text className='ft-hint'>{labels.sumPositionTitle(activeSumDigitCount)}</Text>
                <View className='chips'>
                  <View
                    className={`chip${sumUseAny ? ' chip--active' : ''}`}
                    onClick={() => setUseAny(!sumUseAny)}
                  >
                    <Text className={`chip__text${sumUseAny ? ' chip__text--active' : ''}`}>{labels.anyPosition}</Text>
                  </View>
                  {positionLabels.map((position, index) => {
                    const active = sumSelectedPositions.includes(index)
                    return (
                      <View
                        key={position}
                        className={`chip${active ? ' chip--active' : ''}${sumUseAny ? ' chip--disabled' : ''}`}
                        onClick={() => {
                          if (!sumUseAny) toggleSumPosition(index)
                        }}
                      >
                        <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>{position}</Text>
                      </View>
                    )
                  })}
                </View>
              </View>
              {renderToolbar([
                { text: labels.selectAll, onClick: () => setValues([...activeDialogValues]) },
                {
                  text: labels.invert,
                  onClick: () => setValues(activeDialogValues.filter((value) => !activeValues.includes(value))),
                },
                ...shortcutButtons.map((item) => ({
                  text: item.text,
                  onClick: () => setValues(pickValuesByShortcut(activeDialogValues, item.key)),
                })),
              ])}
              {renderValueGrid(activeDialogValues, activeValues, toggleValue)}
            </>
          ) : null}

          {kind === 'size' || kind === 'parity' ? (
            <>
              {renderToolbar([
                { text: labels.selectAll, onClick: () => setRatioSelections([...ratioValues]) },
                {
                  text: labels.invert,
                  onClick: () => setRatioSelections(ratioValues.filter((value) => !ratioSelections.includes(value))),
                },
                { text: labels.clear, onClick: () => setRatioSelections([]) },
              ])}
              <View className='chips'>
                {ratioValues.map((value) => {
                  const active = ratioSelections.includes(value)
                  return (
                    <View key={value} className={`chip${active ? ' chip--active' : ''}`} onClick={() => toggleRatioValue(value)}>
                      <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>
                        {ratioLabel(value, digitCount)}
                      </Text>
                    </View>
                  )
                })}
              </View>
            </>
          ) : null}

          {kind === 'historyExclude' ? (
            <>
              <Text className='ft-hint'>{labels.historyExcludePositions}</Text>
              <View className='chips'>
                {positionLabels.map((position, index) => {
                  const active = cond.historyExcludePositions.includes(index)
                  return (
                    <View
                      key={position}
                      className={`chip${active ? ' chip--active' : ''}`}
                      onClick={() => toggleHistoryPosition(index)}
                    >
                      <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>{position}</Text>
                    </View>
                  )
                })}
              </View>
              <View className='chips ft-history-modes'>
                {(['codes', 'draws'] as const).map((mode) => {
                  const active = cond.historyExcludeMode === mode
                  return (
                    <View
                      key={mode}
                      className={`chip${active ? ' chip--active' : ''}`}
                      onClick={() => setCond((prev) => ({ ...prev, historyExcludeMode: mode }))}
                    >
                      <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>
                        {mode === 'codes' ? labels.historyModeCodes : labels.historyModeDraws}
                      </Text>
                    </View>
                  )
                })}
              </View>
              {cond.historyExcludeMode === 'codes' ? (
                <>
                  <Text className='ft-hint'>{labels.historyCodesSection}</Text>
                  <Textarea
                    className='ft-textarea'
                    value={cond.historyExcludeInput}
                    placeholder={labels.historyCodesPlaceholder(cond.historyExcludePositions.length || 2)}
                    maxlength={-1}
                    onInput={(e) =>
                      setCond((prev) => ({ ...prev, historyExcludeInput: e.detail.value }))
                    }
                  />
                </>
              ) : (
                <>
                  <Text className='ft-hint'>{labels.historyPeriodSection}</Text>
                  <View className='chips'>
                    {HISTORY_EXCLUDE_PERIODS.map((period) => {
                      const active = cond.historyExcludePeriod === period
                      return (
                        <View
                          key={period}
                          className={`chip${active ? ' chip--active' : ''}`}
                          onClick={() => setCond((prev) => ({ ...prev, historyExcludePeriod: period }))}
                        >
                          <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>
                            {labels.historyPeriodOption(period)}
                          </Text>
                        </View>
                      )
                    })}
                  </View>
                </>
              )}
            </>
          ) : null}
        </ScrollView>

        <View className='ft-sheet__footer'>
          <View className='ft-btn ft-btn--plain' onClick={onCancel}>
            <Text className='ft-btn__text ft-btn__text--plain'>{labels.dialogCancel}</Text>
          </View>
          <View
            className={`ft-btn${applying ? ' ft-btn--disabled' : ''}`}
            onClick={() => {
              if (!applying) onApply('include')
            }}
          >
            <Text className='ft-btn__text'>{labels.dialogConfirm}</Text>
          </View>
          <View
            className={`ft-btn ft-btn--danger${applying ? ' ft-btn--disabled' : ''}`}
            onClick={() => {
              if (!applying) onApply('exclude')
            }}
          >
            <Text className='ft-btn__text'>{labels.dialogExclude}</Text>
          </View>
        </View>
      </View>
    </Popup>
  )
}
