import { Text } from '@tarojs/components'
import './index.css'

/**
 * NutUI Popup `closeable` 的跨端关闭图标（配合 closeIcon prop 使用）。
 * NutUI 内置 Close 来自 @nutui/icons-react-taro，用 <i> 宿主标签渲染（H5 iconfont 方案），
 * RN 端渲染即崩溃（View config getter callback for component `i` must be a function），
 * 故 closeable Popup 一律传 closeIcon={<PopupCloseIcon />}，不再依赖内置图标。
 */
export default function PopupCloseIcon() {
  return <Text className='popup-close-icon'>✕</Text>
}
