import { View, Text } from '@tarojs/components'
import './index.css'

export interface ChipOption {
  label: string
  value: string
  disabled?: boolean
}

interface ChipGroupProps {
  options: ChipOption[]
  value: string
  onChange?: (value: string) => void
  /** 整组锁定置灰（如具体分区进入时彩种不可改） */
  locked?: boolean
}

/** 单选 Chips 组（替代 Web FilterButtonGroup，触控目标 ≥44px） */
export default function ChipGroup({ options, value, onChange, locked }: ChipGroupProps) {
  return (
    <View className='chip-group'>
      {options.map((opt) => {
        const active = opt.value === value
        const disabled = locked || !!opt.disabled
        return (
          <View
            key={opt.value}
            className={`chip-group__item${active ? ' chip-group__item--active' : ''}${disabled ? ' chip-group__item--disabled' : ''}`}
            onClick={() => {
              if (!disabled && onChange) onChange(opt.value)
            }}
          >
            <Text
              className={`chip-group__text${active ? ' chip-group__text--active' : ''}${disabled ? ' chip-group__text--disabled' : ''}`}
            >
              {opt.label}
            </Text>
          </View>
        )
      })}
    </View>
  )
}
