.number-balls {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  width: 100%;
}

/* RN 端圆球必须用 View 做容器（Text 的 border-radius 不裁剪背景、也不支持 flex居中），
   文字样式放到内部 Text 上 */
.number-ball {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  /* RN 不支持百分比 border-radius，用尺寸一半的数值画圆 */
  border-radius: 16px;
  background: var(--color-primary-light);
}

.number-ball__text {
  color: var(--color-primary);
  font-size: 16px;
  font-weight: 600;
}

.number-ball--hit {
  background: var(--color-warning);
}

.number-balls--small .number-ball {
  width: 32px;
  height: 32px;
  border-radius: 16px;
}

.number-balls--small .number-ball__text {
  font-size: 16px;
}