import { useCallback, useEffect, useState } from 'react'
import type { ReactNode } from 'react'
import { View, Text, Input } from '@tarojs/components'
import Taro from '@tarojs/taro'
import type { CommentNode, FlattenedReply, PageResult } from '@/types'
import { flattenReplies, flattenThreadRows } from '@/utils/forumComments'
import { useAuth, redirectToLogin } from '@/store/auth'
import { currentRoute } from '@/utils/nav'
import { COMMENT_MAX_LENGTH } from '@/constants/lottery'
import { commonLabels, forumLabels } from '@/labels'
import { forumDetailLabels } from '@/labels/forumDetail'
import Skeleton from '@/components/Skeleton'
import Empty from '@/components/Empty'
import CommentItem from '../CommentItem'
import './index.css'

/** 评论区数据源适配器（Web PRD §6.7.4 双 adapter：交流帖 forumId / 预测帖 forecastId） */
export interface CommentAdapter {
  loadComments: (sourceId: number | string, pageNum: number, pageSize: number) => Promise<PageResult<CommentNode>>
  loadReplies: (commentId: number | string, pageNum: number, pageSize: number) => Promise<PageResult<CommentNode>>
  publish: (body: { sourceId: number | string; content: string; parentId?: number }) => Promise<any>
  edit?: (body: { id: number | string; sourceId: number | string; content: string; parentId?: number }) => Promise<any>
  remove?: (id: number | string) => Promise<any>
  like: (id: number | string, currentlyLiked: boolean) => Promise<any>
  collect: (id: number | string) => Promise<any>
}

/** 能力开关：预测帖无编辑/删除、评论一次全量不分页 */
export interface CommentCapabilities {
  edit: boolean
  delete: boolean
  paginated: boolean
}

interface ThreadState {
  list: FlattenedReply[]
  pageNum: number
  loadedAll: boolean
  loading: boolean
}

type InputTarget =
  | { mode: 'main' }
  | { mode: 'reply' | 'edit'; comment: CommentNode }

interface CommentSectionProps {
  sourceId: number | string
  adapter: CommentAdapter
  capabilities: CommentCapabilities
  /** 吸底输入栏右侧附加操作（帖子详情页的收藏/分享按钮） */
  actions?: ReactNode
}

const PAGE_SIZE = 10
const REPLY_PAGE_SIZE = 10

function toast(title: string) {
  Taro.showToast({ title, icon: 'none' })
}

/**
 * 评论区（Web PRD §6.7.4）：楼中楼拍平两层、分页/全量双模式、
 * 乐观更新 + 失败回滚、删除二次确认、输入框吸底（maxlength 500）。
 */
export default function CommentSection({ sourceId, adapter, capabilities, actions }: CommentSectionProps) {
  const { isLoggedIn, profile } = useAuth()
  const [comments, setComments] = useState<CommentNode[]>([])
  const [threads, setThreads] = useState<Record<string, ThreadState>>({})
  const [total, setTotal] = useState(0)
  const [pageNum, setPageNum] = useState(1)
  const [loading, setLoading] = useState(true)
  const [loadingMore, setLoadingMore] = useState(false)
  const [draft, setDraft] = useState('')
  const [target, setTarget] = useState<InputTarget>({ mode: 'main' })
  const [publishing, setPublishing] = useState(false)

  const ensureLogin = useCallback(() => {
    if (isLoggedIn) return true
    redirectToLogin(currentRoute())
    return false
  }, [isLoggedIn])

  /** 按 id 就地更新顶级评论或楼中楼回复 */
  const patchComment = useCallback((id: number | string, patch: Partial<CommentNode>) => {
    const key = String(id)
    setComments((prev) => prev.map((c) => (String(c.id) === key ? { ...c, ...patch } : c)))
    setThreads((prev) => {
      let changed = false
      const next: Record<string, ThreadState> = {}
      for (const k of Object.keys(prev)) {
        const state = prev[k]
        const idx = state.list.findIndex((r) => String(r.id) === key)
        if (idx >= 0) {
          const list = [...state.list]
          list[idx] = { ...list[idx], ...patch }
          next[k] = { ...state, list }
          changed = true
        } else {
          next[k] = state
        }
      }
      return changed ? next : prev
    })
  }, [])

  const patchThread = useCallback((key: string, patch: Partial<ThreadState>) => {
    setThreads((prev) => (prev[key] ? { ...prev, [key]: { ...prev[key], ...patch } } : prev))
  }, [])

  const loadComments = useCallback(
    async (page: number, append: boolean) => {
      if (append) setLoadingMore(true)
      else setLoading(true)
      try {
        const res = await adapter.loadComments(sourceId, page, PAGE_SIZE)
        const rows = Array.isArray(res.rows) ? res.rows : []
        // 非分页模式（预测帖）用真实 total 更新评论计数
        setTotal(Number(res.total || 0))
        setPageNum(page)
        if (append && capabilities.paginated) {
          // 分页模式按页累加去重
          setComments((prev) => {
            const ids = new Set(prev.map((c) => String(c.id)))
            return [...prev, ...rows.filter((r) => !ids.has(String(r.id)))]
          })
          setThreads((prev) => {
            const next = { ...prev }
            rows.forEach((c) => {
              next[String(c.id)] = { list: flattenReplies(c), pageNum: 0, loadedAll: false, loading: false }
            })
            return next
          })
        } else {
          setComments(rows)
          const next: Record<string, ThreadState> = {}
          rows.forEach((c) => {
            next[String(c.id)] = { list: flattenReplies(c), pageNum: 0, loadedAll: false, loading: false }
          })
          setThreads(next)
        }
      } catch (err: any) {
        toast(err?.message || forumDetailLabels.commentLoadFailed)
      } finally {
        setLoading(false)
        setLoadingMore(false)
      }
    },
    [adapter, sourceId, capabilities.paginated],
  )

  useEffect(() => {
    loadComments(1, false)
  }, [loadComments])

  const loadReplies = useCallback(
    async (c: CommentNode) => {
      const key = String(c.id)
      const state = threads[key]
      if (!state || state.loading) return
      patchThread(key, { loading: true })
      try {
        if (capabilities.paginated) {
          // 分页模式（交流帖）：按页累加子评论
          const nextPage = state.pageNum + 1
          const res = await adapter.loadReplies(c.id, nextPage, REPLY_PAGE_SIZE)
          const rows = Array.isArray(res.rows) ? res.rows : []
          const flattened = flattenThreadRows(rows)
          const merged =
            nextPage === 1
              ? flattened
              : [...state.list, ...flattened.filter((r) => !state.list.some((e) => String(e.id) === String(r.id)))]
          patchThread(key, { list: merged, pageNum: nextPage, loadedAll: rows.length < REPLY_PAGE_SIZE, loading: false })
        } else {
          // 非分页模式（预测帖）：一次全量加载子评论
          const res = await adapter.loadReplies(c.id, 1, REPLY_PAGE_SIZE)
          const list = flattenThreadRows(Array.isArray(res.rows) ? res.rows : [])
          patchThread(key, { list, pageNum: 1, loadedAll: true, loading: false })
          // 全量加载后以真实总数改写该评论的回复计数
          patchComment(c.id, { commentNum: Number(res.total || list.length) })
        }
      } catch (err: any) {
        patchThread(key, { loading: false })
        toast(err?.message || forumDetailLabels.commentLoadFailed)
      }
    },
    [adapter, capabilities.paginated, threads, patchComment, patchThread],
  )

  const findTopComment = useCallback(
    (comment: CommentNode): CommentNode | undefined => {
      const id = String(comment.id)
      const asTop = comments.find((c) => String(c.id) === id)
      if (asTop) return asTop
      return comments.find((c) => (threads[String(c.id)]?.list || []).some((r) => String(r.id) === id))
    },
    [comments, threads],
  )

  /** 回复发表成功后重拉该顶级评论的全部回复（分页模式 pageSize 200 视为全量） */
  const refreshThread = useCallback(
    async (top: CommentNode) => {
      const key = String(top.id)
      try {
        const res = capabilities.paginated
          ? await adapter.loadReplies(top.id, 1, 200)
          : await adapter.loadReplies(top.id, 1, REPLY_PAGE_SIZE)
        const list = flattenThreadRows(Array.isArray(res.rows) ? res.rows : [])
        patchThread(key, { list, pageNum: 1, loadedAll: true, loading: false })
        patchComment(top.id, { commentNum: Number(res.total || list.length) })
      } catch {
        // 回复已发表成功，刷新失败不额外提示，下次进入页面时恢复
      }
    },
    [adapter, capabilities.paginated, patchComment, patchThread],
  )

  const submit = useCallback(async () => {
    const content = draft.trim()
    if (!content) {
      toast(forumDetailLabels.contentRequired)
      return
    }
    if (publishing || !ensureLogin()) return
    setPublishing(true)
    try {
      if (target.mode === 'edit' && target.comment) {
        if (!capabilities.edit || !adapter.edit) return
        await adapter.edit({ id: target.comment.id, sourceId, content, parentId: target.comment.parentId })
        patchComment(target.comment.id, { content })
        toast(forumDetailLabels.editSuccess)
      } else {
        const parentId = target.mode === 'reply' && target.comment ? target.comment.id : undefined
        const res = await adapter.publish({ sourceId, content, parentId })
        toast(res?.message || (parentId ? forumDetailLabels.replySuccess : forumDetailLabels.publishSuccess))
        if (parentId && target.mode === 'reply' && target.comment) {
          const top = findTopComment(target.comment)
          if (top) await refreshThread(top)
          else await loadComments(capabilities.paginated ? pageNum : 1, false)
        } else {
          await loadComments(1, false)
        }
      }
      setDraft('')
      setTarget({ mode: 'main' })
    } catch (err: any) {
      toast(err?.message || forumDetailLabels.operateFailed)
    } finally {
      setPublishing(false)
    }
  }, [draft, publishing, ensureLogin, target, capabilities, adapter, sourceId, patchComment, findTopComment, refreshThread, loadComments, pageNum])

  const handleReply = useCallback(
    (comment: CommentNode) => {
      if (!ensureLogin()) return
      setTarget({ mode: 'reply', comment })
      setDraft('')
    },
    [ensureLogin],
  )

  const handleEdit = useCallback(
    (comment: CommentNode) => {
      if (!ensureLogin()) return
      if (!capabilities.edit) return
      setTarget({ mode: 'edit', comment })
      setDraft(comment.content || '')
    },
    [ensureLogin, capabilities.edit],
  )

  const handleDelete = useCallback(
    async (comment: CommentNode) => {
      if (!ensureLogin()) return
      if (!capabilities.delete || !adapter.remove) return
      const modal = await Taro.showModal({
        title: forumDetailLabels.deleteConfirmTitle,
        content: forumDetailLabels.deleteConfirmMessage,
        confirmText: forumDetailLabels.delete,
        confirmColor: '#b83237',
      })
      if (!modal.confirm) return
      try {
        await adapter.remove(comment.id)
        toast(forumDetailLabels.deleteSuccess)
        const id = String(comment.id)
        const topIndex = comments.findIndex((c) => String(c.id) === id)
        if (topIndex >= 0) {
          setComments((prev) => prev.filter((c) => String(c.id) !== id))
          setTotal((prev) => Math.max(0, prev - 1))
          setThreads((prev) => {
            const next = { ...prev }
            delete next[id]
            return next
          })
          return
        }
        const top = findTopComment(comment)
        if (top) {
          const key = String(top.id)
          const state = threads[key]
          if (state) {
            patchThread(key, { list: state.list.filter((r) => String(r.id) !== id) })
          }
          patchComment(top.id, { commentNum: Math.max(0, Number(top.commentNum || 0) - 1) })
        }
      } catch (err: any) {
        toast(err?.message || forumDetailLabels.operateFailed)
      }
    },
    [ensureLogin, capabilities.delete, adapter, comments, threads, findTopComment, patchComment, patchThread],
  )

  const handleLike = useCallback(
    async (comment: CommentNode) => {
      if (!ensureLogin()) return
      const liked = comment.isLike === '1'
      const prevLikes = Number(comment.likeNum || 0)
      // 乐观更新，失败回滚
      patchComment(comment.id, { isLike: liked ? '0' : '1', likeNum: Math.max(0, prevLikes + (liked ? -1 : 1)) })
      try {
        await adapter.like(comment.id, liked)
      } catch (err: any) {
        patchComment(comment.id, { isLike: liked ? '1' : '0', likeNum: prevLikes })
        toast(err?.message || forumDetailLabels.operateFailed)
      }
    },
    [ensureLogin, adapter, patchComment],
  )

  const handleCollect = useCallback(
    async (comment: CommentNode) => {
      if (!ensureLogin()) return
      const collected = comment.isCollect === '1'
      // 乐观更新，失败回滚
      patchComment(comment.id, { isCollect: collected ? '0' : '1' })
      try {
        const res = await adapter.collect(comment.id)
        toast(res?.message || forumDetailLabels.collectSuccess)
      } catch (err: any) {
        patchComment(comment.id, { isCollect: collected ? '1' : '0' })
        toast(err?.message || forumDetailLabels.operateFailed)
      }
    },
    [ensureLogin, adapter, patchComment],
  )

  const isMine = useCallback(
    (c: CommentNode) => {
      const uid = profile?.id
      if (!uid || !c.userId) return false
      return String(c.userId) === String(uid)
    },
    [profile],
  )

  const hasMoreComments = capabilities.paginated && comments.length < total

  return (
    <View className='comment-section'>
      <Text className='comment-section__title'>{forumDetailLabels.commentTitle(total)}</Text>

      {loading && comments.length === 0 ? (
        <Skeleton rows={3} />
      ) : comments.length === 0 ? (
        <Empty text={forumDetailLabels.emptyComments} />
      ) : (
        <View className='comment-section__list'>
          {comments.map((c) => {
            const key = String(c.id)
            const state: ThreadState = threads[key] || { list: [], pageNum: 0, loadedAll: false, loading: false }
            const replyTotal = Number(c.commentNum || 0)
            const showToggle = !state.loadedAll && replyTotal > state.list.length
            return (
              <View key={key} className='comment-thread'>
                <CommentItem
                  comment={c}
                  isMine={isMine(c)}
                  canEdit={capabilities.edit}
                  canDelete={capabilities.delete}
                  onReply={handleReply}
                  onEdit={handleEdit}
                  onDelete={handleDelete}
                  onLike={handleLike}
                  onCollect={handleCollect}
                />
                {state.list.length > 0 ? (
                  <View className='comment-thread__replies'>
                    {state.list.map((r) => (
                      <CommentItem
                        key={String(r.id)}
                        comment={r}
                        isReply
                        replyToNickname={r.replyToNickname}
                        isMine={isMine(r)}
                        canEdit={capabilities.edit}
                        canDelete={capabilities.delete}
                        onReply={handleReply}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onLike={handleLike}
                        onCollect={handleCollect}
                      />
                    ))}
                  </View>
                ) : null}
                {showToggle ? (
                  <View className='comment-thread__more' onClick={() => loadReplies(c)}>
                    <Text className='comment-thread__more-text'>
                      {state.loading
                        ? commonLabels.loading
                        : state.pageNum === 0
                          ? forumDetailLabels.viewReplies(replyTotal)
                          : forumDetailLabels.loadMoreReplies(Math.max(0, replyTotal - state.list.length))}
                    </Text>
                  </View>
                ) : null}
              </View>
            )
          })}
        </View>
      )}

      {hasMoreComments ? (
        <View className='comment-section__more' onClick={() => !loadingMore && loadComments(pageNum + 1, true)}>
          <Text className='comment-section__more-text'>
            {loadingMore ? commonLabels.loading : forumDetailLabels.loadMoreComments}
          </Text>
        </View>
      ) : null}

      {/* 吸底评论输入栏（H5 简化：fixed 定位，键盘弹起由浏览器自行处理） */}
      <View className='comment-bar'>
        {target.mode !== 'main' ? (
          <View className='comment-bar__target'>
            <Text className='comment-bar__target-text'>
              {target.mode === 'reply' && target.comment
                ? forumDetailLabels.replyTo(target.comment.nickname || forumDetailLabels.anonymous)
                : forumDetailLabels.editingComment}
            </Text>
            <Text
              className='comment-bar__target-cancel'
              onClick={() => {
                setTarget({ mode: 'main' })
                setDraft('')
              }}
            >
              {commonLabels.cancel}
            </Text>
          </View>
        ) : null}
        <View className='comment-bar__row'>
          <Input
            className='comment-bar__input'
            value={draft}
            maxlength={COMMENT_MAX_LENGTH}
            placeholder={forumLabels.commentPlaceholder}
            onInput={(e) => setDraft(e.detail.value)}
          />
          <View className='comment-bar__send' onClick={submit}>
            <Text className='comment-bar__send-text'>{forumDetailLabels.send}</Text>
          </View>
          {actions}
        </View>
      </View>
    </View>
  )
}
