.profile-page {
  /* RN：页面已 disableScroll，根节点需撑满高度，内部 ScrollView 才有滚动区间（H5 下 flex 对块级布局无影响） */
  flex: 1;
  /* RN 端必须为 0（--sa-0），根节点外部 padding 会压缩内部 ScrollView 滚动区间；
     H5 端 var 不注入走 fallback，底部 24px + 安全区 */
  padding-bottom: var(--sa-0, calc(24px + env(safe-area-inset-bottom)));
}

/* H5：内容不足一屏时撑满视口。
   不能放进 .profile-page：RN 端 taro-css-to-react-native 会把 100vh 转成整窗高度，
   min-height 撑破 flex 容器会使内部 ScrollView 底部溢出到 Tab 栏下方 */
.profile-page--h5 {
  min-height: 100vh;
}

/* RN：页面内滚动容器（H5 不渲染该节点） */
.profile-page__scroll {
  flex: 1;
}

/* 未登录引导空态 */
.guest {
  margin: 16px;
  padding: 48px 24px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  align-items: center;
}

.guest__title {
  margin-top: 16px;
  font-size: 17px;
  font-weight: 600;
}

.guest__desc {
  margin-top: 8px;
  font-size: 13px;
  color: var(--color-text-secondary);
  text-align: center;
}

.guest__btn {
  margin-top: 24px;
  min-height: 48px;
  padding: 0 40px;
  border-radius: 999px;
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.guest__btn-text {
  color: #fff;
  font-size: 15px;
}

/* Hero 卡 */
.hero {
  margin: 16px;
  padding: 24px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.hero__main {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.hero__avatar {
  flex-shrink: 0;
  min-width: 64px;
  min-height: 64px;
}

.hero__info {
  flex: 1;
  margin-left: 16px;
  display: flex;
  flex-direction: column;
}

.hero__nickname {
  font-size: 18px;
  font-weight: 700;
}

.hero__member {
  margin-top: 4px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.hero__avatar-hint {
  margin-top: 4px;
  font-size: 11px;
  color: var(--color-text-placeholder);
}

.hero__edit {
  flex-shrink: 0;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 999px;
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero__edit-text {
  font-size: 13px;
  color: var(--color-text);
}

.hero__integral {
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--color-border);
  display: flex;
  flex-direction: row;
  align-items: center;
}

.hero__integral-label {
  font-size: 13px;
  color: var(--color-text-secondary);
}

.hero__integral-value {
  flex: 1;
  margin-left: 8px;
  font-size: 18px;
  font-weight: 700;
  color: var(--color-primary);
}

.hero__recharge {
  min-height: 44px;
  padding: 0 20px;
  border-radius: 999px;
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero__recharge-text {
  color: #fff;
  font-size: 13px;
}

.stats {
  margin-top: 20px;
  display: flex;
  flex-direction: row;
}

.stats__item {
  flex: 1;
  min-height: 44px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.stats__value {
  font-size: 18px;
  font-weight: 700;
}

.stats__label {
  margin-top: 4px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* 通用面板 */
.panel {
  margin: 0 16px 12px;
  padding: 20px 24px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.panel__head {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
}

.panel__title {
  font-size: 16px;
  font-weight: 600;
}

.panel__subtitle {
  display: block;
  margin: 16px 0 8px;
  font-size: 13px;
  color: var(--color-text-secondary);
}

.panel__more {
  min-height: 44px;
  display: flex;
  align-items: center;
  font-size: 13px;
  color: var(--color-primary);
}

/* 命中率概览 */
.rate-hero {
  margin-top: 12px;
  display: flex;
  flex-direction: row;
  align-items: center;
}

.rate-hero__value {
  font-size: 32px;
  font-weight: 700;
  color: var(--color-primary);
}

.rate-hero__meta {
  margin-left: 16px;
  display: flex;
  flex-direction: column;
}

.rate-hero__label {
  font-size: 13px;
  color: var(--color-text);
}

.rate-hero__stat {
  margin-top: 4px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.rate-meta {
  display: block;
  margin-top: 8px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* 趋势简图（纯 View 横向柱状条，不引入图表库） */
.trend__row {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin-bottom: 8px;
}

.trend__label {
  width: 72px;
  font-size: 11px;
  color: var(--color-text-secondary);
}

.trend__track {
  flex: 1;
  height: 8px;
  border-radius: 999px;
  background: var(--color-bg);
  overflow: hidden;
}

.trend__bar {
  height: 100%;
  border-radius: 999px;
  background: var(--color-primary);
}

.trend__value {
  width: 44px;
  text-align: right;
  font-size: 11px;
  color: var(--color-text-secondary);
}

/* modeSummaries chips */
.chips {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--color-primary-light);
  color: var(--color-primary);
  font-size: 12px;
}

/* 最新预测卡片 */
.forecast-card {
  margin-top: 12px;
  padding-top: 16px;
  border-top: 1px solid var(--color-border);
}

.forecast-card__head {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  min-height: 44px;
}

.forecast-card__issue {
  font-size: 13px;
  color: var(--color-text);
}

.forecast-card__phase {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.forecast-card__title {
  display: block;
  margin-top: 8px;
  font-size: 15px;
  font-weight: 600;
}

.forecast-card__plans {
  margin-top: 8px;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.plan-tag {
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
  font-size: 11px;
  color: var(--color-text-secondary);
}

.forecast-card__foot {
  margin-top: 8px;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
}

.forecast-card__time,
.forecast-card__meta {
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* 功能列表 */
.menu {
  margin: 0 16px 12px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.menu__item {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  min-height: 56px;
  padding: 0 24px;
  border-bottom: 1px solid var(--color-border);
}

.menu__item--last {
  border-bottom-width: 0; /* RN 端不支持 border-bottom: none */
}

.menu__label {
  font-size: 15px;
  color: var(--color-text);
}

.menu__arrow {
  font-size: 16px;
  color: var(--color-text-placeholder);
}

/* 退出登录 */
.logout {
  margin: 24px 16px 0;
  min-height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
}

.logout__text {
  font-size: 15px;
  color: var(--color-danger);
}

/* 弹层内容 */
.sheet {
  padding: 24px;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

.sheet__title {
  display: block;
  margin-bottom: 20px;
  text-align: center;
  font-size: 17px;
  font-weight: 600;
}

/* 带返回键的弹层头部（修改密码等二级弹层） */
.sheet__header {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin-bottom: 20px;
}

.sheet__back {
  /* 触控目标 ≥44px（AGENTS.md 编码约定） */
  width: 44px;
  height: 44px;
  line-height: 44px;
  font-size: 28px;
  color: var(--color-text);
}

.sheet__back--placeholder {
  font-size: 0; /* 占位平衡两侧宽度，保证标题居中 */
}

.sheet__header-title {
  flex: 1;
  text-align: center;
  font-size: 17px;
  font-weight: 600;
}

.sheet__content {
  font-size: 14px;
  line-height: 1.6;
  color: var(--color-text-secondary);
}

.sheet__row {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  min-height: 56px;
  border-bottom: 1px solid var(--color-border);
}

.sheet__row--last {
  border-bottom-width: 0; /* RN 端不支持 border-bottom: none */
}

.sheet__row-info {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.sheet__row-label {
  font-size: 15px;
  color: var(--color-text);
}

.sheet__row-hint {
  margin-top: 4px;
  font-size: 12px;
  color: var(--color-text-placeholder);
}

/* 编辑资料表单 */
.form__item {
  margin-bottom: 16px;
}

.form__label {
  display: block;
  margin-bottom: 6px;
  font-size: 13px;
  color: var(--color-text-secondary);
}

/* Taro Input（RN 端不能用 NutInput：内部 MaskClose 图标走 <i> 宿主标签会崩） */
.form__input {
  height: 44px;
  padding: 0 12px;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  font-size: 15px;
  color: var(--color-text);
}

/* 弹层提交按钮：自绘主按钮（NutButton 在 RN 端样式丢失且 loading 图标崩溃，禁用） */
.sheet__submit {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 46px;
  border-radius: 23px;
  background: var(--color-primary);
}

.sheet__submit--disabled {
  opacity: 0.6;
}

.sheet__submit-text {
  font-size: 16px;
  font-weight: 600;
  color: #fff;
}

/* 修改密码弹层 */
.pwd-entry {
  margin-bottom: 16px;
}

.pwd-tabs {
  display: flex;
  flex-direction: row;
  margin-bottom: 16px;
  padding: 3px;
  border-radius: 8px;
  background: var(--color-bg);
}

.pwd-tabs__tab {
  flex: 1;
  /* 触控目标 ≥44px（AGENTS.md 编码约定） */
  height: 44px;
  line-height: 44px;
  text-align: center;
  font-size: 14px;
  color: var(--color-text-secondary);
  border-radius: 6px;
}

.pwd-tabs__tab--active {
  background: var(--color-primary);
  color: #fff;
}

.pwd__hint {
  display: block;
  margin-bottom: 8px;
  font-size: 12px;
  color: var(--color-text-placeholder);
}

.form__code-row {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.form__code-input {
  flex: 1;
}

.form__code-btn {
  margin-left: 12px;
  min-width: 88px;
  height: 44px;
  line-height: 44px;
  text-align: center;
  font-size: 14px;
  color: var(--color-primary);
}

.form__code-btn--disabled {
  color: var(--color-text-placeholder);
}
