.publish-page {
  min-height: 100vh;
  padding: 16px 16px var(--sa-96, calc(96px + env(safe-area-inset-bottom)));
  box-sizing: border-box;
}

.pub-card {
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  padding: 16px;
  margin-bottom: 12px;
}

.pub-card__title {
  display: block;
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 12px;
}

.pub-card__subtitle {
  font-size: 12px;
  color: var(--color-text-secondary);
  font-weight: 400;
  margin-left: 8px;
}

.pub-field {
  margin-bottom: 16px;
}

.pub-field:last-child {
  margin-bottom: 0;
}

.pub-field__label {
  display: block;
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.pub-input {
  width: 100%;
  box-sizing: border-box;
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  font-size: 15px;
  background: var(--color-bg-card);
}

.pub-textarea {
  width: 100%;
  box-sizing: border-box;
  min-height: 200px;
  padding: 12px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  font-size: 15px;
  line-height: 1.6;
  background: var(--color-bg-card);
}

.pub-textarea--summary {
  min-height: 120px;
}

/* 图片插位（交流帖） */
.pic-grid {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.pic-grid__item {
  position: relative;
  width: 96px;
  height: 96px;
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.pic-grid__image {
  width: 96px;
  height: 96px;
}

.pic-grid__remove {
  position: absolute;
  top: 0;
  right: 0;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.5);
  border-bottom-left-radius: var(--radius-sm);
}

.pic-grid__remove-text {
  color: #fff;
  font-size: 14px;
}

.pic-grid__add {
  width: 96px;
  height: 96px;
  border: 1px dashed var(--color-border);
  border-radius: var(--radius-sm);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.pic-grid__add-icon {
  font-size: 24px;
  color: var(--color-text-placeholder);
  line-height: 1;
}

.pic-grid__add-text {
  font-size: 11px;
  color: var(--color-text-placeholder);
  margin-top: 4px;
}

/* 预测帖标题组合器：自动前缀 + 用户后缀 */
.title-composer {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.title-composer__prefix {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.5;
}

.title-composer__prefix--missing {
  color: var(--color-danger);
}

.title-composer__suffix {
  flex: 1;
  min-width: 160px;
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  font-size: 14px;
  box-sizing: border-box;
}

/* 方案明细 */
.plan-head {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.plan-head__hint {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.prediction-data {
  padding: 12px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-bg);
  font-size: 13px;
  line-height: 1.7;
  color: var(--color-text);
  white-space: pre-wrap;
  word-break: break-all;
}

.prediction-data--empty {
  color: var(--color-text-placeholder);
}

/* 底部固定操作栏（安全区适配） */
.publish-actions {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: row;
  gap: 12px;
  padding: 12px 16px var(--sa-12, calc(12px + env(safe-area-inset-bottom)));
  background: var(--color-bg-card);
  border-top: 1px solid var(--color-border);
}

.publish-actions__btn {
  flex: 1;
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-border);
  background: var(--color-bg-card);
}

.publish-actions__btn--primary {
  background: var(--color-primary);
  border-color: var(--color-primary);
}

.publish-actions__btn--disabled {
  opacity: 0.6;
}

.publish-actions__btn-text {
  font-size: 15px;
  color: var(--color-text-secondary);
}

.publish-actions__btn-text--primary {
  color: #fff;
  font-weight: 600;
}
