import { ScrollView, Text, View } from '@tarojs/components'
import Empty from '@/components/Empty'
import { filterLabels as labels } from '@/labels/tools'
import type { FilterPlan, ResultItem } from '@/utils/tools/filterEngine'

interface ResultPanelProps {
  plans: FilterPlan[]
  activePlanId: string
  selectedPlanIds: string[]
  onSwitchPlan: (planId: string) => void
  onToggleSelect: (planId: string) => void
  onClosePlan: (planId: string) => void
  results: ResultItem[]
  displayCount: number
  onLoadMore: () => void
  onToggleDeleted: (index: number) => void
  onGoExtension: () => void
  onGoSetProcessing: () => void
  onGoHistoryReview: () => void
  onOpenCopy: () => void
  copyDisabled: boolean
}

/** 结果面板（源 result-panel）：多方案 tab（勾选≤2 / 切换 / 关闭）+ 号码列表（行级删除/还原）+ 出站联动 */
export function ResultPanel({
  plans,
  activePlanId,
  selectedPlanIds,
  onSwitchPlan,
  onToggleSelect,
  onClosePlan,
  results,
  displayCount,
  onLoadMore,
  onToggleDeleted,
  onGoExtension,
  onGoSetProcessing,
  onGoHistoryReview,
  onOpenCopy,
  copyDisabled,
}: ResultPanelProps) {
  return (
    <View className='ft-card'>
      {plans.length ? (
        <ScrollView scrollX enhanced showScrollbar={false} className='ft-plans'>
          <View className='ft-plans__inner'>
            {plans.map((plan) => {
              const active = plan.id === activePlanId
              const selected = selectedPlanIds.includes(plan.id)
              return (
                <View key={plan.id} className={`ft-plan${active ? ' ft-plan--active' : ''}`}>
                  <View className='ft-plan__check' onClick={() => onToggleSelect(plan.id)}>
                    <View className={`ft-plan__dot${selected ? ' ft-plan__dot--on' : ''}`} />
                  </View>
                  <Text
                    className={`ft-plan__name${active ? ' ft-plan__name--active' : ''}`}
                    onClick={() => onSwitchPlan(plan.id)}
                  >
                    {plan.name}
                  </Text>
                  <View className='ft-plan__close' onClick={() => onClosePlan(plan.id)}>
                    <Text className='ft-plan__close-text'>×</Text>
                  </View>
                </View>
              )
            })}
          </View>
        </ScrollView>
      ) : null}

      <View className='ft-result-head'>
        <Text className='ft-label'>{labels.resultCount(results.length)}</Text>
      </View>

      {results.length === 0 ? (
        <Empty text={labels.resultEmpty} />
      ) : (
        <>
          <View className='ft-row ft-row--head'>
            <Text className='ft-row__index'>{labels.columnIndex}</Text>
            <Text className='ft-row__code'>{labels.columnCode}</Text>
            <Text className='ft-row__action'>{labels.columnAction}</Text>
          </View>
          {results.slice(0, displayCount).map((item, index) => (
            <View key={`${item.code}-${index}`} className={`ft-row${item.deleted ? ' ft-row--deleted' : ''}`}>
              <Text className='ft-row__index'>{index + 1}</Text>
              <Text className={`ft-row__code${item.deleted ? ' ft-row__code--deleted' : ''}`}>{item.code}</Text>
              <View className='ft-row__action' onClick={() => onToggleDeleted(index)}>
                <Text className={`ft-link${item.deleted ? '' : ' ft-link--danger'}`}>
                  {item.deleted ? labels.rowRestore : labels.rowDelete}
                </Text>
              </View>
            </View>
          ))}
          {displayCount < results.length ? (
            <View className='ft-load-more' onClick={onLoadMore}>
              <Text className='ft-load-more__text'>{labels.loadMore}</Text>
            </View>
          ) : null}
          <View className='ft-result-actions'>
            <View className='ft-btn ft-btn--plain' onClick={onGoExtension}>
              <Text className='ft-btn__text ft-btn__text--plain'>{labels.goPlanExtension}</Text>
            </View>
            <View className='ft-btn ft-btn--plain' onClick={onGoSetProcessing}>
              <Text className='ft-btn__text ft-btn__text--plain'>{labels.goSetProcessing}</Text>
            </View>
            <View className='ft-btn ft-btn--plain' onClick={onGoHistoryReview}>
              <Text className='ft-btn__text ft-btn__text--plain'>{labels.goHistoryReview}</Text>
            </View>
            <View
              className={`ft-btn${copyDisabled ? ' ft-btn--disabled' : ''}`}
              onClick={() => {
                if (!copyDisabled) onOpenCopy()
              }}
            >
              <Text className='ft-btn__text'>{labels.copy}</Text>
            </View>
          </View>
        </>
      )}
    </View>
  )
}
