.home-page {
  /* RN：页面已 disableScroll，根节点需撑满高度，内部 ScrollView 才有滚动区间（H5 下 flex 对块级布局无影响） */
  flex: 1;
  /* 底部间距：H5 走 24px+安全区；RN 端必须为 0（--sa-0），根节点的外部 padding 会压缩内部
     ScrollView 滚动区间，RN 底部间距由 ScrollView 内容容器（index.tsx paddingBottom:24）承担 */
  padding-bottom: var(--sa-0, calc(24px + env(safe-area-inset-bottom)));
}

/* H5：内容不足一屏时撑满视口。
   不能放进 .home-page：RN 端 taro-css-to-react-native 会把 100vh 转成整窗高度，
   min-height 撑破 flex 容器会使内部 ScrollView 底部溢出到 Tab 栏下方（滚到底时末屏内容被 Tab 栏遮住） */
.home-page--h5 {
  min-height: 100vh;
}

/* RN：页面内滚动容器（H5 不渲染该节点） */
.home-scroll {
  flex: 1;
}

/* ---------- 顶部轮播图 ---------- */

/* 正方形轮播：宽高由组件 height prop 注入（= 屏宽），这里只保证图片铺满 */
.banner-swiper {
  width: 100%;
  background: var(--color-bg-card);
}

.banner-swiper__img {
  width: 100%;
  height: 100%;
}

.banner-swiper-wrap {
  position: relative;
  width: 100%;
}

/* H5 沉浸式：NavBar 为 sticky 在文档流内占位（44px + 顶部安全区），
   负边距把轮播图拉到其下方透出，与 RN 端「内容顶到屏幕顶端」效果对齐。
   （仅 H5 生效：RN 端根节点无 home-page--h5 类，且含 env() 的 calc 会被 postcss-rn-calc 剥离） */
.home-page--h5 .banner-swiper-wrap {
  margin-top: calc(-44px - constant(safe-area-inset-top));
  margin-top: calc(-44px - env(safe-area-inset-top));
}

/* 底部浮层：当前页标题 + 指示点。pointer-events: none 透出后不拦截滑动手势
   （H5 为 CSS pointer-events；RN 透传为 style.pointerEvents，RN 0.71+ 支持） */
.banner-swiper__overlay {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  pointer-events: none;
  /* RN 不支持渐变，纯色半透明兜底；H5 用渐变提升文字可读性 */
  background-color: rgba(0, 0, 0, 0.25);
  background-image: linear-gradient(to bottom, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.55));
}

.banner-swiper__title {
  flex: 1;
  min-width: 0;
  font-size: 16px;
  font-weight: 600;
  color: #fff;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.banner-swiper__dots {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin-left: 12px;
  gap: 6px;
}

.banner-swiper__dot {
  width: 6px;
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.5);
}

.banner-swiper__dot--active {
  width: 16px;
  background: #fff;
}

/* 轻量入场渐现（不做交错，RN 性能考虑，产品方案 §6.5） */
@keyframes home-fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.section-title {
  margin-top: 40px;
  display: block;
  padding: 0 0 16px 16px;
  font-size: 17px;
  font-weight: 600;
  animation: home-fade-in 0.3s ease;
}

/* ---------- 推荐功能 ---------- */

.recommend-card {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin: 0 16px 8px;
  animation: home-fade-in 0.3s ease;
}

.recommend-card__item {
  flex: 1;
  display: flex;
  flex-direction: row;
  gap: 6px;
  align-items: center;
  min-height: 44px;
  padding: 14px 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: 0 0 1px 2px var(--color-border);
}

.recommend-card__icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
}

.recommend-card__texts {
  flex: 1;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 4px;
  justify-content: center;
  align-items: flex-start;
}

.recommend-card__label {
  font-size: 15px;
  font-weight: 600;
}

.recommend-card__desc {
  font-size: 10px;
  color: var(--color-text-secondary);
}

/* ---------- 最新开奖卡 ---------- */

.draw-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 0 16px 16px;
  padding: 20px 24px;
  min-height: 44px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  animation: home-fade-in 0.3s ease;
  border: 1px solid var(--color-border);
  box-shadow: 0 0 1px 2px var(--color-border);
}

.draw-card__head {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.draw-card__info {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
}

.draw-card__name {
  display: block;
  font-size: 16px;
  font-weight: 700;
}

.draw-card__issue {
  display: block;
  font-size: 13px;
  color: var(--color-text-secondary);
}

/* 开奖卡片头部：该彩种开奖直播直达入口（播放图标 + 文案，默认灰色，直播窗口内转 primary） */
.draw-card__live-entry {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  min-height: 44px;
}

.draw-card__live-icon {
  width: 16px;
  height: 16px;
  border-radius: 10px;
  background: var(--color-text-placeholder);
  display: flex;
  align-items: center;
  justify-content: center;
}

.draw-card__live-icon--live {
  background: var(--color-primary);
}

.draw-card__live-icon-img {
  width: 9px;
  height: 10px;
  /* 播放三角形视觉重心偏左，右移 1px 光学居中 */
  margin-left: 1px;
}

.draw-card__live-text {
  font-size: 13px;
  color: var(--color-text-secondary);
}

.draw-card__live-text--live {
  color: var(--color-primary);
}

/* 开奖卡片 footer：历史开奖（该彩种开奖页）/ 画规 / 筛选 / 回查入口，次级灰底按钮样式 */
.draw-card__footer {
  display: flex;
  flex-direction: row;
  gap: 8px;
  width: 100%;
  margin-top: 8px;
}

/* 按钮容器负责背景/圆角/flex 居中（RN 端 Text 不支持），文字样式放内部 Text */
.draw-card__footer-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  background: var(--color-primary-light);
  border-radius: var(--radius-sm);
}

.draw-card__footer-btn-text {
  font-size: 14px;
}

/* ---------- 实用工具 ---------- */

/* 每个工具独立卡片（类似推荐功能），flex-wrap 网格平铺（3 列：31% × 3 + 8px × 2 间隙 ≈ 一行） */
.tools-grid {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 16px 8px;
  animation: home-fade-in 0.3s ease;
}

.tools-grid__item {
  width: 31%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 14px 8px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: 0 0 1px 2px var(--color-border);
}

.tools-grid__icon {
  width: 40px;
  height: 40px;
}

.tools-grid__label {
  margin-top: 6px;
  font-size: 12px;
  color: var(--color-text);
}

/* ---------- 专业数据榜 ---------- */

.analyst-card {
  margin: 0 16px 8px;
  padding: 16px 20px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  animation: home-fade-in 0.3s ease;
}

.analyst-card__head {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.analyst-card__info {
  flex: 1;
  min-width: 0;
  margin-left: 12px;
}

.analyst-card__name {
  display: block;
  font-size: 15px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.analyst-card__stats {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: baseline;
  margin-top: 4px;
}

.analyst-card__stat {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-right: 12px;
}

.analyst-card__stat--rate {
  font-size: 15px;
  font-weight: 700;
  color: var(--color-primary);
  margin-left: -8px;
}

.analyst-card__posts {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--color-border);
}

.analyst-card__posts-title {
  display: block;
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 4px;
}

.analyst-card__posts-empty {
  display: block;
  padding: 12px 0;
  font-size: 13px;
  color: var(--color-text-placeholder);
}

.analyst-post {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 44px;
  padding: 6px 0;
}

.analyst-post__tags {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-shrink: 0;
  margin-right: 8px;
  gap: 6px;
}

.analyst-post__title {
  flex: 1;
  min-width: 0;
  font-size: 13px;
  color: var(--color-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.analyst-post__time {
  flex-shrink: 0;
  margin-left: 8px;
  font-size: 12px;
  color: var(--color-text-placeholder);
}