/**
 * 画规工具底部弹层面板（NutUI Popup，双端共享）：
 * 工具选择 / 颜色与线宽 / 智能笔设置 / 基本设置（彩种+期数）/ 数字选择器（高级+简易）。
 * 预测面板交互逻辑移植自源文件数字选择器段（confirmPredictionPanel 的纯前端部分在页面侧）。
 */
import { useEffect, useMemo, useState } from 'react'
import { ScrollView, Text, View } from '@tarojs/components'
import Popup from '@/components/SheetPopup'
import { LOTTERY_OPTIONS } from '@/constants/lottery'
import { drawRuleLabels as labels } from '@/labels/tools'
import {
  DRAW_TOOLS,
  PERIOD_MAX,
  PERIOD_MIN,
  PERIOD_OPTIONS,
  PERIOD_STEP,
  PREDICTION_FIXED_NUMBER_SETS,
  PREDICTION_PAIR_OPTIONS,
  PREDICTION_PREVIEW_ITEMS,
  PREDICTION_SIZE_OPTIONS,
  PREDICTION_NUMBER_OPTIONS,
  SMART_GAP_OPTIONS,
  SMART_LINE_SHAPE_OPTIONS,
  SMART_PEN_COUNT_OPTIONS,
  STROKE_OPTIONS,
  SUM_PREDICTION_NUMBER_OPTIONS,
  SUM_PREDICTION_SIZE_OPTIONS,
  COLOR_OPTIONS,
  currentPredictionLimit,
  isFrontPredictionColumn,
  isPredictionSelectionComplete,
  isSumColumnCell,
  predictionColumnsForActiveCondition,
  predictionConditionsForColumn,
  predictionPositionsForActiveCondition,
  predictionTextLines,
  type ActivePredictionCondition,
  type DigitCellTarget,
  type DrawTool,
  type PredictionCondition,
  type PredictionFillMode,
  type PredictionMode,
  type PredictionPreviewPosition,
  type SmartLineShape,
  type SmartPenColorMode,
} from './model'

const CONDITION_LABELS: Record<PredictionCondition, string> = {
  headTailSum: labels.sumHeadTail,
  hundredTenSum: labels.sumHundredTen,
  thousandHundredSum: labels.sumThousandHundred,
  thousandTenSum: labels.sumThousandTen,
  hundredUnitSum: labels.sumHundredUnit,
  tenUnitSum: labels.sumTenUnit,
  kill: labels.conditionKill,
  stable: labels.stableCode,
  odd: labels.conditionOdd,
  even: labels.conditionEven,
  big: labels.conditionBig,
  small: labels.conditionSmall,
  x: labels.conditionX,
}

const PREVIEW_POSITION_LABELS: Record<PredictionPreviewPosition, string> = {
  thousand: labels.previewPosThousand,
  hundred: labels.previewPosHundred,
  ten: labels.previewPosTen,
  unit: labels.previewPosUnit,
}

export function predictionConditionLabel(condition: ActivePredictionCondition) {
  if (condition === 'none') return ''
  return CONDITION_LABELS[condition] || ''
}

/** 工具 fab 图标字符（源 mobileToolIconText） */
export const TOOL_ICON_TEXT: Record<DrawTool, string> = {
  智能线: 'S',
  直线: '/',
  自由线: 'A',
  添加文字: 'T',
  橡皮擦: '▱',
  实心圆形: '●',
  实心矩形: '■',
  空心圆形: '○',
  空心矩形: '□',
}

const TOOL_LABELS: Record<DrawTool, string> = {
  智能线: labels.toolSmartLine,
  直线: labels.toolStraightLine,
  自由线: labels.toolFreeLine,
  添加文字: labels.toolAddText,
  橡皮擦: labels.toolEraser,
  实心圆形: labels.toolSolidCircle,
  实心矩形: labels.toolSolidRect,
  空心圆形: labels.toolHollowCircle,
  空心矩形: labels.toolHollowRect,
}

const STROKE_LABELS: Record<string, string> = {
  细线: labels.strokeThin,
  中线: labels.strokeMiddle,
  粗线: labels.strokeThick,
}

function SheetHeader({ title, onClose }: { title: string; onClose: () => void }) {
  return (
    <View className='draw-sheet__header'>
      <Text className='draw-sheet__title'>{title}</Text>
      <View className='draw-sheet__close' onClick={onClose}>
        <Text className='draw-sheet__close-text'>×</Text>
      </View>
    </View>
  )
}

// ---------- 工具选择 ----------

export function ToolSheet({
  visible,
  activeTool,
  onSelect,
  onOpenSmartSetting,
  onClose,
}: {
  visible: boolean
  activeTool: DrawTool
  onSelect: (tool: DrawTool) => void
  onOpenSmartSetting: () => void
  onClose: () => void
}) {
  return (
    <Popup visible={visible} onClose={onClose}>
      <View className='draw-sheet'>
        <SheetHeader title={TOOL_LABELS[activeTool]} onClose={onClose} />
        <View className='draw-sheet__tool-grid'>
          {DRAW_TOOLS.map((tool) => (
            <View
              key={tool}
              className={`draw-sheet__tool${activeTool === tool ? ' is-active' : ''}`}
              onClick={() => onSelect(tool)}
            >
              <Text className='draw-sheet__tool-icon'>{TOOL_ICON_TEXT[tool]}</Text>
              <Text className='draw-sheet__tool-name'>{TOOL_LABELS[tool]}</Text>
            </View>
          ))}
        </View>
        {activeTool === '智能线' ? (
          <View className='draw-sheet__smart-entry' onClick={onOpenSmartSetting}>
            <Text className='draw-sheet__smart-entry-text'>{labels.smartSettingTitle}</Text>
          </View>
        ) : null}
      </View>
    </Popup>
  )
}

// ---------- 颜色与线宽 ----------

export function ColorSheet({
  visible,
  activeColor,
  activeStroke,
  onColorChange,
  onStrokeChange,
  onClose,
}: {
  visible: boolean
  activeColor: string
  activeStroke: string
  onColorChange: (color: string) => void
  onStrokeChange: (stroke: string) => void
  onClose: () => void
}) {
  return (
    <Popup visible={visible} onClose={onClose}>
      <View className='draw-sheet'>
        <SheetHeader title={labels.smartColor} onClose={onClose} />
        <View className='draw-sheet__color-grid'>
          {COLOR_OPTIONS.map((color) => (
            <View
              key={color}
              className={`draw-sheet__color${activeColor === color ? ' is-active' : ''}`}
              style={{ backgroundColor: color }}
              onClick={() => onColorChange(color)}
            >
              {activeColor === color ? <Text className='draw-sheet__color-check'>✓</Text> : null}
            </View>
          ))}
        </View>
        <View className='draw-sheet__stroke-row'>
          {STROKE_OPTIONS.map((stroke) => (
            <View
              key={stroke.label}
              className={`draw-sheet__stroke${activeStroke === stroke.label ? ' is-active' : ''}`}
              onClick={() => onStrokeChange(stroke.label)}
            >
              <View className='draw-sheet__stroke-line' style={{ height: stroke.width }} />
              <Text className='draw-sheet__stroke-label'>{STROKE_LABELS[stroke.label] || stroke.label}</Text>
            </View>
          ))}
        </View>
      </View>
    </Popup>
  )
}

// ---------- 智能笔设置 ----------

export interface SmartSetting {
  enabled: boolean
  colorMode: SmartPenColorMode
  lineShape: SmartLineShape
  gap: number
  penCount: number
}

export function SmartSettingSheet({
  visible,
  value,
  onChange,
  onClose,
}: {
  visible: boolean
  value: SmartSetting
  onChange: (patch: Partial<SmartSetting>) => void
  onClose: () => void
}) {
  const multiEnabled = value.penCount > 1
  return (
    <Popup visible={visible} onClose={onClose}>
      <View className='draw-sheet'>
        <SheetHeader title={labels.smartSettingTitle} onClose={onClose} />

        <View className='draw-sheet__row'>
          <Text className='draw-sheet__row-label'>{labels.smartSwitch}</Text>
          <Text className='draw-sheet__row-hint'>{labels.smartSwitchHint}</Text>
          {/* 命中区 ≥44px（触控约定），视觉滑轨 50x28 右对齐在内 */}
          <View className='draw-sheet__switch-hit' onClick={() => onChange({ enabled: !value.enabled })}>
            <View className={`draw-sheet__switch${value.enabled ? ' is-on' : ''}`}>
              <View className='draw-sheet__switch-dot' />
            </View>
          </View>
        </View>

        <View className='draw-sheet__row'>
          <Text className='draw-sheet__row-label'>{labels.smartColor}</Text>
          <View className='draw-sheet__options'>
            <View
              className={`draw-sheet__option${value.colorMode === 'single' ? ' is-active' : ''}`}
              onClick={() => onChange({ colorMode: 'single' })}
            >
              <Text className='draw-sheet__option-text'>{labels.smartSingleColor}</Text>
            </View>
            <View
              className={`draw-sheet__option${value.colorMode === 'multi' ? ' is-active' : ''}${multiEnabled ? '' : ' is-disabled'}`}
              onClick={() => {
                if (multiEnabled) onChange({ colorMode: 'multi' })
              }}
            >
              <Text className='draw-sheet__option-text'>{labels.smartMultiColor}</Text>
            </View>
          </View>
        </View>

        <View className='draw-sheet__row'>
          <Text className='draw-sheet__row-label'>{labels.smartLineShape}</Text>
          <View className='draw-sheet__options'>
            {SMART_LINE_SHAPE_OPTIONS.map((option) => (
              <View
                key={option.value}
                className={`draw-sheet__option${value.lineShape === option.value ? ' is-active' : ''}`}
                onClick={() => onChange({ lineShape: option.value })}
              >
                <Text className='draw-sheet__option-text'>
                  {option.value === 'up' ? labels.lineShapeUp : option.value === 'down' ? labels.lineShapeDown : labels.lineShapeStraight}
                </Text>
              </View>
            ))}
          </View>
        </View>

        <View className='draw-sheet__row'>
          <Text className='draw-sheet__row-label'>{labels.smartInterval}</Text>
          <View className='draw-sheet__options'>
            {SMART_GAP_OPTIONS.map((option) => (
              <View
                key={option.value}
                className={`draw-sheet__option${value.gap === option.value && multiEnabled ? ' is-active' : ''}${multiEnabled ? '' : ' is-disabled'}`}
                onClick={() => {
                  if (multiEnabled) onChange({ gap: option.value })
                }}
              >
                <Text className='draw-sheet__option-text'>{labels.smartGapOption(option.value)}</Text>
              </View>
            ))}
          </View>
        </View>

        <View className='draw-sheet__row'>
          <Text className='draw-sheet__row-label'>{labels.smartPenCount}</Text>
          <View className='draw-sheet__options'>
            {SMART_PEN_COUNT_OPTIONS.map((count) => (
              <View
                key={count}
                className={`draw-sheet__option${value.penCount === count ? ' is-active' : ''}`}
                onClick={() => onChange({ penCount: count })}
              >
                <Text className='draw-sheet__option-text'>{labels.smartPenCountOption(count)}</Text>
              </View>
            ))}
          </View>
        </View>

        <View className='draw-sheet__confirm' onClick={onClose}>
          <Text className='draw-sheet__confirm-text'>{labels.confirm}</Text>
        </View>
      </View>
    </Popup>
  )
}

// ---------- 基本设置（彩种 + 期数） ----------

export function BasicSettingSheet({
  visible,
  lotteryCode,
  periodCount,
  onLotteryChange,
  onPeriodChange,
  onClose,
}: {
  visible: boolean
  lotteryCode: string
  periodCount: number
  onLotteryChange: (code: string) => void
  onPeriodChange: (count: number) => void
  onClose: () => void
}) {
  return (
    <Popup visible={visible} onClose={onClose}>
      <View className='draw-sheet'>
        <SheetHeader title={labels.settingsTitle} onClose={onClose} />

        <View className='draw-sheet__row'>
          <Text className='draw-sheet__row-label'>{labels.lotterySwitch}</Text>
          <View className='draw-sheet__options'>
            {LOTTERY_OPTIONS.map((item) => (
              <View
                key={item.value}
                className={`draw-sheet__option${lotteryCode === item.value ? ' is-active' : ''}`}
                onClick={() => onLotteryChange(item.value)}
              >
                <Text className='draw-sheet__option-text'>{item.label}</Text>
              </View>
            ))}
          </View>
        </View>

        <View className='draw-sheet__row'>
          <Text className='draw-sheet__row-label'>{labels.periodSetting}</Text>
          <View className='draw-sheet__options'>
            {PERIOD_OPTIONS.map((count) => (
              <View
                key={count}
                className={`draw-sheet__option${periodCount === count ? ' is-active' : ''}`}
                onClick={() => onPeriodChange(count)}
              >
                <Text className='draw-sheet__option-text'>{count}</Text>
              </View>
            ))}
          </View>
        </View>

        <View className='draw-sheet__row'>
          <Text className='draw-sheet__row-label'>{labels.periodAdjust}</Text>
          <View className='draw-sheet__options'>
            <View
              className={`draw-sheet__option${periodCount <= PERIOD_MIN ? ' is-disabled' : ''}`}
              onClick={() => {
                if (periodCount > PERIOD_MIN) onPeriodChange(periodCount - PERIOD_STEP)
              }}
            >
              <Text className='draw-sheet__option-text'>{labels.periodDecrease}</Text>
            </View>
            <View className='draw-sheet__option is-static'>
              <Text className='draw-sheet__option-text'>{labels.periodLabel(periodCount)}</Text>
            </View>
            <View
              className={`draw-sheet__option${periodCount >= PERIOD_MAX ? ' is-disabled' : ''}`}
              onClick={() => {
                if (periodCount < PERIOD_MAX) onPeriodChange(periodCount + PERIOD_STEP)
              }}
            >
              <Text className='draw-sheet__option-text'>{labels.periodIncrease}</Text>
            </View>
          </View>
        </View>

        <View className='draw-sheet__confirm' onClick={onClose}>
          <Text className='draw-sheet__confirm-text'>{labels.confirm}</Text>
        </View>
      </View>
    </Popup>
  )
}

// ---------- 数字选择器（预测标记） ----------

export interface PredictionConfirmPayload {
  condition: ActivePredictionCondition
  conditionLabel: string
  numbers: string[]
  fillMode: PredictionFillMode
}

export function PredictionSheet({
  visible,
  cell,
  drawCount,
  color,
  onConfirm,
  onSimpleSelect,
  onClose,
}: {
  visible: boolean
  cell: DigitCellTarget | null
  drawCount: number
  color: string
  onConfirm: (payload: PredictionConfirmPayload) => void
  onSimpleSelect: (value: string) => void
  onClose: () => void
}) {
  const [mode, setMode] = useState<PredictionMode>('simple')
  const [condition, setCondition] = useState<ActivePredictionCondition>('none')
  const [fillMode, setFillMode] = useState<PredictionFillMode>('solid')
  const [selectedNumbers, setSelectedNumbers] = useState<Set<string>>(new Set())

  const isSumCell = isSumColumnCell(cell)
  const canSwitchMode = Boolean(cell && !isSumCell && isFrontPredictionColumn(cell.columnIndex, drawCount))

  // 源 resetPredictionDraft：面板每次打开重置
  useEffect(() => {
    if (!visible) return
    setCondition('none')
    setFillMode('solid')
    setSelectedNumbers(new Set())
    setMode(cell && !isSumColumnCell(cell) && isFrontPredictionColumn(cell.columnIndex, drawCount) ? 'advanced' : 'simple')
  }, [visible, cell, drawCount])

  const conditionOptions = useMemo(() => {
    if (!cell) return []
    return predictionConditionsForColumn(cell.columnIndex, drawCount).map((value) => ({
      value,
      label: CONDITION_LABELS[value],
    }))
  }, [cell, drawCount])

  const sortedNumbers = useMemo(
    () => [...selectedNumbers].sort((a, b) => Number(a) - Number(b)),
    [selectedNumbers],
  )

  const limit = currentPredictionLimit(condition)
  const fixedNumbers = condition === 'none' ? undefined : PREDICTION_FIXED_NUMBER_SETS[condition]
  const previewLines = predictionTextLines(
    { condition, conditionLabel: predictionConditionLabel(condition), numbers: sortedNumbers },
    labels.stablePrevCode,
  )
  const activePositions = predictionPositionsForActiveCondition(condition, cell, drawCount)
  const canConfirm =
    mode === 'advanced' &&
    predictionColumnsForActiveCondition(condition, cell, drawCount).length > 0 &&
    isPredictionSelectionComplete(condition, sortedNumbers)

  function handleConditionClick(next: PredictionCondition) {
    if (!conditionOptions.some((item) => item.value === next)) return
    if (condition === next) {
      setCondition('none')
      trimSelection('none', selectedNumbers)
      return
    }
    setCondition(next)
    if (next === 'x') {
      setSelectedNumbers(new Set())
      return
    }
    const fixed = PREDICTION_FIXED_NUMBER_SETS[next]
    const base = fixed ? new Set(fixed) : selectedNumbers
    if (fixed) setSelectedNumbers(base)
    trimSelection(next, base)
  }

  function trimSelection(target: ActivePredictionCondition, base: Set<string>) {
    const targetLimit = currentPredictionLimit(target)
    const sorted = [...base].sort((a, b) => Number(a) - Number(b))
    if (sorted.length > targetLimit) {
      setSelectedNumbers(new Set(sorted.slice(0, targetLimit)))
    }
  }

  function toggleNumber(value: string) {
    if (condition === 'x' || fixedNumbers) return
    const next = new Set(selectedNumbers)
    if (next.has(value)) {
      next.delete(value)
    } else if (next.size < limit) {
      next.add(value)
    }
    setSelectedNumbers(next)
  }

  function isNumberDisabled(value: string) {
    if (condition === 'x' || fixedNumbers) return true
    return !selectedNumbers.has(value) && selectedNumbers.size >= limit
  }

  const numberOptions = isSumCell ? SUM_PREDICTION_NUMBER_OPTIONS : PREDICTION_NUMBER_OPTIONS
  const sizeOptions = isSumCell ? SUM_PREDICTION_SIZE_OPTIONS : PREDICTION_SIZE_OPTIONS

  return (
    <Popup visible={visible} onClose={onClose}>
      <View className='draw-sheet draw-sheet--prediction'>
        <View className='draw-sheet__header'>
          <Text className='draw-sheet__title'>{labels.digitPickerTitle}</Text>
          {canSwitchMode ? (
            <View className='draw-sheet__mode-switch'>
              <View
                className={`draw-sheet__mode${mode === 'advanced' ? ' is-active' : ''}`}
                onClick={() => setMode('advanced')}
              >
                <Text className='draw-sheet__mode-text'>{labels.modeAdvanced}</Text>
              </View>
              <View
                className={`draw-sheet__mode${mode === 'simple' ? ' is-active' : ''}`}
                onClick={() => setMode('simple')}
              >
                <Text className='draw-sheet__mode-text'>{labels.modeSimple}</Text>
              </View>
            </View>
          ) : null}
          <View className='draw-sheet__close' onClick={onClose}>
            <Text className='draw-sheet__close-text'>×</Text>
          </View>
        </View>

        <ScrollView scrollY className='draw-sheet__prediction-scroll'>
          {mode === 'advanced' ? (
            <View className='draw-sheet__prediction-body'>
              <Text className='draw-sheet__section-label'>{labels.selectCondition}</Text>
              <View className='draw-sheet__options'>
                {conditionOptions.map((item) => (
                  <View
                    key={item.value}
                    className={`draw-sheet__option${condition === item.value ? ' is-active' : ''}`}
                    onClick={() => handleConditionClick(item.value)}
                  >
                    <Text className='draw-sheet__option-text'>{item.label}</Text>
                  </View>
                ))}
              </View>
              <View className='draw-sheet__number-grid'>
                {PREDICTION_NUMBER_OPTIONS.map((item) => (
                  <View
                    key={item}
                    className={`draw-sheet__number${selectedNumbers.has(item) ? ' is-active' : ''}${isNumberDisabled(item) ? ' is-disabled' : ''}`}
                    onClick={() => {
                      if (!isNumberDisabled(item) || selectedNumbers.has(item)) toggleNumber(item)
                    }}
                  >
                    <Text className='draw-sheet__number-text'>{item}</Text>
                  </View>
                ))}
              </View>

              <Text className='draw-sheet__section-label'>{labels.preview}</Text>
              <View className='draw-sheet__fill-row'>
                <View
                  className={`draw-sheet__fill${fillMode === 'solid' ? ' is-active' : ''}`}
                  onClick={() => setFillMode('solid')}
                >
                  <View className='draw-sheet__fill-dot draw-sheet__fill-dot--solid' />
                  <Text className='draw-sheet__fill-text'>{labels.styleSolid}</Text>
                </View>
                <View
                  className={`draw-sheet__fill${fillMode === 'hollow' ? ' is-active' : ''}`}
                  onClick={() => setFillMode('hollow')}
                >
                  <View className='draw-sheet__fill-dot draw-sheet__fill-dot--hollow' />
                  <Text className='draw-sheet__fill-text'>{labels.styleHollow}</Text>
                </View>
              </View>
              <View className='draw-sheet__preview-row'>
                {PREDICTION_PREVIEW_ITEMS.map((item) => {
                  const active = activePositions.includes(item.value)
                  const stableHidden = condition === 'stable' && item.value !== 'thousand'
                  if (stableHidden) return null
                  const stable = condition === 'stable'
                  return (
                    <View key={item.value} className='draw-sheet__preview-item'>
                      <View
                        className={[
                          'draw-sheet__preview-card',
                          active ? 'is-active' : '',
                          active && fillMode === 'hollow' ? 'is-hollow' : '',
                          stable ? 'is-stable' : '',
                        ]
                          .filter(Boolean)
                          .join(' ')}
                        style={active ? (fillMode === 'hollow' ? { borderColor: color } : { backgroundColor: color }) : undefined}
                      >
                        {active
                          ? previewLines.map((line, index) => (
                              <Text
                                key={index}
                                className='draw-sheet__preview-line'
                                numberOfLines={1}
                                style={fillMode === 'hollow' ? { color } : undefined}
                              >
                                {line}
                              </Text>
                            ))
                          : null}
                      </View>
                      <Text className='draw-sheet__preview-label'>{PREVIEW_POSITION_LABELS[item.value]}</Text>
                    </View>
                  )
                })}
              </View>

              <View
                className={`draw-sheet__confirm${canConfirm ? '' : ' is-disabled'}`}
                style={canConfirm ? { backgroundColor: color } : undefined}
                onClick={() => {
                  if (!canConfirm) return
                  onConfirm({
                    condition,
                    conditionLabel: predictionConditionLabel(condition),
                    numbers: sortedNumbers,
                    fillMode,
                  })
                }}
              >
                <Text className='draw-sheet__confirm-text'>{labels.confirm}</Text>
              </View>
            </View>
          ) : (
            <View className='draw-sheet__prediction-body'>
              <Text className='draw-sheet__section-label'>{labels.selectNumbers}</Text>
              <View className='draw-sheet__number-grid'>
                {numberOptions.map((item) => (
                  <View key={item} className='draw-sheet__number' onClick={() => onSimpleSelect(item)}>
                    <Text className='draw-sheet__number-text'>{item}</Text>
                  </View>
                ))}
              </View>
              {!isSumCell ? (
                <View>
                  <Text className='draw-sheet__section-label'>{labels.selectPairs}</Text>
                  <View className='draw-sheet__number-grid'>
                    {PREDICTION_PAIR_OPTIONS.map((item) => (
                      <View key={item} className='draw-sheet__number' onClick={() => onSimpleSelect(item)}>
                        <Text className='draw-sheet__number-text'>{item}</Text>
                      </View>
                    ))}
                  </View>
                </View>
              ) : null}
              <View>
                <Text className='draw-sheet__section-label'>{labels.sizeParity}</Text>
                <View className='draw-sheet__number-grid'>
                  {sizeOptions.map((item) => (
                    <View key={item} className='draw-sheet__number' onClick={() => onSimpleSelect(item)}>
                      <Text className='draw-sheet__number-text'>{item}</Text>
                    </View>
                  ))}
                </View>
              </View>
            </View>
          )}
        </ScrollView>
      </View>
    </Popup>
  )
}
