/**
 * 筛选工具计算内核（移植自 lottery_web FilterToolEntry.vue）。
 * 纯 TS，不依赖 Taro / DOM，H5 与 RN 通用，便于后续单测。
 * 语义严格对齐源文件：lotteryRules / parseBaseCodes / codesFromNumberPicker /
 * matchesAnyPositionSum / getMaxDifference / runFilter（2041-2215 行）/ formatCopyCode。
 */

export type FilterLotteryType = 'qxc' | 'pl5' | 'fc3d'
/** sizeParity 为源文件遗留条件类型（无 UI 入口），保留以兼容条件快照结构 */
export type ConditionKind =
  | 'position'
  | 'sum'
  | 'sumTail'
  | 'difference'
  | 'sizeParity'
  | 'size'
  | 'parity'
  | 'historyExclude'
export type ConditionMode = 'include' | 'exclude'
export type HistoryExcludeMode = 'codes' | 'draws'
export type ValueShortcut = 'large' | 'small' | 'odd' | 'even' | 'prime' | 'composite'
export type Size = 'large' | 'small' | null
export type Parity = 'odd' | 'even' | null

/** 定数规则（源 651-658 lotteryRules） */
export const LOTTERY_RULES: Record<FilterLotteryType, { digitCounts: number[] }> = {
  qxc: { digitCounts: [2, 3, 4] },
  pl5: { digitCounts: [2, 3, 4, 5] },
  fc3d: { digitCounts: [2, 3] },
}

export const DIGITS = Array.from({ length: 10 }, (_, index) => index)
export const LARGE_DIGITS = [5, 6, 7, 8, 9]
export const SMALL_DIGITS = [0, 1, 2, 3, 4]
export const ODD_DIGITS = [1, 3, 5, 7, 9]
export const EVEN_DIGITS = [0, 2, 4, 6, 8]
export const PRIME_DIGITS = [1, 2, 3, 5, 7]
export const COMPOSITE_DIGITS = [0, 4, 6, 8, 9]
/** 位次名称（源 positionNames），按定数从尾部截取 */
export const POSITION_NAMES = ['万位', '千位', '百位', '十位', '个位']
/** 方案名（源 PLAN_NAMES，最多 10 个） */
export const PLAN_NAMES = [
  '方案一',
  '方案二',
  '方案三',
  '方案四',
  '方案五',
  '方案六',
  '方案七',
  '方案八',
  '方案九',
  '方案十',
] as const
export const RESULT_PAGE_SIZE = 20
/** 历史排除回查期数选项 */
export const HISTORY_EXCLUDE_PERIODS = [10, 20, 30, 50]
/**
 * 移动端性能保护：候选大底注数上限（逐位选号 5 定全选 = 10 万注，预留一倍余量）。
 * Web 源文件无此限制；任意位置和值回溯 × 大底注数在移动端可能爆炸，超限时页面层 toast 拒绝执行。
 */
export const MAX_FILTER_CANDIDATES = 200000

export interface SizeParitySelection {
  size: Size
  parity: Parity
}

/** 当前条件编辑状态（源 FilterConditionSnapshot 去掉 kind/mode 的部分） */
export interface ConditionState {
  positionSelections: number[][]
  sumSelections: number[]
  sumGroupSelections: Record<string, number[]>
  activeSumMode: string
  sumSelectedPositions: number[]
  sumUseAnyPositions: boolean
  sumTailSelections: number[]
  sumTailGroupSelections: Record<string, number[]>
  activeSumTailMode: string
  sumTailSelectedPositions: number[]
  sumTailUseAnyPositions: boolean
  differenceSelections: Record<string, number[]>
  activeDifferencePair: string
  sizeParitySelections: SizeParitySelection[]
  sizeCountSelections: number[]
  parityCountSelections: number[]
  historyExcludePositions: number[]
  historyExcludeInput: string
  historyExcludePeriod: number
  historyExcludeMode: HistoryExcludeMode
  historyExcludeCodes: string[]
}

export interface FilterConditionSnapshot extends ConditionState {
  kind: ConditionKind
  mode: ConditionMode
}

export interface FilterStep {
  id: string
  label: string
  summary: string
  condition: FilterConditionSnapshot
  inputCodes: string[]
  inputCount: number
  outputCount: number
}

/** 多方案持久化结构（storage key：STORAGE_KEYS.filterToolPlans） */
export interface FilterPlan {
  id: string
  name: string
  lotteryType: FilterLotteryType
  digitCount: number
  baseInput: string
  baseSelectedDigits: number[][]
  condition: ConditionState
  activeCondition: ConditionKind | null
  activeMode: ConditionMode
  filterSteps: FilterStep[]
  resultCodes: string[]
}

export interface ResultItem {
  code: string
  sum: number
  sumTail: number
  maxDifference: number
  deleted: boolean
}

export interface DifferencePair {
  key: string
  label: string
  left?: number
  right?: number
}

// ---------- 基础构造 ----------

export function createEmptyDigitSelections(count: number): number[][] {
  return Array.from({ length: count }, () => [] as number[])
}

export function createAllDigitSelections(count: number): number[][] {
  return Array.from({ length: count }, () => [...DIGITS])
}

export function createSizeParitySelections(count: number): SizeParitySelection[] {
  return Array.from({ length: count }, () => ({ size: null as Size, parity: null as Parity }))
}

/** 初始 / 重置条件编辑状态（源 resetCurrentConditionState 的字段部分） */
export function createInitialConditionState(digitCount: number): ConditionState {
  return {
    positionSelections: createEmptyDigitSelections(digitCount),
    sumSelections: [],
    sumGroupSelections: {},
    activeSumMode: String(digitCount),
    sumSelectedPositions: Array.from({ length: digitCount }, (_, index) => index),
    sumUseAnyPositions: false,
    sumTailSelections: [],
    sumTailGroupSelections: {},
    activeSumTailMode: String(digitCount),
    sumTailSelectedPositions: Array.from({ length: digitCount }, (_, index) => index),
    sumTailUseAnyPositions: false,
    differenceSelections: {},
    activeDifferencePair: 'any',
    sizeParitySelections: createSizeParitySelections(digitCount),
    sizeCountSelections: [],
    parityCountSelections: [],
    historyExcludePositions: [],
    historyExcludeInput: '',
    historyExcludePeriod: 10,
    historyExcludeMode: 'codes',
    historyExcludeCodes: [],
  }
}

export function createStepId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
}

export function cloneSteps(steps: FilterStep[]): FilterStep[] {
  return JSON.parse(JSON.stringify(steps)) as FilterStep[]
}

export function cloneConditionState(cond: ConditionState): ConditionState {
  return JSON.parse(JSON.stringify(cond)) as ConditionState
}

// ---------- 派生选项 ----------

/** 位次标签（源 positionLabels：positionNames.slice(5 - digitCount)） */
export function getPositionLabels(digitCount: number): string[] {
  return POSITION_NAMES.slice(5 - digitCount)
}

/** 两码差位置对（源 differencePairs）：任意两位 + 全部位置组合 */
export function getDifferencePairs(digitCount: number): DifferencePair[] {
  const labels = getPositionLabels(digitCount)
  return [
    { key: 'any', label: '任意两位差' },
    ...labels.flatMap((label, left) =>
      labels.slice(left + 1).map((right, offset) => ({
        key: `${left}-${left + offset + 1}`,
        label: `${label}${right}差`,
        left,
        right: left + offset + 1,
      })),
    ),
  ]
}

/** N 定和 / N 定合选项（源 sumModeOptions）：digitCount 定 → 2 定 */
export function getSumModeOptions(digitCount: number): { key: string; count: number }[] {
  return Array.from({ length: Math.max(0, digitCount - 1) }, (_, index) => {
    const count = digitCount - index
    return { key: String(count), count }
  })
}

/** 大小 / 奇偶比例可选值（源 ratioValues）：digitCount → 0 */
export function getRatioValues(digitCount: number): number[] {
  return Array.from({ length: digitCount + 1 }, (_, index) => digitCount - index)
}

/** 比例文案（源 ratioLabel）：选中大/奇个数 : 小/偶个数 */
export function ratioLabel(value: number, digitCount: number): string {
  return `${value}:${digitCount - value}`
}

/** 质数判定（源 isLotteryPrime：1 视为质数，0 非质数） */
export function isLotteryPrime(value: number): boolean {
  if (value === 1) return true
  if (value < 2) return false
  for (let divisor = 2; divisor * divisor <= value; divisor += 1) {
    if (value % divisor === 0) return false
  }
  return true
}

/** 数值快捷操作（源 selectDialogValues：大小以值域中点划分，奇偶/质合按属性） */
export function pickValuesByShortcut(values: number[], shortcut: ValueShortcut): number[] {
  if (!values.length) return []
  const midpoint = Math.ceil((values[0] + values[values.length - 1]) / 2)
  switch (shortcut) {
    case 'large':
      return values.filter((value) => value >= midpoint)
    case 'small':
      return values.filter((value) => value < midpoint)
    case 'odd':
      return values.filter((value) => value % 2 === 1)
    case 'even':
      return values.filter((value) => value % 2 === 0)
    case 'prime':
      return values.filter((value) => isLotteryPrime(value))
    case 'composite':
      return values.filter((value) => !isLotteryPrime(value))
    default:
      return []
  }
}

// ---------- 候选大底 ----------

/** 解析大底输入（源 parseBaseCodes）：多分隔符拆分，过滤非 N 位纯数字，去重 */
export function parseBaseCodes(input: string, digitCount: number): string[] {
  const tokens = String(input || '')
    .split(/[\s,，;；|]+/)
    .map((item) => item.trim())
    .filter(Boolean)
  return [...new Set(tokens.filter((item) => new RegExp(`^\\d{${digitCount}}$`).test(item)))]
}

/** 逐位选号笛卡尔积（源 codesFromNumberPicker：某位未选时按 0-9 全量） */
export function codesFromNumberPicker(selections: number[][]): string[] {
  return selections.reduce<string[]>(
    (codes, selected) => {
      const allowedDigits = selected.length ? selected : DIGITS
      return codes.flatMap((code) => allowedDigits.map((digit) => code + digit))
    },
    [''],
  )
}

/** 逐位选号注数预估（用于上限校验，不实际展开） */
export function pickerCandidateCount(selections: number[][]): number {
  return selections.reduce((total, selected) => total * (selected.length || 10), 1)
}

/** 候选号码二选一（源 getInitialCandidateCodes）：大底文本非空用大底，否则用逐位选号 */
export function getInitialCandidateCodes(
  baseInput: string,
  selections: number[][],
  digitCount: number,
): string[] {
  const baseCodes = parseBaseCodes(baseInput, digitCount)
  return baseInput.trim() ? baseCodes : codesFromNumberPicker(selections)
}

// ---------- 号码特征 ----------

/** 任意两位最大绝对差（源 getMaxDifference） */
export function getMaxDifference(values: number[]): number {
  let difference = 0
  for (let index = 0; index < values.length; index += 1) {
    for (let next = index + 1; next < values.length; next += 1) {
      difference = Math.max(difference, Math.abs(values[index] - values[next]))
    }
  }
  return difference
}

export function createResultItem(code: string): ResultItem {
  const values = code.split('').map(Number)
  const sum = values.reduce((total, value) => total + value, 0)
  return { code, sum, sumTail: sum % 10, maxDifference: getMaxDifference(values), deleted: false }
}

/** 任意位置回溯枚举（源 matchesAnyPositionSum）：是否存在 count 个位置之和（或合值）命中选中值 */
export function matchesAnyPositionSum(
  values: number[],
  count: number,
  selectedValues: number[],
  useSumTail = false,
): boolean {
  const visit = (start: number, remaining: number, total: number): boolean => {
    if (!remaining) return selectedValues.includes(useSumTail ? total % 10 : total)
    for (let index = start; index <= values.length - remaining; index += 1) {
      if (visit(index + 1, remaining - 1, total + values[index])) return true
    }
    return false
  }
  return count > 0 && count <= values.length && visit(0, count, 0)
}

/** 单位置大小奇偶规则（源 matchesSingleSizeParity，sizeParity 遗留条件用） */
export function matchesSingleSizeParity(value: number, rule: SizeParitySelection): boolean {
  if (rule.size === 'large' && value < 5) return false
  if (rule.size === 'small' && value > 4) return false
  if (rule.parity === 'odd' && value % 2 === 0) return false
  if (rule.parity === 'even' && value % 2 !== 0) return false
  return true
}

// ---------- 历史排除 ----------

export type HistoryExcludeValidation =
  | { ok: true; codes: string[] }
  | { ok: false; error: 'invalid' | 'empty'; invalid?: string }

/** 号码组排除输入校验（源 prepareHistoryExclude codes 分支） */
export function validateHistoryExcludeCodes(input: string, length: number): HistoryExcludeValidation {
  const inputs = String(input || '')
    .split(/[\s,，;；]+/)
    .map((item) => item.trim())
    .filter(Boolean)
  const invalid = inputs.find((item) => !new RegExp(`^\\d{${length}}$`).test(item))
  if (invalid) return { ok: false, error: 'invalid', invalid }
  if (!inputs.length) return { ok: false, error: 'empty' }
  return { ok: true, codes: [...new Set(inputs)] }
}

/** 往期开奖同位置号码组（源 prepareHistoryExclude draws 分支）：开奖号取数字位，按排序后位置拼接 */
export function buildHistoryExcludeCodes(
  drawResults: string[],
  positions: number[],
  length: number,
): string[] {
  const sorted = [...positions].sort((left, right) => left - right)
  const historySet = new Set(
    drawResults.map((result) => {
      const digits = (String(result || '').match(/\d/g) || []).join('')
      return sorted.map((position) => digits[position] || '').join('')
    }),
  )
  return [...historySet].filter((code) => code.length === length)
}

// ---------- 筛选执行 ----------

/**
 * 单轮筛选（源 runFilter 2041-2215 行的 reduce 语义严格照抄）。
 * 仅 activeCondition 生效；其余条件字段应为初始空态（页面层 applyConditionMode 已保证）。
 */
export function runFilterOnce(
  candidates: string[],
  cond: ConditionState,
  activeCondition: ConditionKind | null,
  mode: ConditionMode,
  digitCount: number,
): ResultItem[] {
  const differencePairs = getDifferencePairs(digitCount)
  const activeSumDigitCount = cond.activeSumMode === 'base' ? digitCount : Number(cond.activeSumMode)
  const activeSumTailDigitCount = cond.activeSumTailMode === 'base' ? digitCount : Number(cond.activeSumTailMode)
  return candidates.reduce<ResultItem[]>((accepted, code) => {
    const values = code.split('').map(Number)
    const sum = values.reduce((total, value) => total + value, 0)
    const sumTail = sum % 10
    const maxDifference = getMaxDifference(values)
    const positionHit = values.every(
      (value, index) => !cond.positionSelections[index].length || cond.positionSelections[index].includes(value),
    )
    const positionMatches =
      activeCondition !== 'position' ||
      !cond.positionSelections.some((item) => item.length) ||
      (mode === 'include' ? positionHit : !positionHit)
    const hasSizeParity = cond.sizeParitySelections.some((item) => item.size || item.parity)
    const sizeParityHit = values.every((value, index) =>
      matchesSingleSizeParity(value, cond.sizeParitySelections[index]),
    )
    const sizeParityMatches =
      activeCondition !== 'sizeParity' || !hasSizeParity || (mode === 'include' ? sizeParityHit : !sizeParityHit)
    const largeCount = values.filter((value) => value >= 5).length
    const oddCount = values.filter((value) => value % 2 === 1).length
    const sizeMatches =
      activeCondition !== 'size' ||
      !cond.sizeCountSelections.length ||
      (mode === 'include'
        ? cond.sizeCountSelections.includes(largeCount)
        : !cond.sizeCountSelections.includes(largeCount))
    const parityMatches =
      activeCondition !== 'parity' ||
      !cond.parityCountSelections.length ||
      (mode === 'include'
        ? cond.parityCountSelections.includes(oddCount)
        : !cond.parityCountSelections.includes(oddCount))
    if (!positionMatches || !sizeParityMatches || !sizeMatches || !parityMatches) return accepted
    const historyExcludeHit =
      activeCondition === 'historyExclude' &&
      cond.historyExcludeCodes.length > 0 &&
      cond.historyExcludeCodes.includes(
        [...cond.historyExcludePositions]
          .sort((left, right) => left - right)
          .map((position) => values[position])
          .join(''),
      )
    if (historyExcludeHit) return accepted
    const selectedSumValues =
      cond.activeSumMode === 'base' ? cond.sumSelections : cond.sumGroupSelections[cond.activeSumMode] || []
    const sumHit =
      cond.activeSumMode === 'base'
        ? selectedSumValues.includes(sum)
        : cond.sumUseAnyPositions
          ? matchesAnyPositionSum(values, activeSumDigitCount, selectedSumValues)
          : cond.sumSelectedPositions.length === activeSumDigitCount &&
            selectedSumValues.includes(
              cond.sumSelectedPositions.reduce((total, position) => total + values[position], 0),
            )
    if (activeCondition === 'sum' && selectedSumValues.length && (mode === 'include' ? !sumHit : sumHit)) {
      return accepted
    }
    const selectedSumTailValues =
      cond.activeSumTailMode === 'base'
        ? cond.sumTailSelections
        : cond.sumTailGroupSelections[cond.activeSumTailMode] || []
    const sumTailHit =
      cond.activeSumTailMode === 'base'
        ? selectedSumTailValues.includes(sumTail)
        : cond.sumTailUseAnyPositions
          ? matchesAnyPositionSum(values, activeSumTailDigitCount, selectedSumTailValues, true)
          : cond.sumTailSelectedPositions.length === activeSumTailDigitCount &&
            selectedSumTailValues.includes(
              cond.sumTailSelectedPositions.reduce((total, position) => total + values[position], 0) % 10,
            )
    if (activeCondition === 'sumTail' && selectedSumTailValues.length && (mode === 'include' ? !sumTailHit : sumTailHit)) {
      return accepted
    }
    const selectedDifferencePairs = differencePairs.filter((pair) => cond.differenceSelections[pair.key]?.length)
    const differenceHit = selectedDifferencePairs.every((pair) => {
      const selected = cond.differenceSelections[pair.key]
      if (pair.key === 'any') {
        return values.some((value, index) =>
          values.slice(index + 1).some((next) => selected.includes(Math.abs(value - next))),
        )
      }
      if (pair.left === undefined || pair.right === undefined) return false
      return selected.includes(Math.abs(values[pair.left] - values[pair.right]))
    })
    if (
      activeCondition === 'difference' &&
      selectedDifferencePairs.length &&
      (mode === 'include' ? !differenceHit : differenceHit)
    ) {
      return accepted
    }
    accepted.push({ code, sum, sumTail, maxDifference, deleted: false })
    return accepted
  }, [])
}

// ---------- 复制补位 ----------

/**
 * X 补位（源复制弹层 formatCopyCode）：
 * 不满足条件原样返回；否则在 padPositions 指定的目标位放 X，其余位按序填入号码数字。
 */
export function padCodeAtPositions(
  code: string,
  targetLength: number,
  padPositions: number[],
  requiredCount: number,
  canApply: boolean,
): string {
  if (!canApply || code.length >= targetLength || padPositions.length !== requiredCount) return code
  const padPositionSet = new Set(padPositions)
  let codeIndex = 0
  return Array.from({ length: targetLength }, (_, index) =>
    padPositionSet.has(index) ? 'X' : code[codeIndex++] || '',
  ).join('')
}

/** 复制文本（源 displayedCopyText）：补位后去重，按分隔符连接 */
export function buildCopyText(
  codes: string[],
  separator: 'comma' | 'space',
  pad: boolean,
  targetLength: number,
  padPositions: number[],
  requiredCount: number,
  canApply: boolean,
): string {
  const items = [
    ...new Set(
      codes.map((code) => (pad ? padCodeAtPositions(code, targetLength, padPositions, requiredCount, canApply) : code)),
    ),
  ]
  return items.join(separator === 'comma' ? ',' : ' ')
}
