.cge-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

.cge-card {
  margin: 16px;
  padding: 20px 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.cge-label {
  display: block;
  margin: 16px 0 8px;
  font-size: 15px;
  font-weight: 600;
  color: var(--color-text);
}

.cge-card .cge-label:first-child {
  margin-top: 0;
}

.cge-label-row {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  flex-wrap: wrap;
  margin: 16px 0 8px;
}

.cge-card .cge-label-row:first-child {
  margin-top: 0;
}

.cge-label-row .cge-label {
  margin: 0;
  margin-right: 8px;
}

.cge-hint {
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.5;
}

.cge-tip {
  display: block;
  margin-top: 12px;
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

/* Chips 单选/多选（与历史回查/集合处理同款交互，触控 ≥44px） */
.chips {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 16px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.chip--active {
  background: var(--color-primary-light);
}

.chip--disabled {
  opacity: 0.45;
}

.chip__text {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.chip__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

.cge-mode-tabs {
  margin-top: 16px;
}

/* 输入框 */
.cge-textarea {
  width: 100%;
  min-height: 104px;
  padding: 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
  font-size: 14px;
  box-sizing: border-box;
}

.cge-textarea--lg {
  min-height: 150px;
}

.cge-textarea--sm {
  min-height: 84px;
}

/* 位置填充分组 */
.cge-group {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--color-border);
}

.cge-group .cge-label {
  margin-top: 8px;
}

.cge-group .cge-textarea {
  margin-top: 12px;
}

/* 定位组合基础号码组卡片 */
.cge-unit {
  margin-top: 12px;
  padding: 12px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
}

.cge-unit__head {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin-bottom: 8px;
}

.cge-unit__title {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
}

.cge-unit__key {
  margin-left: 8px;
  font-size: 12px;
  color: var(--color-primary);
}

.cge-unit__delete {
  margin-left: auto;
  padding: 8px 0 8px 12px;
}

.cge-unit__delete--disabled {
  opacity: 0.45;
}

.cge-unit__delete-text {
  font-size: 13px;
  color: var(--color-danger);
}

.cge-unit .chips {
  margin-top: 8px;
}

.cge-unit .cge-textarea {
  margin-top: 12px;
}

.cge-add-unit {
  display: flex;
  align-items: center;
  justify-content: center;
  align-self: flex-start;
  min-height: 44px;
  margin-top: 12px;
  padding: 0 16px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.cge-add-unit__text {
  font-size: 14px;
  color: var(--color-text-secondary);
}

/* 操作按钮 */
.cge-actions {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin-top: 24px;
}

.cge-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  border-radius: 999px;
  background: var(--color-primary);
}

.cge-btn--plain {
  background: var(--color-bg);
}

.cge-btn--disabled {
  opacity: 0.6;
}

.cge-btn__text {
  font-size: 15px;
  font-weight: 600;
  color: #fff;
}

.cge-btn__text--plain {
  color: var(--color-text-secondary);
}

/* 结果区 */
.cge-result-head {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  justify-content: space-between;
}

.cge-result-head .cge-label {
  margin-top: 0;
}

.cge-result-count {
  font-size: 13px;
  color: var(--color-primary);
}

.cge-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 44px;
  border-top: 1px solid var(--color-border);
}

.cge-row--head {
  border-top-width: 0; /* RN 端不支持 border-top: none */
}

.cge-row--head .cge-row__index,
.cge-row--head .cge-row__code {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.cge-row__index {
  width: 56px;
  font-size: 13px;
  color: var(--color-text-secondary);
}

.cge-row__code {
  flex: 1;
  font-size: 14px;
  color: var(--color-text);
  letter-spacing: 1px;
}

/* 加载更多 */
.load-more {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
}

.load-more__text {
  font-size: 13px;
  color: var(--color-primary);
}

/* 复制弹层 */
.cge-sheet {
  padding: 16px 16px var(--sa-16, calc(16px + env(safe-area-inset-bottom)));
}

.cge-sheet__title {
  display: block;
  text-align: center;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 12px;
}

.cge-copy-preview {
  max-height: 30vh;
  padding: 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
  box-sizing: border-box;
}

.cge-copy-preview__text {
  font-size: 13px;
  color: var(--color-text);
  line-height: 1.6;
  word-break: break-all;
}

.cge-sheet__settings {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 14px;
}

.cge-sheet__actions {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin-top: 16px;
}
