.feed-pred {
  margin: 0 16px 12px;
  padding: 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.feed-pred__head {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin-bottom: 10px;
}

.feed-pred__author {
  margin-left: 8px;
  font-size: 13px;
  color: var(--color-text-secondary);
  max-width: 96px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.feed-pred__tags {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  margin-left: auto;
}

.feed-pred__tag {
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  margin-left: 6px;
}

.feed-pred__tag--type {
  background: rgba(184, 50, 55, 0.1);
  color: var(--color-primary);
}

.feed-pred__tag--dim {
  background: rgba(52, 152, 219, 0.1);
  color: var(--color-info);
}

.feed-pred__title {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.5;
  color: var(--color-text);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.feed-pred__foot {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin-top: 12px;
}

.feed-pred__time {
  font-size: 12px;
  color: var(--color-text-placeholder);
}

.feed-pred__stat {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-left: 16px;
}
