/** 中国大陆手机号校验：1 开头 + 第二位 3-9（已分配号段）+ 共 11 位 */
export function isValidCnPhone(value: string) {
  return /^1[3-9]\d{9}$/.test(String(value || '').trim())
}

/** 手机号脱敏：合法国内手机号保留前 3 后 4，其余（未绑定/异常值）原样展示 */
export function maskCnPhone(value: string) {
  const phone = String(value || '').trim()
  return isValidCnPhone(phone) ? `${phone.slice(0, 3)}****${phone.slice(7)}` : phone
}
