import { View, Text } from '@tarojs/components'
import Taro from '@tarojs/taro'
import { toolsLabels } from '@/labels/tools'
import { navigateTo } from '@/utils/nav'
import './index.css'

interface ToolItem {
  id: keyof typeof toolsLabels.items
  /** 需订阅工具显示「订阅」角标 */
  subscription: boolean
  /** MVP 画规暂无独立页（走首页开奖卡片入口），其余工具均已落地 */
  path?: string
}

/** 工具注册表（Web PRD §6.8；深度遗漏已下线不展示） */
const TOOLS: ToolItem[] = [
  { id: 'filter', subscription: true, path: '/pages/tools/filter/index' },
  { id: 'code-group-extension', subscription: true, path: '/pages/tools/code-group-extension/index' },
  { id: 'history-review', subscription: false, path: '/pages/tools/history-review/index' },
  { id: 'set-processing', subscription: true, path: '/pages/tools/set-processing/index' },
  { id: 'draw-rule', subscription: true, path: '/pages/tools/draw-rule/index' },
]

/** 实用工具列表：卡片网格 2 列（产品方案 §6.8） */
export default function ToolsPage() {
  const open = (tool: ToolItem) => {
    if (tool.path) {
      navigateTo({ url: tool.path })
    } else {
      Taro.showToast({ title: toolsLabels.comingSoon, icon: 'none' })
    }
  }

  return (
    <View className='tools-page'>
      <View className='tools-grid'>
        {TOOLS.map((tool) => {
          const meta = toolsLabels.items[tool.id]
          return (
            <View key={tool.id} className='tool-card' onClick={() => open(tool)}>
              <Text
                className={`tool-card__badge${tool.subscription ? '' : ' tool-card__badge--free'}`}
              >
                {tool.subscription ? toolsLabels.subscriptionBadge : toolsLabels.freeBadge}
              </Text>
              <Text className='tool-card__name'>{meta.name}</Text>
              <Text className='tool-card__desc'>{meta.desc}</Text>
            </View>
          )
        })}
      </View>
    </View>
  )
}
