.hit-badge {
  display: inline-flex;
  padding: 4px 12px;
  border-radius: 6px;
  font-size: 12px;
  line-height: 1.4;
}

.hit-badge--hit {
  color: var(--color-success);
  background: rgba(16, 185, 129, 0.12);
}

.hit-badge--miss {
  color: var(--color-danger);
  background: rgba(239, 68, 68, 0.12);
}

.hit-badge--pending {
  color: var(--color-warning);
  background: rgba(245, 158, 11, 0.12);
}
