import { useState } from 'react'
import { View, Text, Input } from '@tarojs/components'
import Taro from '@tarojs/taro'
import { useAuth } from '@/store/auth'
import { sendSmsCodeApi } from '@/services/api'
import { authLabels } from '@/labels/auth'
import { isValidCnPhone } from '@/utils/phone'
import { goAfterAuth, goBack, navigateTo } from '@/utils/nav'
import { useCodeSender } from '@/hooks/useCodeSender'
import '@/styles/auth-shared.css'
import './index.css'

/** 全屏模态登录页（产品方案 §6.11）：左上角关闭；手机验证码 / 手机号+密码双模式，成功按 ?redirect= 回跳 */
export default function LoginPage() {
  const { login, loginBySmsCode } = useAuth()
  const redirect = Taro.getCurrentInstance().router?.params?.redirect
  const [mode, setMode] = useState<'password' | 'sms'>('sms')
  const [phone, setPhone] = useState('')
  const [password, setPassword] = useState('')
  const [smsCode, setSmsCode] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [remember, setRemember] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const { countdown, disabled: sendDisabled, sendCode } = useCodeSender(
    () => sendSmsCodeApi(phone.trim()),
    { sentTitle: authLabels.login.codeSent, failTitle: authLabels.errors.loginFailed },
  )

  /** 从公开页唤起时用户可放弃：优先返回上一页，栈空（直达/刷新）回首页 */
  const closeModal = () => goBack('/pages/home/index')

  const goForgotPassword = () => {
    navigateTo({ url: '/pages/forgot-password/index' })
  }

  const clickSendSmsCode = () => {
    const phoneNumber = phone.trim()
    if (!phoneNumber) {
      Taro.showToast({ title: authLabels.errors.phoneRequired, icon: 'none' })
      return
    }
    if (!isValidCnPhone(phoneNumber)) {
      Taro.showToast({ title: authLabels.errors.phoneInvalid, icon: 'none' })
      return
    }
    sendCode()
  }

  const submit = async () => {
    if (submitting) return
    if (mode === 'password') {
      // 密码登录走 /biz/user/login 的自由格式 account 列：手机号、存量用户名账号都允许，
      // 不做手机号格式限制（否则存量用户名账号被永久锁在门外），交由后端校验
      if (!phone.trim()) {
        Taro.showToast({ title: authLabels.errors.accountRequired, icon: 'none' })
        return
      }
      if (!password) {
        Taro.showToast({ title: authLabels.errors.passwordRequired, icon: 'none' })
        return
      }
    } else {
      if (!phone.trim()) {
        Taro.showToast({ title: authLabels.errors.phoneRequired, icon: 'none' })
        return
      }
      if (!isValidCnPhone(phone.trim())) {
        Taro.showToast({ title: authLabels.errors.phoneInvalid, icon: 'none' })
        return
      }
      if (!smsCode.trim()) {
        Taro.showToast({ title: authLabels.errors.smsCodeRequired, icon: 'none' })
        return
      }
    }
    setSubmitting(true)
    try {
      if (mode === 'password') {
        // 密码登录：短信注册的新账号 account 即手机号；存量用户名账号仍以其 account 登录
        await login(phone.trim(), password, remember)
      } else {
        await loginBySmsCode(phone.trim(), smsCode.trim(), remember)
      }
      goAfterAuth(redirect)
    } catch (err: any) {
      Taro.showToast({ title: err?.message || authLabels.errors.loginFailed, icon: 'none' })
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <View className='auth-page'>
      {/* 关闭入口仅 H5 渲染：RN 端默认导航栏自带返回键（栈空兜底场景仅存在于 H5 直达/刷新） */}
      {process.env.TARO_ENV === 'h5' && (
        <View className='auth-page__close' onClick={closeModal}>
          <Text className='auth-page__close-icon'>✕</Text>
        </View>
      )}

      <Text className='auth-page__title'>{authLabels.login.title}</Text>

      <View className='auth-tabs'>
        <Text
          className={`auth-tabs__item${mode === 'sms' ? ' auth-tabs__item--active' : ''}`}
          onClick={() => setMode('sms')}
        >
          {authLabels.login.tabSms}
        </Text>
        <Text
          className={`auth-tabs__item${mode === 'password' ? ' auth-tabs__item--active' : ''}`}
          onClick={() => setMode('password')}
        >
          {authLabels.login.tabPassword}
        </Text>
      </View>

      {/* 两种模式共用账号输入：验证码模式限手机号（数字键盘 / 11 位）；密码模式不限格式，
          兼容存量用户名账号（后端按 account 列自由匹配） */}
      <View className='auth-field'>
        <Input
          className='auth-field__input'
          type={mode === 'sms' ? 'number' : 'text'}
          maxlength={mode === 'sms' ? 11 : undefined}
          value={phone}
          placeholder={mode === 'sms' ? authLabels.login.phonePlaceholder : authLabels.login.accountOrPhonePlaceholder}
          onInput={(e) => setPhone(e.detail.value)}
        />
      </View>

      {mode === 'password' ? (
        <View className='auth-field'>
          <Input
            className='auth-field__input'
            value={password}
            password={!showPassword}
            placeholder={authLabels.login.passwordPlaceholder}
            onInput={(e) => setPassword(e.detail.value)}
          />
          <Text className='auth-field__toggle' onClick={() => setShowPassword(!showPassword)}>
            {showPassword ? authLabels.hidePassword : authLabels.showPassword}
          </Text>
        </View>
      ) : (
        <View className='auth-field'>
          <Input
            className='auth-field__input'
            type='number'
            maxlength={6}
            value={smsCode}
            placeholder={authLabels.login.smsCodePlaceholder}
            onInput={(e) => setSmsCode(e.detail.value)}
          />
          <Text
            className={`auth-field__toggle${sendDisabled ? ' auth-field__toggle--disabled' : ''}`}
            onClick={clickSendSmsCode}
          >
            {countdown > 0 ? authLabels.login.resendAfter(countdown) : authLabels.login.sendCode}
          </Text>
        </View>
      )}

      <View className='auth-row'>
        <View className='checkbox' onClick={() => setRemember(!remember)}>
          <View className={`checkbox__box${remember ? ' checkbox__box--checked' : ''}`}>
            {remember ? <Text className='checkbox__tick'>✓</Text> : null}
          </View>
          <Text className='checkbox__label'>{authLabels.login.keepLogin}</Text>
        </View>
        <Text className='auth-row__link' onClick={goForgotPassword}>
          {authLabels.login.forgotPassword}
        </Text>
      </View>

      <View className={`auth-submit${submitting ? ' auth-submit--disabled' : ''}`} onClick={submit}>
        <Text className='auth-submit__text'>{submitting ? authLabels.login.submitting : authLabels.login.submit}</Text>
      </View>

      {/* 验证码模式登录即注册（autoLogin 自动注册未注册手机号），以说明文案代替注册入口 */}
      {mode === 'sms' && (
        <View className='auth-footer'>
          <Text className='auth-hint'>{authLabels.login.autoRegisterHint}</Text>
        </View>
      )}
    </View>
  )
}
