import {
  fetchForumComments,
  publishForumComment,
  editForumComment,
  deleteForumComment,
  collectForumComment,
  likeForumComment,
  unlikeForumComment,
  fetchPredictionComments,
  publishPredictionComment,
  collectPredictionComment,
  likePredictionComment,
  unlikePredictionComment,
} from '@/services/api'
import type { CommentAdapter } from './CommentSection'

/**
 * 评论区双 adapter（Web PRD §6.7.4）：
 * - 交流帖：forumId 数据源，分页，支持编辑/删除
 * - 预测帖：forecastId 数据源（后端独立表），一次全量，无编辑/删除接口
 */
export const forumCommentAdapter: CommentAdapter = {
  loadComments: (sourceId, pageNum, pageSize) => fetchForumComments({ forumId: sourceId, pageNum, pageSize }),
  loadReplies: (commentId, pageNum, pageSize) => fetchForumComments({ commentId, pageNum, pageSize }),
  publish: ({ sourceId, content, parentId }) => publishForumComment({ forumId: sourceId, content, parentId }),
  edit: ({ id, sourceId, content, parentId }) => editForumComment({ id, forumId: sourceId, content, parentId }),
  remove: (id) => deleteForumComment(id),
  like: (id, currentlyLiked) => (currentlyLiked ? unlikeForumComment(id) : likeForumComment(id)),
  collect: (id) => collectForumComment(id),
}

export const predictionCommentAdapter: CommentAdapter = {
  // 预测帖评论一次全量，忽略分页参数
  loadComments: (sourceId) => fetchPredictionComments({ forecastId: sourceId }),
  loadReplies: (commentId) => fetchPredictionComments({ commentId }),
  publish: ({ sourceId, content, parentId }) => publishPredictionComment({ forecastId: sourceId, content, parentId }),
  like: (id, currentlyLiked) => (currentlyLiked ? unlikePredictionComment(id) : likePredictionComment(id)),
  collect: (id) => collectPredictionComment(id),
}
