import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { ScrollView, View, Text, Input } from '@tarojs/components'
import Taro, { useDidShow, usePullDownRefresh } from '@tarojs/taro'
import Popup from '@/components/SheetPopup'
import Switch from '@nutui/nutui-react-taro/dist/es/packages/switch'
import { useAuth, redirectToLogin } from '@/store/auth'
import { fetchProfileDashboard, fetchUserIntegral, updateUserInfo, uploadAvatar } from '@/services/api'
import type { ProfileDashboardResponse, ForecastPost } from '@/types'
import { getSlugByLotteryCode, getDimensionLabel } from '@/constants/lottery'
import { currentRoute, goPostDetail, goTools, switchTab } from '@/utils/nav'
import { formatTime } from '@/utils/formatTime'
import { lotteryLabels, profileLabels } from '@/labels'
import { mineLabels } from '@/labels/mine'
import Avatar from '@/components/Avatar'
import Empty from '@/components/Empty'
import Skeleton from '@/components/Skeleton'
import HitBadge from '@/components/HitBadge'
import LotteryTag from '@/components/LotteryTag'
import NavBar, { STATUS_BAR_HEIGHT } from '@/components/NavBar'
import RefreshControl from '@/components/RefreshControl'
import ChangePasswordSheet from './ChangePasswordSheet'
import iconProfile from '@/assets/tabbar/profile_active.png'
import './index.css'

/** RN 端结构分端：RN 不支持 sticky，页面内滚动 + NavBar 覆盖吸顶；H5 保持页面级滚动 + sticky */
const IS_RN = process.env.TARO_ENV === 'rn'

/** RN 端 NavBar 总高度：状态栏 + 44px 导航内容 + 1px 底部分隔线（与首页同款算法） */
const RN_NAV_BAR_HEIGHT = STATUS_BAR_HEIGHT + 45

function clampRate(rate?: number): number {
  const value = Number(rate || 0)
  if (!Number.isFinite(value)) return 0
  return Math.min(100, Math.max(0, value))
}

/** 我的（一级 Tab）：Hero 卡 + 预测表现 + 最新预测 + 功能列表（产品方案 §6.9，MVP 裁剪） */
export default function ProfilePage() {
  const { isLoggedIn, profile, logout, refreshProfile } = useAuth()

  const [integral, setIntegral] = useState<string | null>(null)
  const [dashboard, setDashboard] = useState<ProfileDashboardResponse | null>(null)
  const [dashboardLoading, setDashboardLoading] = useState(false)

  const [uploading, setUploading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [formNickname, setFormNickname] = useState('')

  const [settingsVisible, setSettingsVisible] = useState(false)
  const [notifyOn, setNotifyOn] = useState(false) // 通知开关预留：纯 UI 状态
  const [aboutVisible, setAboutVisible] = useState(false)
  const [agreementVisible, setAgreementVisible] = useState(false)
  const clearCacheTapAt = useRef(0)

  /**
   * 弹层单状态机：null 关闭 / 'edit' 编辑资料 / 'pwd' 修改密码（edit 之上的二级层）。
   * 相比两个独立布尔，「pwd 打开时 edit 必然关闭」由构造保证；pwd 层所有退出路径
   * （‹ 返回键 / 蒙层点击 / RN 物理返回 / 保存成功）行为一致——都回到编辑资料弹层
   */
  const [sheet, setSheet] = useState<'edit' | 'pwd' | null>(null)

  const loadIntegral = useCallback(async () => {
    try {
      const res = await fetchUserIntegral()
      setIntegral(res?.value != null ? String(res.value) : null)
    } catch {
      setIntegral(null) // 失败回退 profile.integralValue
    }
  }, [])

  const loadDashboard = useCallback(async (userId: number) => {
    setDashboardLoading(true)
    try {
      const res = await fetchProfileDashboard({ userId, rounds: 10, recentLimit: 3 })
      setDashboard(res || null)
    } catch {
      setDashboard(null) // 聚合接口部分失败回退空数据，不崩溃
    } finally {
      setDashboardLoading(false)
    }
  }, [])

  useEffect(() => {
    if (isLoggedIn && profile?.id) {
      loadIntegral()
      loadDashboard(profile.id)
    } else {
      setIntegral(null)
      setDashboard(null)
    }
  }, [isLoggedIn, profile?.id, loadIntegral, loadDashboard])

  useDidShow(() => {
    if (isLoggedIn) refreshProfile()
  })

  usePullDownRefresh(async () => {
    if (isLoggedIn && profile?.id) {
      await Promise.all([refreshProfile(), loadIntegral(), loadDashboard(profile.id)])
    } else {
      await refreshProfile()
    }
    Taro.stopPullDownRefresh()
  })

  // RN 端下拉刷新：页面 disableScroll 后 runtime-rn 不再注入页面级 RefreshControl，
  // 改由页面内 ScrollView 透传 refreshControl；H5 端不走这里，仍由上面的 usePullDownRefresh 承接
  const [refreshing, setRefreshing] = useState(false)
  const onRnRefresh = useCallback(async () => {
    setRefreshing(true)
    try {
      if (isLoggedIn && profile?.id) {
        await Promise.all([refreshProfile(), loadIntegral(), loadDashboard(profile.id)])
      } else {
        await refreshProfile()
      }
    } finally {
      setRefreshing(false)
    }
  }, [isLoggedIn, profile?.id, refreshProfile, loadIntegral, loadDashboard])
  // 元素引用稳定化：RN 原生 RefreshControl 对 props diff 敏感，memo 后刷新期间不重建
  const refreshControlEl = useMemo(
    () => <RefreshControl refreshing={refreshing} onRefresh={onRnRefresh} progressViewOffset={RN_NAV_BAR_HEIGHT} />,
    [refreshing, onRnRefresh],
  )

  // ---------- 头像更换：选图 → 上传 → 保存 → 刷新 ----------
  const handleAvatarChange = async () => {
    if (uploading) return
    let filePath = ''
    try {
      const res = await Taro.chooseImage({ count: 1, sizeType: ['compressed'], sourceType: ['album', 'camera'] })
      filePath = res.tempFilePaths?.[0] || ''
    } catch {
      return // 用户取消选择
    }
    if (!filePath) return
    setUploading(true)
    Taro.showLoading({ title: mineLabels.avatarUploading, mask: true })
    try {
      const url = await uploadAvatar(filePath)
      await updateUserInfo({ avatar: url })
      await refreshProfile()
      Taro.showToast({ title: mineLabels.avatarSuccess, icon: 'success' })
    } catch {
      Taro.showToast({ title: mineLabels.avatarFail, icon: 'none' })
    } finally {
      Taro.hideLoading()
      setUploading(false)
    }
  }

  // ---------- 编辑资料（仅昵称；手机号走绑定/换绑短信流程，地址 MVP 不需要） ----------
  const openEdit = () => {
    setFormNickname(profile?.nickname || '')
    setSheet('edit')
  }

  const handleSaveProfile = async () => {
    if (saving) return
    const nickname = formNickname.trim()
    if (!nickname || nickname.length > 30) {
      Taro.showToast({ title: mineLabels.nicknameInvalid, icon: 'none' })
      return
    }
    setSaving(true)
    try {
      // updateUserInfo 仅透传出现的字段（白名单 nickname/avatar/phone/address），只传 nickname 不影响其余字段
      await updateUserInfo({ nickname })
      await refreshProfile()
      setSheet(null)
      Taro.showToast({ title: mineLabels.saveSuccess, icon: 'success' })
    } catch {
      Taro.showToast({ title: mineLabels.saveFail, icon: 'none' })
    } finally {
      setSaving(false)
    }
  }

  // ---------- 功能列表 ----------
  const handleComingSoon = () => {
    Taro.showToast({ title: mineLabels.comingSoon, icon: 'none' })
  }

  /** 清除缓存：Toast 二次确认 → logout + 清 storage */
  const handleClearCache = () => {
    const now = Date.now()
    if (now - clearCacheTapAt.current > 3000) {
      clearCacheTapAt.current = now
      Taro.showToast({ title: mineLabels.clearCacheFirstTip, icon: 'none' })
      return
    }
    clearCacheTapAt.current = 0
    logout()
    Taro.clearStorage().catch(() => {})
    setSettingsVisible(false)
    Taro.showToast({ title: mineLabels.clearCacheDone, icon: 'none' })
  }

  const handleLogout = () => {
    logout()
    Taro.showToast({ title: mineLabels.logoutSuccess, icon: 'none' })
  }

  // ---------- 未登录空态 ----------
  if (!isLoggedIn || !profile) {
    return (
      <View className={IS_RN ? 'profile-page' : 'profile-page profile-page--h5'}>
        <NavBar title={mineLabels.navTitle} icon={iconProfile} />
        <View className='guest'>
          <Avatar size={72} />
          <Text className='guest__title'>{mineLabels.guestTitle}</Text>
          <Text className='guest__desc'>{mineLabels.guestDesc}</Text>
          <View className='guest__btn' onClick={() => redirectToLogin(currentRoute())}>
            <Text className='guest__btn-text'>{mineLabels.guestAction}</Text>
          </View>
        </View>
      </View>
    )
  }

  // ---------- 派生展示数据 ----------
  const memberFlag = Number(profile.memberFlag || 0)
  const expireDate = String(profile.memberExpireTime || '').trim().slice(0, 10)
  const memberText = memberFlag > 0 ? (expireDate ? mineLabels.memberValidTo(expireDate) : mineLabels.memberActive) : mineLabels.memberNone
  const integralText = integral ?? (profile.integralValue != null ? String(profile.integralValue) : '--')
  const stats = [
    { label: mineLabels.statFollowing, value: profile.followingCount },
    { label: mineLabels.statFollowers, value: profile.followerCount },
    { label: mineLabels.statForecasts, value: profile.forecastCount },
    { label: mineLabels.statForums, value: profile.forumCount },
  ]
  const trend = dashboard?.trend || []
  const modeSummaries = dashboard?.modeSummaries || []
  const recentForecasts = dashboard?.recentForecasts || []

  const renderForecastCard = (post: ForecastPost) => (
    <View
      key={post.id}
      className='forecast-card'
      onClick={() => goPostDetail({ partition: getSlugByLotteryCode(post.lotteryCode), type: 'prediction', id: post.id })}
    >
      <View className='forecast-card__head'>
        <LotteryTag code={post.lotteryCode} />
        {post.lotteryDrawNum ? <Text className='forecast-card__issue'>{lotteryLabels.issuePrefix(post.lotteryDrawNum)}</Text> : null}
        <Text className='forecast-card__phase'>{post.forecastPhase === '1' ? mineLabels.planPhase : mineLabels.singlePhase}</Text>
        <HitBadge hitFlag={post.hitFlag} hitDetail={post.hitDetail} />
      </View>
      {post.title ? <Text className='forecast-card__title'>{post.title}</Text> : null}
      {(post.planVOList || []).length > 0 ? (
        <View className='forecast-card__plans'>
          {(post.planVOList || []).map((plan, idx) => {
            const label = [getDimensionLabel(plan.planMode), plan.codeMode].filter(Boolean).join(' · ') || mineLabels.planTagFallback
            return (
              <Text key={idx} className='plan-tag'>
                {label}
              </Text>
            )
          })}
        </View>
      ) : null}
      <View className='forecast-card__foot'>
        <Text className='forecast-card__time'>{formatTime(post.createTime)}</Text>
        <Text className='forecast-card__meta'>{mineLabels.commentCollect(post.commentNum || 0, post.collectNum || 0)}</Text>
      </View>
    </View>
  )

  /** 页面主体：H5 走页面级滚动（NavBar sticky 吸顶）；RN 由页面内 ScrollView 承载 */
  const content = (
    <>
      {/* Hero 卡 */}
      <View className='hero'>
        <View className='hero__main'>
          <View className='hero__avatar' onClick={handleAvatarChange}>
            <Avatar src={profile.avatar} name={profile.nickname || profile.account} size={64} />
          </View>
          <View className='hero__info'>
            <Text className='hero__nickname'>{profile.nickname || profile.account || '--'}</Text>
            <Text className='hero__member'>{memberText}</Text>
            <Text className='hero__avatar-hint'>{mineLabels.avatarChangeHint}</Text>
          </View>
          <View className='hero__edit' onClick={openEdit}>
            <Text className='hero__edit-text'>{profileLabels.editProfile}</Text>
          </View>
        </View>
        <View className='hero__integral'>
          <Text className='hero__integral-label'>{mineLabels.integralBalance}</Text>
          <Text className='hero__integral-value'>{integralText}</Text>
          <View className='hero__recharge' onClick={() => Taro.showToast({ title: profileLabels.rechargeComingSoon, icon: 'none' })}>
            <Text className='hero__recharge-text'>{profileLabels.recharge}</Text>
          </View>
        </View>
        <View className='stats'>
          {stats.map((item) => (
            <View key={item.label} className='stats__item'>
              <Text className='stats__value'>{Number(item.value || 0)}</Text>
              <Text className='stats__label'>{item.label}</Text>
            </View>
          ))}
        </View>
      </View>

      {/* 预测表现面板 */}
      <View className='panel'>
        <Text className='panel__title'>{mineLabels.performanceTitle}</Text>
        {dashboardLoading && !dashboard ? (
          <Skeleton rows={2} card={false} />
        ) : dashboard ? (
          <>
            <View className='rate-hero'>
              <Text className='rate-hero__value'>{clampRate(dashboard.hitRate)}%</Text>
              <View className='rate-hero__meta'>
                <Text className='rate-hero__label'>{mineLabels.hitRateLabel}</Text>
                <Text className='rate-hero__stat'>{mineLabels.hitStat(dashboard.totalHits || 0, dashboard.totalIssues || 0)}</Text>
              </View>
            </View>
            <Text className='rate-meta'>
              {mineLabels.issueStat(dashboard.totalIssues || 0, dashboard.cycleCount || 0, dashboard.forecastTotal || 0)}
            </Text>
            {trend.length > 0 ? (
              <View className='trend'>
                <Text className='panel__subtitle'>{mineLabels.trendTitle}</Text>
                {trend.map((item, idx) => (
                  <View key={`${item.label}-${idx}`} className='trend__row'>
                    <Text className='trend__label'>{item.label}</Text>
                    <View className='trend__track'>
                      <View className='trend__bar' style={{ width: `${clampRate(item.rate)}%` }} />
                    </View>
                    <Text className='trend__value'>{clampRate(item.rate)}%</Text>
                  </View>
                ))}
              </View>
            ) : null}
            {modeSummaries.length > 0 ? (
              <View className='chips-wrap'>
                <Text className='panel__subtitle'>{mineLabels.modeSummaryTitle}</Text>
                <View className='chips'>
                  {modeSummaries.map((item, idx) => (
                    <Text key={`${item.codeMode}-${idx}`} className='chip'>
                      {item.codeMode} · {item.description}
                    </Text>
                  ))}
                </View>
              </View>
            ) : null}
          </>
        ) : (
          <Empty text={mineLabels.dashboardEmpty} />
        )}
      </View>

      {/* 我的最新预测 */}
      {recentForecasts.length > 0 ? (
        <View className='panel'>
          <View className='panel__head'>
            <Text className='panel__title'>{mineLabels.recentTitle}</Text>
            <Text className='panel__more' onClick={() => switchTab({ url: '/pages/forum/index' })}>
              {mineLabels.viewAll}
            </Text>
          </View>
          {recentForecasts.map(renderForecastCard)}
        </View>
      ) : null}

      {/* 功能列表 */}
      <View className='menu'>
        <View className='menu__item' onClick={goTools}>
          <Text className='menu__label'>{profileLabels.tools}</Text>
          <Text className='menu__arrow'>›</Text>
        </View>
        <View className='menu__item' onClick={handleComingSoon}>
          <Text className='menu__label'>{mineLabels.featurePromotion}</Text>
          <Text className='menu__arrow'>›</Text>
        </View>
        <View className='menu__item' onClick={handleComingSoon}>
          <Text className='menu__label'>{mineLabels.featureRechargeRecords}</Text>
          <Text className='menu__arrow'>›</Text>
        </View>
        <View className='menu__item menu__item--last' onClick={() => setSettingsVisible(true)}>
          <Text className='menu__label'>{profileLabels.settings}</Text>
          <Text className='menu__arrow'>›</Text>
        </View>
      </View>

      {/* 退出登录 */}
      <View className='logout' onClick={handleLogout}>
        <Text className='logout__text'>{mineLabels.logout}</Text>
      </View>

      {/* 编辑资料弹层 */}
      <Popup visible={sheet === 'edit'} onClose={() => setSheet(null)}>
        <View className='sheet'>
          <Text className='sheet__title'>{mineLabels.editTitle}</Text>
          <View className='form__item'>
            <Text className='form__label'>{mineLabels.fieldNickname}</Text>
            <Input
              className='form__input'
              value={formNickname}
              maxlength={30}
              placeholder={mineLabels.nicknamePlaceholder}
              onInput={(e) => setFormNickname(e.detail.value)}
            />
          </View>
          <View className='sheet__row sheet__row--last pwd-entry' onClick={() => setSheet('pwd')}>
            <Text className='sheet__row-label'>{mineLabels.changePassword}</Text>
            <Text className='menu__arrow'>›</Text>
          </View>
          {/* 弹层提交按钮：自绘主按钮（NutButton 在 RN 端样式丢失且 loading 图标崩溃，禁用） */}
          <View
            className={`sheet__submit${saving ? ' sheet__submit--disabled' : ''}`}
            onClick={handleSaveProfile}
          >
            <Text className='sheet__submit-text'>{saving ? mineLabels.saveSubmitting : mineLabels.save}</Text>
          </View>
        </View>
      </Popup>

      {/* 修改密码弹层（编辑资料弹层之上的二级层）：所有退出路径（返回键/蒙层/物理返回/保存成功）
          一律回到编辑资料弹层，半填的昵称在页面 state 中保留不丢 */}
      <ChangePasswordSheet
        visible={sheet === 'pwd'}
        boundPhone={profile.phone}
        onBack={() => setSheet('edit')}
        onClose={() => setSheet('edit')}
      />

      {/* 设置弹层 */}
      <Popup visible={settingsVisible} onClose={() => setSettingsVisible(false)}>
        <View className='sheet'>
          <Text className='sheet__title'>{profileLabels.settings}</Text>
          <View className='sheet__row'>
            <View className='sheet__row-info'>
              <Text className='sheet__row-label'>{mineLabels.settingsNotify}</Text>
              <Text className='sheet__row-hint'>{mineLabels.settingsNotifyHint}</Text>
            </View>
            <Switch checked={notifyOn} onChange={setNotifyOn} />
          </View>
          <View className='sheet__row' onClick={handleClearCache}>
            <Text className='sheet__row-label'>{mineLabels.settingsClearCache}</Text>
            <Text className='menu__arrow'>›</Text>
          </View>
          <View className='sheet__row' onClick={() => setAboutVisible(true)}>
            <Text className='sheet__row-label'>{mineLabels.settingsAbout}</Text>
            <Text className='menu__arrow'>›</Text>
          </View>
          <View className='sheet__row sheet__row--last' onClick={() => setAgreementVisible(true)}>
            <Text className='sheet__row-label'>{mineLabels.settingsAgreement}</Text>
            <Text className='menu__arrow'>›</Text>
          </View>
        </View>
      </Popup>

      {/* 关于我们 */}
      <Popup visible={aboutVisible} onClose={() => setAboutVisible(false)}>
        <View className='sheet'>
          <Text className='sheet__title'>{mineLabels.aboutTitle}</Text>
          <Text className='sheet__content'>{mineLabels.aboutContent}</Text>
        </View>
      </Popup>

      {/* 用户协议 */}
      <Popup visible={agreementVisible} onClose={() => setAgreementVisible(false)}>
        <View className='sheet'>
          <Text className='sheet__title'>{mineLabels.agreementTitle}</Text>
          <Text className='sheet__content'>{mineLabels.agreementContent}</Text>
        </View>
      </Popup>
    </>
  )

  return (
    <View className={IS_RN ? 'profile-page' : 'profile-page profile-page--h5'}>
      {IS_RN ? (
        <>
          {/* RN 不支持 sticky：页面 config 已 disableScroll，改页面内 ScrollView + NavBar 覆盖吸顶，
              内容预留 NavBar 占位（NavBar 恒不透明，无渐变）；RN 底部间距由内容容器承担（根节点 pb 为 0） */}
          <ScrollView scrollY className='profile-page__scroll' refreshControl={refreshControlEl}>
            <View style={{ paddingTop: RN_NAV_BAR_HEIGHT, paddingBottom: 24 }}>{content}</View>
          </ScrollView>
          <NavBar title={mineLabels.navTitle} icon={iconProfile} overlay />
        </>
      ) : (
        <>
          <NavBar title={mineLabels.navTitle} icon={iconProfile} />
          {content}
        </>
      )}
    </View>
  )
}
