import { useCallback, useEffect, useState } from 'react'
import { View, Text } from '@tarojs/components'
import { usePullDownRefresh, useReachBottom } from '@tarojs/taro'
import Taro from '@tarojs/taro'
import { LOTTERY_LIST, normalizeLotteryCode, getLotteryMeta, type LotteryCode } from '@/constants/lottery'
import { fetchDrawDailyDetail, fetchDrawHistory } from '@/services/api'
import { usePagedList } from '@/hooks/usePagedList'
import { formatBeijingDateTime, getLiveWindowState } from '@/utils/live'
import { goLive } from '@/utils/nav'
import { lotteryLabels } from '@/labels'
import NumberBalls from '@/components/NumberBalls'
import Skeleton from '@/components/Skeleton'
import Empty from '@/components/Empty'
import './index.css'

/** 每日开奖（首页「更多开奖数据」二级页）：分段切彩种 + Hero 卡 + 历史上拉加载（产品方案 §6.2） */
export default function DrawPage() {
  const [code, setCode] = useState<LotteryCode>(() =>
    normalizeLotteryCode(Taro.getCurrentInstance().router?.params?.code),
  )
  const [detail, setDetail] = useState<{ drawNum: string; numbers: string[]; drawTime: string } | null>(null)
  const [detailLoading, setDetailLoading] = useState(true)

  const loadDetail = useCallback(async (c: LotteryCode) => {
    setDetailLoading(true)
    try {
      const res = await fetchDrawDailyDetail(c)
      setDetail(res?.drawNum ? { drawNum: res.drawNum, numbers: res.numbers || [], drawTime: res.drawTime } : null)
    } catch {
      setDetail(null) // 开奖接口异常显示空态不崩溃（降级策略）
    } finally {
      setDetailLoading(false)
    }
  }, [])

  const {
    list,
    loading,
    refreshing,
    error,
    hasMore,
    refresh,
    loadMore,
  } = usePagedList({
    fetchPage: useCallback((pageNum: number) => fetchDrawHistory(code, pageNum, 20), [code]),
    pageSize: 20,
  })

  useEffect(() => {
    loadDetail(code)
    refresh()
  }, [code, loadDetail, refresh])

  usePullDownRefresh(async () => {
    await Promise.all([loadDetail(code), refresh()])
    Taro.stopPullDownRefresh()
  })

  useReachBottom(() => {
    if (hasMore && !loading) loadMore()
  })

  const meta = getLotteryMeta(code)
  const live = getLiveWindowState()

  return (
    <View className='draw-page'>
      {/* 三彩种分段选择器 */}
      <View className='segment'>
        {LOTTERY_LIST.map((item) => (
          <View
            key={item.code}
            className={`segment__item${item.code === code ? ' segment__item--active' : ''}`}
            onClick={() => setCode(item.code)}
          >
            <Text className={`segment__text${item.code === code ? ' segment__text--active' : ''}`}>{item.label}</Text>
          </View>
        ))}
      </View>

      {/* Hero 卡 */}
      <View className='hero'>
        {detailLoading ? (
          <Skeleton rows={1} card={false} />
        ) : detail ? (
          <>
            <View className='hero__head'>
              <View>
                <Text className='hero__name'>{meta.label}</Text>
                <Text className='hero__issue'>{lotteryLabels.issuePrefix(detail.drawNum)}</Text>
              </View>
              <View className='hero__live' onClick={() => goLive(code)}>
                {live.isLive ? <View className='hero__live-dot' /> : null}
                <Text className='hero__live-text'>{live.isLive ? '正在直播' : lotteryLabels.liveEntry}</Text>
              </View>
            </View>
            <NumberBalls numbers={detail.numbers} />
            <Text className='hero__time'>{formatBeijingDateTime(detail.drawTime)}</Text>
          </>
        ) : (
          <Empty text='暂无开奖数据' />
        )}
      </View>

      {/* 历史列表 */}
      <Text className='section-title'>{lotteryLabels.drawHistory}</Text>
      {refreshing && list.length === 0 ? (
        <Skeleton rows={5} />
      ) : error && list.length === 0 ? (
        <Empty text={error} actionText='点击重试' onAction={refresh} />
      ) : list.length === 0 ? (
        <Empty />
      ) : (
        <>
          {list.map((item, idx) => (
            <View key={`${item.drawNum}-${idx}`} className='history-card'>
              <Text className='history-card__issue'>{lotteryLabels.issuePrefix(item.drawNum)}</Text>
              <NumberBalls numbers={item.numbers} size='small' />
            </View>
          ))}
          <View className='list-footer' onClick={() => hasMore && !loading && loadMore()}>
            <Text className='list-footer__text'>
              {loading ? '加载中…' : hasMore ? '加载更多' : '没有更多了'}
            </Text>
          </View>
        </>
      )}
    </View>
  )
}
