import { View, Text } from '@tarojs/components'
import './index.css'

interface NumberBallsProps {
  numbers: string[]
  /** 命中高亮的号码（可选） */
  hitNumbers?: string[]
  size?: 'normal' | 'small'
}

/** 号码球：开奖号码 / 预测号码通用展示 */
export default function NumberBalls({ numbers, hitNumbers, size = 'normal' }: NumberBallsProps) {
  const hitSet = new Set((hitNumbers || []).map(String))
  return (
    <View className={`number-balls number-balls--${size}`}>
      {(numbers || []).map((num, idx) => (
        <View
          key={`${idx}-${num}`}
          className={`number-ball${hitSet.has(String(num)) ? ' number-ball--hit' : ''}`}
        >
          <Text className="number-ball__text">{num}</Text>
        </View>
      ))}
    </View>
  )
}
