import { useEffect, useMemo, useState } from 'react'
import { ScrollView, Text, Textarea, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import Popup from '@/components/SheetPopup'
import Empty from '@/components/Empty'
import PopupCloseIcon from '@/components/PopupCloseIcon'
import { LOTTERY_LIST } from '@/constants/lottery'
import { commonLabels } from '@/labels'
import { codeGroupExtensionLabels as labels } from '@/labels/tools'
import { formatCopyCode } from '@/utils/tools/numberCodes'
import {
  EXTENSION_RULES,
  defaultTailPositions,
  getLocationPositionOptions,
  getPositionLabels,
  locationPositionKey,
  runExpansion,
  runLocationCombination,
  runPositionFill,
  type EngineError,
  type EngineOutcome,
  type ExtensionLotteryType,
  type ResultItem,
} from '@/utils/tools/codeGroupEngine'
import { navigateTo } from '@/utils/nav'
import { readToolPayloadOnce, writeToolPayload } from '@/utils/tools/toolPayload'
import { STORAGE_KEYS } from '@/utils/storage'
import './index.css'

const PAGE_SIZE = 20

type Mode = 'expand' | 'position' | 'location'
type CopySeparator = 'comma' | 'space'
type PositionGroupKey = 'first' | 'second'

interface PositionGroup {
  positions: number[]
  input: string
}

interface LocationUnit {
  id: string
  positions: number[]
  input: string
}

const EMPTY_GROUP: PositionGroup = { positions: [], input: '' }

const MODES: { value: Mode; label: string }[] = [
  { value: 'expand', label: labels.modeExpand },
  { value: 'position', label: labels.modePosition },
  { value: 'location', label: labels.modeLocation },
]

function toast(title: string) {
  Taro.showToast({ title, icon: 'none' })
}

function createLocationUnit(): LocationUnit {
  return { id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, positions: [], input: '' }
}

/** 引擎错误 → codeGroupExtensionLabels.errors 文案 */
function errorText(error: EngineError): string {
  const [first, second] = error.params
  switch (error.key) {
    case 'noExpandTarget':
      return labels.errors.noExpandTarget
    case 'positionsMismatch':
      return labels.errors.positionsMismatch
    case 'targetMustContainSource':
      return labels.errors.targetMustContainSource
    case 'invalidCode':
      return labels.errors.invalidCode(Number(first), String(second))
    case 'positionGroupsRequired':
      return labels.errors.positionGroupsRequired
    case 'locationTargetMin':
      return labels.errors.locationTargetMin
    case 'locationTargetMax':
      return labels.errors.locationTargetMax(Number(first))
    case 'locationUnitRequired':
      return labels.errors.locationUnitRequired
    case 'locationUnitPositionsMin':
      return labels.errors.locationUnitPositionsMin(Number(first))
    case 'locationUnitPositionsInTarget':
      return labels.errors.locationUnitPositionsInTarget(Number(first))
    case 'locationUnitCodesRequired':
      return labels.errors.locationUnitCodesRequired(Number(first), Number(second))
    default:
      return ''
  }
}

/** 码组扩展工具（免费，纯前端计算零 API；移植自 lottery_web CodeGroupExtensionEntry.vue） */
export default function CodeGroupExtensionPage() {
  const [lotteryType, setLotteryType] = useState<ExtensionLotteryType>('pl5')
  const [activeMode, setActiveMode] = useState<Mode>('expand')
  const [sourceCount, setSourceCount] = useState(2)
  const [targetCount, setTargetCount] = useState(3)
  const [baseInput, setBaseInput] = useState('')
  const [sourcePositions, setSourcePositions] = useState<number[]>(() => defaultTailPositions(5, 2))
  const [targetPositions, setTargetPositions] = useState<number[]>(() => defaultTailPositions(5, 3))
  const [firstGroup, setFirstGroup] = useState<PositionGroup>({ ...EMPTY_GROUP })
  const [secondGroup, setSecondGroup] = useState<PositionGroup>({ ...EMPTY_GROUP })
  const [locationTargets, setLocationTargets] = useState<number[]>(() => defaultTailPositions(5, 2))
  const [locationUnits, setLocationUnits] = useState<LocationUnit[]>(() => [createLocationUnit()])
  const [results, setResults] = useState<ResultItem[]>([])
  const [displayCount, setDisplayCount] = useState(PAGE_SIZE)
  const [copyVisible, setCopyVisible] = useState(false)
  const [copySeparator, setCopySeparator] = useState<CopySeparator>('space')
  const [copyPad, setCopyPad] = useState(false)

  const rule = EXTENSION_RULES[lotteryType]
  const positionLabels = getPositionLabels(rule)
  const targetCounts = rule.counts.filter((count) => count > sourceCount)
  const locationOptions = getLocationPositionOptions(lotteryType, rule)

  /** 复制补位目标位数（对齐源 copyTargetLength）：fc3d 补到 3 位，其余补到 4 位 */
  const copyTargetLength = lotteryType === 'fc3d' ? 3 : 4

  const clearResults = () => {
    setResults([])
    setDisplayCount(PAGE_SIZE)
  }

  const resetLocation = (type: ExtensionLotteryType) => {
    setLocationTargets(defaultTailPositions(EXTENSION_RULES[type].positions, 2))
    setLocationUnits([createLocationUnit()])
  }

  /** 切换彩种（源 watch(lotteryType)）：定数/位置回默认，两组与定位组合清空 */
  const changeLottery = (next: ExtensionLotteryType) => {
    if (next === lotteryType) return
    const nextRule = EXTENSION_RULES[next]
    setLotteryType(next)
    setSourceCount(nextRule.counts[0])
    setTargetCount(nextRule.counts[1])
    setSourcePositions(defaultTailPositions(nextRule.positions, nextRule.counts[0]))
    setTargetPositions(defaultTailPositions(nextRule.positions, nextRule.counts[1]))
    setFirstGroup({ ...EMPTY_GROUP })
    setSecondGroup({ ...EMPTY_GROUP })
    resetLocation(next)
    clearResults()
  }

  /** 原定数变化（源 watch(sourceCount)）：扩展定数不在候选内时回退首个候选，原/目标位置重置为末 N 位 */
  const changeSourceCount = (count: number) => {
    if (count === sourceCount) return
    const targets = rule.counts.filter((item) => item > count)
    const nextTarget = targets.length && !targets.includes(targetCount) ? targets[0] : targetCount
    setSourceCount(count)
    setTargetCount(nextTarget)
    setSourcePositions(defaultTailPositions(rule.positions, count))
    setTargetPositions(defaultTailPositions(rule.positions, nextTarget))
    clearResults()
  }

  const changeTargetCount = (count: number) => {
    if (count === targetCount) return
    setTargetCount(count)
    setTargetPositions(defaultTailPositions(rule.positions, count))
    clearResults()
  }

  /**  capped 多选位置（原位置/目标位置）：数量达到定数后未选项禁用 */
  const toggleCappedPosition = (
    list: number[],
    setter: (next: number[]) => void,
    index: number,
    max: number,
  ) => {
    if (list.includes(index)) {
      setter(list.filter((item) => item !== index))
    } else if (list.length < max) {
      setter([...list, index])
    }
    clearResults()
  }

  /** 位置填充组位置选择：已由另一组占用的位置不可选（源 isPositionDisabled） */
  const toggleGroupPosition = (key: PositionGroupKey, index: number) => {
    const group = key === 'first' ? firstGroup : secondGroup
    const other = key === 'first' ? secondGroup : firstGroup
    if (other.positions.includes(index)) return
    const next = group.positions.includes(index)
      ? group.positions.filter((item) => item !== index)
      : [...group.positions, index]
    const updated = { ...group, positions: next }
    if (key === 'first') setFirstGroup(updated)
    else setSecondGroup(updated)
    clearResults()
  }

  const changeGroupInput = (key: PositionGroupKey, value: string) => {
    const group = key === 'first' ? firstGroup : secondGroup
    const updated = { ...group, input: value }
    if (key === 'first') setFirstGroup(updated)
    else setSecondGroup(updated)
  }

  /** 组合目标变化（源 watch(locationTargetPositions)）：各基础组位置裁剪到目标内 */
  const toggleLocationTarget = (index: number) => {
    const next = locationTargets.includes(index)
      ? locationTargets.filter((item) => item !== index)
      : [...locationTargets, index]
    setLocationTargets(next)
    const targetSet = new Set(next)
    setLocationUnits(locationUnits.map((unit) => ({ ...unit, positions: unit.positions.filter((p) => targetSet.has(p)) })))
    clearResults()
  }

  /** 基础组位置选择（源 isLocationUnitPositionDisabled）：须落在组合目标内且不超过目标定数 */
  const toggleUnitPosition = (unit: LocationUnit, index: number) => {
    if (!locationTargets.includes(index)) return
    if (unit.positions.includes(index)) {
      updateUnit(unit.id, { positions: unit.positions.filter((item) => item !== index) })
    } else if (unit.positions.length < locationTargets.length) {
      updateUnit(unit.id, { positions: [...unit.positions, index] })
    } else {
      return
    }
    clearResults()
  }

  const updateUnit = (id: string, patch: Partial<LocationUnit>) => {
    setLocationUnits((units) => units.map((unit) => (unit.id === id ? { ...unit, ...patch } : unit)))
  }

  const addLocationUnit = () => {
    setLocationUnits([...locationUnits, createLocationUnit()])
    clearResults()
  }

  const removeLocationUnit = (id: string) => {
    if (locationUnits.length <= 1) return
    setLocationUnits(locationUnits.filter((unit) => unit.id !== id))
    clearResults()
  }

  const applyOutcome = (outcome: EngineOutcome) => {
    if (outcome.status === 'noop') return
    if (outcome.status === 'error') {
      toast(errorText(outcome.error))
      return
    }
    setResults(outcome.results)
    setDisplayCount(PAGE_SIZE)
  }

  const handleRunExpansion = () => {
    applyOutcome(runExpansion(rule, { baseInput, sourceCount, targetCount, sourcePositions, targetPositions }))
  }

  const handleRunPositionFill = () => {
    applyOutcome(runPositionFill(rule, firstGroup, secondGroup))
  }

  const handleRunLocation = () => {
    applyOutcome(runLocationCombination(rule, locationTargets, locationUnits))
  }

  const clearExpandInput = () => {
    setBaseInput('')
    clearResults()
  }

  const clearPositionGroups = () => {
    setFirstGroup({ ...EMPTY_GROUP })
    setSecondGroup({ ...EMPTY_GROUP })
    clearResults()
  }

  const clearLocationUnits = () => {
    resetLocation(lotteryType)
    clearResults()
  }

  // 跨工具入站 payload（如筛选工具「方案扩展」带入）：读取即删，结构 {lotteryType, digitCount, groups}（最多 2 组）
  useEffect(() => {
    void (async () => {
      const payload = await readToolPayloadOnce<{
        lotteryType?: string
        digitCount?: number
        groups?: string[][]
      }>(STORAGE_KEYS.codeGroupExtensionPayload)
      if (!payload) return
      try {
        const type = String(payload.lotteryType || '') as ExtensionLotteryType
        const payloadRule = EXTENSION_RULES[type]
        const digit = Number(payload.digitCount)
        const groups = (Array.isArray(payload.groups) ? payload.groups : []).slice(0, 2)
        if (
          !payloadRule ||
          !payloadRule.counts.includes(digit) ||
          !groups.length ||
          groups.some((group) => !Array.isArray(group) || !group.length || group.some((code) => typeof code !== 'string'))
        ) {
          throw new Error('invalid code group extension payload')
        }
        const targets = payloadRule.counts.filter((count) => count > digit)
        const nextTarget = targets.length ? targets[0] : digit
        setLotteryType(type)
        setSourceCount(digit)
        setTargetCount(nextTarget)
        setSourcePositions(defaultTailPositions(payloadRule.positions, digit))
        setTargetPositions(defaultTailPositions(payloadRule.positions, nextTarget))
        setBaseInput(groups[0].join(' '))
        setFirstGroup({ positions: [], input: groups[0].join(' ') })
        setSecondGroup({ positions: [], input: (groups[1] || []).join(' ') })
        if (groups[1]?.length) setActiveMode('position')
        resetLocation(type)
        clearResults()
      } catch {
        toast(labels.errors.payloadInvalid)
      }
    })()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  /** 跳筛选工具：纯数字 / 同定数 / 彩种支持校验（对齐源 goToFilterTool） */
  const goToFilterTool = async () => {
    const codes = [...new Set(results.map((item) => item.code))]
    if (!codes.length) return
    if (codes.some((code) => !/^\d+$/.test(code))) {
      toast(labels.errors.filterOnlyDigits)
      return
    }
    const digitCount = codes[0].length
    if (codes.some((code) => code.length !== digitCount)) {
      toast(labels.errors.filterMixedDigit)
      return
    }
    if (!rule.counts.includes(digitCount)) {
      toast(labels.errors.filterUnsupportedDigit(digitCount))
      return
    }
    await writeToolPayload(STORAGE_KEYS.filterToolPayload, { lotteryType, digitCount, codes })
    navigateTo({ url: '/pages/tools/filter/index' })
  }

  const displayedCopyText = useMemo(() => {
    const codes = [...new Set(results.map((item) => (copyPad ? formatCopyCode(item.code, copyTargetLength) : item.code)))]
    return codes.join(copySeparator === 'comma' ? ',' : ' ')
  }, [results, copyPad, copySeparator, copyTargetLength])

  const openCopyModal = () => {
    if (!results.length) return
    setCopyVisible(true)
  }

  const copyResults = async () => {
    if (!displayedCopyText) return
    try {
      await Taro.setClipboardData({ data: displayedCopyText })
      setCopyVisible(false)
      toast(labels.copied(results.length))
    } catch {
      toast(labels.errors.copyFailed)
    }
  }

  /** 下载 txt：仅 H5（Blob + a[download]，动态创建 DOM 仅限该分支，RN 不渲染入口） */
  const downloadResults = () => {
    if (process.env.TARO_ENV !== 'h5' || !displayedCopyText) return
    const blob = new Blob([displayedCopyText], { type: 'text/plain;charset=utf-8' })
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = labels.downloadFileName
    link.click()
    URL.revokeObjectURL(link.href)
  }

  const renderChip = (
    key: string,
    text: string,
    active: boolean,
    disabled: boolean,
    onToggle: () => void,
  ) => (
    <View
      key={key}
      className={`chip${active ? ' chip--active' : ''}${disabled ? ' chip--disabled' : ''}`}
      onClick={() => {
        if (!disabled) onToggle()
      }}
    >
      <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>{text}</Text>
    </View>
  )

  const groupPlaceholder = (length: number) =>
    length ? labels.groupPlaceholder(length, '0123456789'.slice(0, length)) : labels.groupPlaceholderEmpty

  const unitPlaceholder = (positions: number[]) =>
    positions.length < 2
      ? labels.locationUnitPlaceholderEmpty
      : labels.locationUnitPlaceholder(
          positions.length,
          '0123456789'.slice(0, positions.length),
          '9876543210'.slice(0, positions.length),
        )

  const resultEmptyText = activeMode === 'location' ? labels.resultEmptyLocation : labels.resultEmptyExpand

  return (
    <View className='cge-page'>
      {/* 彩种 + 模式 */}
      <View className='cge-card'>
        <Text className='cge-label'>{labels.lotterySection}</Text>
        <View className='chips'>
          {LOTTERY_LIST.map((item) =>
            renderChip(item.toolKey, item.label, item.toolKey === lotteryType, false, () =>
              changeLottery(item.toolKey as ExtensionLotteryType),
            ),
          )}
        </View>
        <View className='chips cge-mode-tabs'>
          {MODES.map((mode) =>
            renderChip(mode.value, mode.label, mode.value === activeMode, false, () => setActiveMode(mode.value)),
          )}
        </View>
      </View>

      {/* 定数扩展 */}
      {activeMode === 'expand' ? (
        <View className='cge-card'>
          <View className='cge-label-row'>
            <Text className='cge-label'>{labels.baseSection}</Text>
            <Text className='cge-hint'>{labels.baseHint}</Text>
          </View>
          <Textarea
            className='cge-textarea cge-textarea--lg'
            value={baseInput}
            placeholder={labels.basePlaceholder(sourceCount, '0123456789'.slice(0, sourceCount))}
            maxlength={-1}
            onInput={(e) => setBaseInput(e.detail.value)}
          />

          <Text className='cge-label'>{labels.sourceCount}</Text>
          <View className='chips'>
            {rule.counts.map((count) =>
              renderChip(`source-${count}`, labels.digitUnit(count), count === sourceCount, false, () =>
                changeSourceCount(count),
              ),
            )}
          </View>

          <Text className='cge-label'>{labels.sourcePositions}</Text>
          <View className='chips'>
            {positionLabels.map((name, index) => {
              const active = sourcePositions.includes(index)
              const disabled = !active && sourcePositions.length >= sourceCount
              return renderChip(`source-pos-${name}`, name, active, disabled, () =>
                toggleCappedPosition(sourcePositions, setSourcePositions, index, sourceCount),
              )
            })}
          </View>

          <Text className='cge-label'>{labels.targetCount}</Text>
          <View className='chips'>
            {targetCounts.map((count) =>
              renderChip(`target-${count}`, labels.digitUnit(count), count === targetCount, false, () =>
                changeTargetCount(count),
              ),
            )}
          </View>

          <Text className='cge-label'>{labels.targetPositions}</Text>
          <View className='chips'>
            {positionLabels.map((name, index) => {
              const active = targetPositions.includes(index)
              const disabled = !active && targetPositions.length >= targetCount
              return renderChip(`target-pos-${name}`, name, active, disabled, () =>
                toggleCappedPosition(targetPositions, setTargetPositions, index, targetCount),
              )
            })}
          </View>

          <Text className='cge-tip'>{labels.expandTip(targetCount)}</Text>

          <View className='cge-actions'>
            <View className='cge-btn cge-btn--plain' onClick={clearExpandInput}>
              <Text className='cge-btn__text cge-btn__text--plain'>{labels.clear}</Text>
            </View>
            <View className='cge-btn' onClick={handleRunExpansion}>
              <Text className='cge-btn__text'>{labels.runExpand}</Text>
            </View>
          </View>
        </View>
      ) : null}

      {/* 指定号码位置填充 */}
      {activeMode === 'position' ? (
        <View className='cge-card'>
          <Text className='cge-tip'>{labels.positionTip}</Text>
          {([
            { key: 'first' as PositionGroupKey, group: firstGroup, title: labels.firstGroupSection },
            { key: 'second' as PositionGroupKey, group: secondGroup, title: labels.secondGroupSection },
          ]).map(({ key, group, title }) => (
            <View key={key} className='cge-group'>
              <Text className='cge-label'>{title}</Text>
              <View className='chips'>
                {positionLabels.map((name, index) => {
                  const other = key === 'first' ? secondGroup : firstGroup
                  const active = group.positions.includes(index)
                  const disabled = !active && other.positions.includes(index)
                  return renderChip(`${key}-pos-${name}`, name, active, disabled, () =>
                    toggleGroupPosition(key, index),
                  )
                })}
              </View>
              <Textarea
                className='cge-textarea'
                value={group.input}
                placeholder={groupPlaceholder(group.positions.length)}
                maxlength={-1}
                onInput={(e) => changeGroupInput(key, e.detail.value)}
              />
            </View>
          ))}

          <View className='cge-actions'>
            <View className='cge-btn cge-btn--plain' onClick={clearPositionGroups}>
              <Text className='cge-btn__text cge-btn__text--plain'>{labels.clear}</Text>
            </View>
            <View className='cge-btn' onClick={handleRunPositionFill}>
              <Text className='cge-btn__text'>{labels.runPositionFill}</Text>
            </View>
          </View>
        </View>
      ) : null}

      {/* 定位组合 */}
      {activeMode === 'location' ? (
        <View className='cge-card'>
          <View className='cge-label-row'>
            <Text className='cge-label'>{labels.locationTitle}</Text>
            <Text className='cge-hint'>{labels.locationHint}</Text>
          </View>
          <Text className='cge-tip'>{labels.locationExample}</Text>

          <View className='cge-label-row'>
            <Text className='cge-label'>{labels.locationTarget}</Text>
            <Text className='cge-hint'>{labels.locationTargetHint(locationTargets.length)}</Text>
          </View>
          <View className='chips'>
            {locationOptions.map((option) =>
              renderChip(
                `location-target-${option.value}`,
                option.label,
                locationTargets.includes(option.value),
                false,
                () => toggleLocationTarget(option.value),
              ),
            )}
          </View>

          {locationUnits.map((unit, index) => (
            <View key={unit.id} className='cge-unit'>
              <View className='cge-unit__head'>
                <Text className='cge-unit__title'>{labels.locationUnitTitle(index)}</Text>
                <Text className='cge-unit__key'>{locationPositionKey(unit.positions) || labels.locationUnitEmpty}</Text>
                <View
                  className={`cge-unit__delete${locationUnits.length === 1 ? ' cge-unit__delete--disabled' : ''}`}
                  onClick={() => removeLocationUnit(unit.id)}
                >
                  <Text className='cge-unit__delete-text'>{labels.locationUnitDelete}</Text>
                </View>
              </View>
              <Text className='cge-hint'>{labels.locationUnitPositions(unit.positions.length)}</Text>
              <View className='chips'>
                {locationOptions.map((option) => {
                  const active = unit.positions.includes(option.value)
                  const disabled =
                    !locationTargets.includes(option.value) ||
                    (!active && unit.positions.length >= locationTargets.length)
                  return renderChip(`unit-${unit.id}-${option.value}`, option.label, active, disabled, () =>
                    toggleUnitPosition(unit, option.value),
                  )
                })}
              </View>
              <Textarea
                className='cge-textarea cge-textarea--sm'
                value={unit.input}
                placeholder={unitPlaceholder(unit.positions)}
                maxlength={-1}
                onInput={(e) => updateUnit(unit.id, { input: e.detail.value })}
              />
            </View>
          ))}

          <View className='cge-add-unit' onClick={addLocationUnit}>
            <Text className='cge-add-unit__text'>{labels.addLocationUnit}</Text>
          </View>

          <View className='cge-actions'>
            <View className='cge-btn cge-btn--plain' onClick={clearLocationUnits}>
              <Text className='cge-btn__text cge-btn__text--plain'>{labels.clear}</Text>
            </View>
            <View className='cge-btn' onClick={handleRunLocation}>
              <Text className='cge-btn__text'>{labels.runLocation}</Text>
            </View>
          </View>
        </View>
      ) : null}

      {/* 结果区 */}
      <View className='cge-card'>
        <View className='cge-result-head'>
          <Text className='cge-label'>
            {activeMode === 'location' ? labels.resultTitleLocation : labels.resultTitleExpand}
          </Text>
          <Text className='cge-result-count'>{labels.resultCount(results.length)}</Text>
        </View>

        {results.length === 0 ? (
          <Empty text={resultEmptyText} />
        ) : (
          <>
            <View className='cge-row cge-row--head'>
              <Text className='cge-row__index'>{labels.columnIndex}</Text>
              <Text className='cge-row__code'>{labels.columnCode}</Text>
            </View>
            {results.slice(0, displayCount).map((item, index) => (
              <View key={`${item.paddedCode || item.code}-${index}`} className='cge-row'>
                <Text className='cge-row__index'>{index + 1}</Text>
                <Text className='cge-row__code'>{item.code}</Text>
              </View>
            ))}
            {displayCount < results.length ? (
              <View className='load-more' onClick={() => setDisplayCount(displayCount + PAGE_SIZE)}>
                <Text className='load-more__text'>{commonLabels.loadMore}</Text>
              </View>
            ) : null}
            <View className='cge-actions'>
              <View className='cge-btn cge-btn--plain' onClick={goToFilterTool}>
                <Text className='cge-btn__text cge-btn__text--plain'>{labels.goFilter}</Text>
              </View>
              <View className='cge-btn' onClick={openCopyModal}>
                <Text className='cge-btn__text'>{labels.copy}</Text>
              </View>
            </View>
          </>
        )}
      </View>

      {/* 复制弹层 */}
      <Popup visible={copyVisible} closeable closeIcon={<PopupCloseIcon />} onClose={() => setCopyVisible(false)}>
        <View className='cge-sheet'>
          <Text className='cge-sheet__title'>{labels.copyModalTitle}</Text>
          <ScrollView scrollY className='cge-copy-preview'>
            <Text className='cge-copy-preview__text'>{displayedCopyText}</Text>
          </ScrollView>

          <View className='cge-sheet__settings'>
            <View className='chips'>
              {(['comma', 'space'] as CopySeparator[]).map((item) =>
                renderChip(`sep-${item}`, item === 'comma' ? labels.separatorComma : labels.separatorSpace, item === copySeparator, false, () =>
                  setCopySeparator(item),
                ),
              )}
            </View>
            <View className='chips'>
              {[true, false].map((item) =>
                renderChip(`pad-${String(item)}`, item ? labels.pad : labels.noPad, item === copyPad, false, () =>
                  setCopyPad(item),
                ),
              )}
            </View>
          </View>

          <View className='cge-sheet__actions'>
            <View className='cge-btn cge-btn--plain' onClick={() => setCopyVisible(false)}>
              <Text className='cge-btn__text cge-btn__text--plain'>{labels.cancel}</Text>
            </View>
            {process.env.TARO_ENV === 'h5' ? (
              <View className='cge-btn cge-btn--plain' onClick={downloadResults}>
                <Text className='cge-btn__text cge-btn__text--plain'>{labels.downloadTxt}</Text>
              </View>
            ) : null}
            <View className='cge-btn' onClick={copyResults}>
              <Text className='cge-btn__text'>{labels.confirmCopy}</Text>
            </View>
          </View>
        </View>
      </Popup>
    </View>
  )
}
