import { resolveHitStatus } from '@/constants/lottery'
import type {
  ForecastPlanPayload,
  ForecastPost,
  ForumPost,
  ProfileDashboardResponse,
} from '@/types'
import { get, post, unwrapAjaxData, ApiError } from './request'

/**
 * 个人中心仪表盘聚合（移植自 lottery_web server/api/profile/dashboard.get.ts）。
 * 直连 Java 后端后，原 BFF 的 8 路并发聚合 + 命中判定 + 预览归一化全部移到客户端。
 * Promise.allSettled 语义保留：单路失败（非 401/403）降级为空，401/403 继续抛出。
 */

interface BackendPage<T = any> {
  total?: number
  rows?: T[]
}

interface BackendFollowItem {
  id?: number | string
  followerId?: number | string
  followingId?: number | string
  followerNickname?: string
  followerAvatar?: string
  followingNickname?: string
  followingAvatar?: string
  createTime?: string
  isFollowed?: boolean
}

function normalizeDateValue(raw: unknown) {
  return raw === null || raw === undefined ? '' : String(raw).trim()
}

function normalizeStringList(raw: unknown): string[] {
  if (Array.isArray(raw)) {
    return raw.map((item) => String(item || '').trim()).filter(Boolean)
  }
  const value = String(raw || '').trim()
  return value ? value.split(',').map((item) => item.trim()).filter(Boolean) : []
}

function lotteryLabel(code?: string) {
  const map: Record<string, string> = {
    '04': '7星彩',
    '350133': '排列5',
    '3d': '3D',
  }
  const value = String(code || '').trim()
  const normalized = value.toLowerCase() === '3d' ? '3d' : value
  return value ? map[normalized] || value : ''
}

function parsePlanHitDetail(plan: ForecastPlanPayload): Record<string, unknown> | null {
  const raw: unknown = plan.hitDetail
  if (!raw) return null
  if (typeof raw !== 'string') return raw as Record<string, unknown>
  try {
    return JSON.parse(raw) as Record<string, unknown>
  } catch {
    return null
  }
}

function hitDetailOverall(plan: ForecastPlanPayload) {
  return String(parsePlanHitDetail(plan)?.overall || '').trim().toLowerCase()
}

/** 命中判定复用统一口径 resolveHitStatus（hitFlag / hitDetail.overall 双源） */
function isHitPlan(plan: ForecastPlanPayload) {
  return resolveHitStatus(plan.hitFlag, hitDetailOverall(plan)) === 'hit'
}

function isMissPlan(plan: ForecastPlanPayload) {
  return resolveHitStatus(plan.hitFlag, hitDetailOverall(plan)) === 'miss'
}

function isSettledPlan(plan: ForecastPlanPayload) {
  return Boolean(plan.hitDetail || plan.drawResult || isHitPlan(plan) || isMissPlan(plan))
}

function isHitForecast(forecast: ForecastPost) {
  return Array.isArray(forecast.planVOList) && forecast.planVOList.some((plan) => isHitPlan(plan))
}

function isSettledForecast(forecast: ForecastPost) {
  return Array.isArray(forecast.planVOList) && forecast.planVOList.some((plan) => isSettledPlan(plan))
}

function toForecastTrendLabel(forecast: ForecastPost, index: number) {
  const lotteryName = lotteryLabel(forecast.lotteryCode)
  const drawNum = String(forecast.lotteryDrawNum || '').trim()
  if (drawNum) return lotteryName ? `${lotteryName} ${drawNum}` : drawNum
  return lotteryName ? `${lotteryName} #${index + 1}` : `#${index + 1}`
}

function toForecastPoint(forecast: ForecastPost, index: number) {
  const settled = isSettledForecast(forecast)
  const hit = isHitForecast(forecast)
  return {
    label: toForecastTrendLabel(forecast, index),
    lotteryCode: String(forecast.lotteryCode || '').trim(),
    forecastPhase: String(forecast.forecastPhase || '').trim(),
    rate: settled ? (hit ? 100 : 0) : 0,
    hits: settled && hit ? 1 : 0,
    total: settled ? 1 : 0,
  }
}

function normalizeRecentForecasts(list: unknown): ForecastPost[] {
  if (!Array.isArray(list)) return []
  return list.map((item): ForecastPost => {
    const raw = item && typeof item === 'object' ? (item as Record<string, unknown>) : {}
    return {
      // 与 BFF 行为一致：id 统一转成字符串（xhs 类型声明为 number，运行时实际为字符串）
      id: String(raw.id || '') as unknown as number,
      lotteryType: typeof raw.lotteryType === 'string' ? raw.lotteryType : '',
      lotteryCode: typeof raw.lotteryCode === 'string' ? raw.lotteryCode : '',
      forecastPhase: typeof raw.forecastPhase === 'string' ? raw.forecastPhase : '',
      lotteryDrawNum: typeof raw.lotteryDrawNum === 'string' ? raw.lotteryDrawNum : '',
      sourceType: typeof raw.sourceType === 'string' ? raw.sourceType : '',
      bizUserId: raw.bizUserId as number | undefined,
      nickname: typeof raw.nickname === 'string' ? raw.nickname : '',
      userAvatar: typeof raw.userAvatar === 'string' ? raw.userAvatar : '',
      createTime: normalizeDateValue(raw.createTime),
      commentNum: Number(raw.commentNum || 0),
      collectNum: Number(raw.collectNum || 0),
      isCollected: Boolean(raw.isCollected),
      planVOList: Array.isArray(raw.planVOList) ? (raw.planVOList as ForecastPlanPayload[]) : [],
    }
  })
}

function normalizeForumPosts(list: unknown): ForumPost[] {
  if (!Array.isArray(list)) return []
  return list.map((item): ForumPost => {
    const raw = item && typeof item === 'object' ? (item as Record<string, unknown>) : {}
    return {
      id: String(raw.id || '') as unknown as number,
      content: typeof raw.content === 'string' ? raw.content : '',
      picsList: normalizeStringList(raw.picsList),
      createTime: normalizeDateValue(raw.createTime),
      updateTime: normalizeDateValue(raw.updateTime),
      userId: raw.userId as number | undefined,
      username: typeof raw.username === 'string' ? raw.username : '',
      userAvatar: typeof raw.userAvatar === 'string' ? raw.userAvatar : '',
      commentNum: Number(raw.commentNum || 0),
      likeNum: Number(raw.likeNum || 0),
      collectNum: Number(raw.collectNum || 0),
      isCollected: Boolean(raw.isCollected),
    }
  })
}

function normalizePreviewPage<T>(raw: unknown, normalizer: (list: unknown) => T[]) {
  const page = raw && typeof raw === 'object' ? (raw as BackendPage) : {}
  const rows = normalizer(page.rows)
  const total = Number(page.total ?? rows.length ?? 0)
  return { total: Number.isFinite(total) ? total : rows.length, rows }
}

function normalizeFollowPreviewPage(raw: unknown, relation: 'following' | 'follower') {
  const page = raw && typeof raw === 'object' ? (raw as BackendPage<BackendFollowItem>) : {}
  const rows = Array.isArray(page.rows) ? page.rows : []
  return {
    total: Number(page.total || rows.length || 0),
    rows: rows.map((item) => {
      const targetId = relation === 'following' ? item.followingId : item.followerId
      const nickname =
        relation === 'following'
          ? String(item.followingNickname || '').trim()
          : String(item.followerNickname || '').trim()
      const avatar =
        relation === 'following'
          ? String(item.followingAvatar || '').trim()
          : String(item.followerAvatar || '').trim()
      return {
        id: String(item.id || ''),
        userId: String(targetId || ''),
        nickname,
        avatar,
        followed: Boolean(item.isFollowed ?? relation === 'following'),
        relation,
        createTime: normalizeDateValue(item.createTime),
      }
    }),
  }
}

function isAuthError(error: unknown) {
  return error instanceof ApiError && (error.status === 401 || error.status === 403)
}

function unwrapSettled<T>(result: PromiseSettledResult<T>, fallback: T): T {
  if (result.status === 'fulfilled') return result.value
  if (isAuthError(result.reason)) throw result.reason
  return fallback
}

/** POST /forecast/list：分页走 query，bizUserId/lotteryCode 过滤走 body */
function fetchUserForecastPage(userId: number, pageSize: number, lotteryCode?: string) {
  const body: Record<string, any> = { bizUserId: userId }
  if (lotteryCode) body.lotteryCode = lotteryCode
  return post<BackendPage<ForecastPost>>(
    `/forecast/list?pageNum=1&pageSize=${pageSize}`,
    body,
    { paged: true },
  )
}

function fetchFollowPreview(path: string, previewLimit: number) {
  return get<BackendPage<BackendFollowItem>>(
    path,
    { pageNum: 1, pageSize: previewLimit },
    { paged: true },
  )
}

export async function fetchProfileDashboard(params: {
  userId: number | string
  rounds?: number
  recentLimit?: number
}): Promise<ProfileDashboardResponse> {
  const userId = Number(params.userId)
  if (!Number.isFinite(userId) || userId <= 0) {
    throw new ApiError('Valid userId is required', 400)
  }
  const recentLimit = Math.min(3, Math.max(1, Number(params.recentLimit || 3)))
  const performanceLimit = Math.min(10, Math.max(1, Number(params.rounds || 10)))
  // BFF 支持 previewLimit 查询参数（默认 3，上限 4）；App 端签名未暴露，沿用默认值
  const previewLimit = 3

  const tasks = await Promise.allSettled([
    fetchUserForecastPage(userId, recentLimit),
    fetchUserForecastPage(userId, performanceLimit),
    (async () => {
      const result = await get<any>(
        `/biz/userInfo/getUserHitStats/${userId}`,
        undefined,
      )
      const hitStats = unwrapAjaxData<any>(result)
      return Array.isArray(hitStats?.modeStats)
        ? hitStats.modeStats
            .map((item: any) => ({
              codeMode: String(item?.codeMode || '').trim(),
              description: String(item?.hitEffectDescription || '').trim(),
            }))
            .filter((item: { codeMode: string; description: string }) => item.codeMode && item.description)
            .slice(0, 4)
        : []
    })(),
    fetchFollowPreview('/biz/user/following', previewLimit),
    fetchFollowPreview('/biz/user/followers', previewLimit),
    get<BackendPage<ForumPost>>(`/forum/getUserForum/${userId}`, { pageNum: 1, pageSize: previewLimit }, { paged: true }),
    get<BackendPage<ForumPost>>('/forum/getUserCollectedForum', { pageNum: 1, pageSize: previewLimit }, { paged: true }),
    get<BackendPage<ForecastPost>>('/forecast/getUserCollectedForecast', { pageNum: 1, pageSize: previewLimit }, { paged: true }),
  ])

  const forecastPageData = unwrapSettled(tasks[0], { total: 0, rows: [] } as BackendPage<ForecastPost>)
  const performancePageData = unwrapSettled(tasks[1], { total: 0, rows: [] } as BackendPage<ForecastPost>)
  const modeSummaries = unwrapSettled(tasks[2], [] as { codeMode: string; description: string }[])
  const followingPageData = unwrapSettled(tasks[3], { total: 0, rows: [] } as BackendPage<BackendFollowItem>)
  const followersPageData = unwrapSettled(tasks[4], { total: 0, rows: [] } as BackendPage<BackendFollowItem>)
  const myForumsPageData = unwrapSettled(tasks[5], { total: 0, rows: [] } as BackendPage<ForumPost>)
  const collectedForumsPageData = unwrapSettled(tasks[6], { total: 0, rows: [] } as BackendPage<ForumPost>)
  const collectedForecastsPageData = unwrapSettled(tasks[7], { total: 0, rows: [] } as BackendPage<ForecastPost>)

  const recentForecasts = normalizeRecentForecasts(forecastPageData?.rows)
  const performanceForecasts = normalizeRecentForecasts(performancePageData?.rows)
  const points = performanceForecasts.map((forecast, index) => toForecastPoint(forecast, index))
  const totalHits = points.reduce((sum, item) => sum + item.hits, 0)
  const totalIssues = points.reduce((sum, item) => sum + item.total, 0)
  const hitRate = totalIssues > 0 ? Math.round((totalHits / totalIssues) * 100) : 0

  const forecastRates = points.reduce<Record<string, number>>((acc, point, index) => {
    const forecast = performanceForecasts[index]
    const key = String(forecast?.id || '').trim()
    if (!key || acc[key] !== undefined) return acc
    acc[key] = point.rate
    return acc
  }, {})

  return {
    hitRate,
    totalHits,
    totalIssues,
    cycleCount: performanceForecasts.length,
    forecastTotal: Number(performancePageData?.total || forecastPageData?.total || recentForecasts.length || 0),
    lastUpdatedAt: recentForecasts[0]?.createTime || performanceForecasts[0]?.createTime || '',
    trend: points.reverse(),
    recentForecasts,
    forecastRates,
    modeSummaries,
    following: normalizeFollowPreviewPage(followingPageData, 'following'),
    followers: normalizeFollowPreviewPage(followersPageData, 'follower'),
    myForums: normalizePreviewPage(myForumsPageData, normalizeForumPosts),
    collectedForums: normalizePreviewPage(collectedForumsPageData, normalizeForumPosts),
    collectedForecasts: normalizePreviewPage(collectedForecastsPageData, normalizeRecentForecasts),
  }
}
