import { PropsWithChildren } from 'react'
import { useLaunch } from '@tarojs/taro'
// RN 端 polyfill：补回 RN ≥0.71 移除的 DeviceEventEmitter.removeListener
// （@ant-design/react-native Portal.Host 卸载时仍调用它）；H5 解析到空实现
import '@/shims/deviceEventEmitter'
import { AuthProvider, useAuth } from '@/store/auth'

import './app.css'

function AuthBootstrap({ children }: PropsWithChildren<any>) {
  const { initAuth } = useAuth()

  // 冷启动恢复会话：读 storage → 拉 profile（产品方案 §5.1）
  useLaunch(() => {
    initAuth()
  })

  return children
}

function App({ children }: PropsWithChildren<any>) {
  return (
    <AuthProvider>
      <AuthBootstrap>{children}</AuthBootstrap>
    </AuthProvider>
  )
}

export default App
