/* 筛选工具（移植自 lottery_web FilterToolEntry.vue；token 见 src/app.css） */

.ft-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

.ft-card {
  margin: 16px;
  padding: 20px 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.ft-label {
  display: block;
  margin: 16px 0 8px;
  font-size: 15px;
  font-weight: 600;
  color: var(--color-text);
}

.ft-card .ft-label:first-child {
  margin-top: 0;
}

.ft-label-row {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  margin: 16px 0 8px;
}

.ft-label-row .ft-label {
  margin: 0;
  margin-right: 8px;
}

.ft-hint {
  display: block;
  margin: 8px 0;
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.5;
}

/* Chips 单选/多选（与历史回查页同风格） */
.chips {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 16px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.chip--small {
  padding: 0 12px;
}

.chip--active {
  background: var(--color-primary-light);
}

.chip--disabled {
  opacity: 0.45;
}

.chip__text {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.chip__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

.ft-toolbar {
  margin: 8px 0;
}

/* 大底 / 号码组输入 */
.ft-textarea {
  width: 100%;
  min-height: 96px;
  padding: 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
  font-size: 14px;
  box-sizing: border-box;
}

/* 逐位选号 / 定位弹层数字网格（5 个一行，触控 ≥44px） */
.ft-digit-grid {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: space-between;
  row-gap: 8px;
}

.ft-digit {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 19%;
  min-height: 44px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.ft-digit--active {
  background: var(--color-primary);
}

.ft-digit__text {
  font-size: 15px;
  color: var(--color-text);
}

.ft-digit__text--active {
  color: #fff;
  font-weight: 600;
}

.ft-position-block {
  margin-top: 12px;
}

.ft-position-block__head {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.ft-position-block__name {
  display: block;
  margin-bottom: 8px;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
}

.ft-position-block__head .ft-position-block__name {
  margin-bottom: 0;
}

.ft-position-block__ops {
  display: flex;
  flex-direction: row;
  gap: 16px;
}

.ft-link {
  padding: 8px 0;
  font-size: 13px;
  color: var(--color-primary);
}

.ft-link--danger {
  color: var(--color-danger);
}

/* 条件库 */
.ft-conditions {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: space-between;
  row-gap: 8px;
}

.ft-condition {
  width: 32%;
  padding: 10px 8px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
  box-sizing: border-box;
}

.ft-condition--active {
  background: var(--color-primary-light);
}

.ft-condition__label {
  display: block;
  font-size: 14px;
  text-align: center;
  color: var(--color-text);
}

.ft-condition__label--active {
  color: var(--color-primary);
  font-weight: 600;
}

.ft-condition__summary {
  display: block;
  margin-top: 4px;
  font-size: 11px;
  text-align: center;
  color: var(--color-text-secondary);
}

/* 过滤步骤 */
.ft-step {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 10px 8px;
  border-top: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
}

.ft-step--current {
  background: var(--color-primary-light);
}

.ft-step__main {
  flex: 1;
  min-width: 0;
}

.ft-step__label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
}

.ft-step__summary {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.ft-step__flow {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  color: var(--color-text-placeholder);
}

.ft-step__ops {
  display: flex;
  flex-direction: row;
  gap: 16px;
  margin-left: 12px;
}

/* 操作按钮 */
.ft-actions {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin-top: 24px;
}

.ft-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  border-radius: 999px;
  background: var(--color-primary);
}

.ft-btn--plain {
  background: var(--color-bg);
}

.ft-btn--danger {
  background: var(--color-danger);
}

.ft-btn--disabled {
  opacity: 0.6;
}

.ft-btn__text {
  font-size: 15px;
  font-weight: 600;
  color: #fff;
}

.ft-btn__text--plain {
  color: var(--color-text-secondary);
}

/* 方案 tabs（横向滚动） */
.ft-plans {
  margin-bottom: 8px;
  white-space: nowrap;
}

.ft-plans__inner {
  display: flex;
  flex-direction: row;
  gap: 8px;
}

.ft-plan {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 44px;
  padding: 0 6px 0 4px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
  border-width: 1px;
  border-color: transparent;
}

.ft-plan--active {
  background: var(--color-primary-light);
  border-color: var(--color-primary);
}

.ft-plan__check {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 44px;
}

.ft-plan__dot {
  width: 16px;
  height: 16px;
  border-radius: 8px;
  border-width: 1px;
  border-color: var(--color-text-placeholder);
  background: var(--color-bg-card);
}

.ft-plan__dot--on {
  border-color: var(--color-primary);
  background: var(--color-primary);
}

.ft-plan__name {
  padding: 8px 4px;
  font-size: 13px;
  color: var(--color-text);
}

.ft-plan__name--active {
  color: var(--color-primary);
  font-weight: 600;
}

.ft-plan__close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 44px;
}

.ft-plan__close-text {
  font-size: 16px;
  color: var(--color-text-placeholder);
}

/* 结果列表 */
.ft-result-head {
  margin-bottom: 4px;
}

.ft-result-head .ft-label {
  margin: 0;
}

.ft-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 44px;
  border-top: 1px solid var(--color-border);
}

.ft-row--head {
  border-top-width: 0; /* RN 端不支持 border-top: none */
}

.ft-row--deleted {
  background: #ffe4e6;
  opacity: 0.6;
}

.ft-row__index {
  width: 15%;
  font-size: 13px;
  color: var(--color-text-secondary);
}

.ft-row__code {
  flex: 1;
  font-size: 14px;
  color: var(--color-text);
  letter-spacing: 1px;
}

.ft-row__code--deleted {
  color: #991b1b;
  font-weight: 700;
  text-decoration: line-through;
}

.ft-row__action {
  width: 20%;
  display: flex;
  justify-content: flex-end;
}

.ft-row--head .ft-row__index,
.ft-row--head .ft-row__code,
.ft-row--head .ft-row__action {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.ft-result-actions {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}

.ft-result-actions .ft-btn {
  min-width: 45%;
  min-height: 44px;
}

.ft-load-more {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
}

.ft-load-more__text {
  font-size: 13px;
  color: var(--color-primary);
}

/* 底部弹层（条件配置 / 复制） */
.ft-sheet {
  padding: 16px 16px var(--sa-16, calc(16px + env(safe-area-inset-bottom)));
}

.ft-sheet__title {
  display: block;
  text-align: center;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 8px;
}

.ft-sheet__body {
  max-height: 60vh;
}

.ft-sheet__footer {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin-top: 16px;
}

.ft-sumpos {
  margin: 12px 0;
}

.ft-history-modes {
  margin: 12px 0;
}

/* 和值 / 合值 / 两码差值域网格（6 个一行） */
.ft-value-grid {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: space-between;
  row-gap: 8px;
  margin-top: 8px;
}

.ft-value {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 15%;
  min-height: 44px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.ft-value--active {
  background: var(--color-primary);
}

.ft-value__text {
  font-size: 14px;
  color: var(--color-text);
}

.ft-value__text--active {
  color: #fff;
  font-weight: 600;
}

/* 复制预览 */
.ft-copy-preview {
  max-height: 30vh;
  margin-top: 8px;
  padding: 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
}

.ft-copy-preview__text {
  font-size: 13px;
  color: var(--color-text);
  line-height: 1.6;
}
