import { useCallback, useEffect, useState } from 'react'
import { View, Text } from '@tarojs/components'
import Taro, { usePullDownRefresh, useReachBottom } from '@tarojs/taro'
import Popup from '@/components/SheetPopup'
import { FORUM_PARTITIONS, getSlugByLotteryCode } from '@/constants/lottery'
import type { FeedItem } from '@/types'
import { fetchFeedList } from '@/services/api'
import { usePagedList } from '@/hooks/usePagedList'
import { useAuth, redirectToLogin } from '@/store/auth'
import { currentRoute, goPostDetail, goPublish } from '@/utils/nav'
import { commonLabels, forumLabels } from '@/labels'
import { forumDetailLabels } from '@/labels/forumDetail'
import Skeleton from '@/components/Skeleton'
import Empty from '@/components/Empty'
import FeedPredictionCard from '@/components/forum/FeedPredictionCard'
import FeedExchangeRow from '@/components/forum/FeedExchangeRow'
import NavBar from '@/components/NavBar'
import iconForum from '@/assets/tabbar/forum_active.png'
import './index.css'

const ALL_PARTITION = 'all'

/** 交流帖标题回退：正文去标签截 50 字 */
function exchangeTitle(item: FeedItem): string {
  return (
    item.title?.trim() ||
    (item.content || '').replace(/<[^>]+>/g, '').trim().slice(0, 50) ||
    forumDetailLabels.noTitle
  )
}

function detailTarget(item: FeedItem) {
  return {
    partition: item.lotteryCode ? getSlugByLotteryCode(item.lotteryCode) : ALL_PARTITION,
    type: (item.feedType === 'forecast' ? 'prediction' : 'exchange') as 'prediction' | 'exchange',
    id: item.id,
  }
}

/** 社区信息流（Tab2，产品方案 §6.5）：自定义导航栏（含「我的」入口）+ 分区 Segment + 论坛规则/发帖入口 + 混合信息流上拉加载 */
export default function ForumPage() {
  const { isLoggedIn } = useAuth()
  const [partition, setPartition] = useState<string>(ALL_PARTITION)
  const [rulesVisible, setRulesVisible] = useState(false)
  const [publishVisible, setPublishVisible] = useState(false)

  const lotteryCode =
    partition === ALL_PARTITION ? undefined : FORUM_PARTITIONS.find((p) => p.slug === partition)?.lotteryCode

  const { list, loading, refreshing, error, hasMore, refresh, loadMore } = usePagedList({
    fetchPage: useCallback((pageNum: number) => fetchFeedList(lotteryCode, pageNum, 10), [lotteryCode]),
    pageSize: 10,
  })

  // 切分区重置列表（fetchPage 变化 → refresh 引用变化 → 重新拉第 1 页）
  useEffect(() => {
    refresh()
  }, [refresh])

  usePullDownRefresh(async () => {
    await refresh()
    Taro.stopPullDownRefresh()
  })

  useReachBottom(() => {
    if (hasMore && !loading) loadMore()
  })

  const openDetail = (item: FeedItem) => {
    goPostDetail(detailTarget(item))
  }

  // 长按卡片：复制「标题 + 链接」并 Toast（产品方案 §3.4）
  const copyItem = (item: FeedItem) => {
    const { partition: slug, type, id } = detailTarget(item)
    const title = item.feedType === 'forecast' ? item.title?.trim() || forumDetailLabels.noTitle : exchangeTitle(item)
    Taro.setClipboardData({
      data: `${title}\n/pages/forum-detail/index?partition=${slug}&type=${type}&id=${id}`,
      success: () => Taro.showToast({ title: commonLabels.copySuccess, icon: 'none' }),
    })
  }

  const onPublish = () => {
    if (!isLoggedIn) {
      redirectToLogin(currentRoute())
      return
    }
    setPublishVisible(true)
  }

  const pickPublishType = (type: 'exchange' | 'prediction') => {
    setPublishVisible(false)
    goPublish({ type, partition })
  }

  return (
    <View className='forum-page'>
      {/* 自定义顶部导航栏（navigationStyle: 'custom'）：居中标题 + 右侧「我的」入口 */}
      <NavBar title={forumLabels.title} icon={iconForum} />
      {/* 顶部：分区 Segment + 论坛规则 + 发帖 */}
      <View className='forum-header'>
        <View className='forum-segment'>
          <View
            className={`forum-segment__item${partition === ALL_PARTITION ? ' forum-segment__item--active' : ''}`}
            onClick={() => setPartition(ALL_PARTITION)}
          >
            <Text
              className={`forum-segment__text${partition === ALL_PARTITION ? ' forum-segment__text--active' : ''}`}
            >
              全部
            </Text>
          </View>
          {FORUM_PARTITIONS.map((p) => (
            <View
              key={p.slug}
              className={`forum-segment__item${partition === p.slug ? ' forum-segment__item--active' : ''}`}
              onClick={() => setPartition(p.slug)}
            >
              <Text className={`forum-segment__text${partition === p.slug ? ' forum-segment__text--active' : ''}`}>
                {p.label}
              </Text>
            </View>
          ))}
        </View>
        <View className='forum-header__icon' onClick={() => setRulesVisible(true)}>
          <Text className='forum-header__icon-text'>!</Text>
        </View>
        <View className='forum-header__publish' onClick={onPublish}>
          <Text className='forum-header__publish-text'>{forumLabels.publish}</Text>
        </View>
      </View>

      {/* 混合信息流：交流帖 + 预测帖按时间倒序 */}
      {refreshing && list.length === 0 ? (
        <Skeleton rows={5} />
      ) : error && list.length === 0 ? (
        <Empty text={error} actionText={commonLabels.networkError} onAction={refresh} />
      ) : list.length === 0 ? (
        <Empty />
      ) : (
        <>
          {list.map((item) => (
            <View
              key={`${item.feedType}-${item.id}`}
              onClick={() => openDetail(item)}
              onLongPress={() => copyItem(item)}
            >
              {item.feedType === 'forecast' ? <FeedPredictionCard item={item} /> : <FeedExchangeRow item={item} />}
            </View>
          ))}
          <View className='list-footer' onClick={() => hasMore && !loading && loadMore()}>
            <Text className='list-footer__text'>
              {loading ? commonLabels.loading : hasMore ? commonLabels.loadMore : commonLabels.noMore}
            </Text>
          </View>
        </>
      )}

      {/* 论坛规则弹层 */}
      <Popup visible={rulesVisible} onClose={() => setRulesVisible(false)}>
        <View className='sheet'>
          <Text className='sheet__title'>{forumLabels.rulesTitle}</Text>
          {forumLabels.rules.map((rule, idx) => (
            <View key={idx} className='sheet__rule'>
              <Text className='sheet__rule-text'>{`${idx + 1}. ${rule}`}</Text>
            </View>
          ))}
          <View className='sheet__cancel' onClick={() => setRulesVisible(false)}>
            <Text className='sheet__cancel-text'>{commonLabels.cancel}</Text>
          </View>
        </View>
      </Popup>

      {/* 发帖类型选择弹层 */}
      <Popup visible={publishVisible} onClose={() => setPublishVisible(false)}>
        <View className='sheet'>
          <Text className='sheet__title'>{forumLabels.publish}</Text>
          <View className='sheet__action' onClick={() => pickPublishType('exchange')}>
            <Text className='sheet__action-text'>{forumLabels.publishExchange}</Text>
          </View>
          <View className='sheet__action' onClick={() => pickPublishType('prediction')}>
            <Text className='sheet__action-text'>{forumLabels.publishPrediction}</Text>
          </View>
          <View className='sheet__cancel' onClick={() => setPublishVisible(false)}>
            <Text className='sheet__cancel-text'>{commonLabels.cancel}</Text>
          </View>
        </View>
      </Popup>
    </View>
  )
}
