.feed-exchange {
  margin: 0 16px 12px;
  padding: 14px 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.feed-exchange__main {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.feed-exchange__title {
  flex: 1;
  margin-left: 8px;
  font-size: 15px;
  color: var(--color-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.feed-exchange__meta {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin-top: 10px;
}

.feed-exchange__author {
  margin-left: 6px;
  font-size: 12px;
  color: var(--color-text-secondary);
  max-width: 80px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.feed-exchange__time {
  margin-left: 12px;
  font-size: 12px;
  color: var(--color-text-placeholder);
}

.feed-exchange__stat {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-left: 12px;
}
