import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Image, ScrollView, Text, View } from '@tarojs/components'
import Taro, { useDidHide, useDidShow, usePageScroll, usePullDownRefresh } from '@tarojs/taro'
import Swiper from '@nutui/nutui-react-taro/dist/es/packages/swiper'
import '@nutui/nutui-react-taro/dist/es/packages/swiper/style/css.js'
import iconFilter from '@/assets/tools/filter.png'
import iconCodeGroupExtension from '@/assets/tools/code-group-extension.png'
import iconHistoryReview from '@/assets/tools/history-review.png'
import iconSetProcessing from '@/assets/tools/set-processing.png'
import iconDrawRule from '@/assets/tools/draw-rule.png'
import iconPlay from '@/assets/common/play.png'
import iconDataFactory from '@/assets/tools/data-factory.png'
import iconTrend from '@/assets/tools/trend.png'
import {
  DEFAULT_LOTTERY_CODE,
  LOTTERY_LIST,
  getLotteryLabel,
  getSlugByLotteryCode,
  type LotteryCode,
} from '@/constants/lottery'
import { fetchBannerList, fetchExpertRank, fetchIsFollowing, fetchLatestDraw, fetchPredictionList } from '@/services/api'
import { goCodeGroupExtension, goDraw, goDrawRule, goFilterTool, goHistoryReview, goLive, goPageLink, goPostDetail, goSetProcessing, switchTab } from '@/utils/nav'
import { formatTime } from '@/utils/formatTime'
import { getLiveWindowState } from '@/utils/live'
import { useAuth } from '@/store/auth'
import { commonLabels, lotteryLabels } from '@/labels'
import { homeLabels } from '@/labels/home'
import type { BannerItem, Expert, ForecastPost, LotteryDraw } from '@/types'
import NumberBalls from '@/components/NumberBalls'
import Avatar from '@/components/Avatar'
import Skeleton from '@/components/Skeleton'
import Empty from '@/components/Empty'
import FollowButton from '@/components/FollowButton'
import HitBadge from '@/components/HitBadge'
import LotteryTag from '@/components/LotteryTag'
import NavBar, { STATUS_BAR_HEIGHT } from '@/components/NavBar'
import RefreshControl from '@/components/RefreshControl'
import './index.css'

/** NavBar 渐变距离（px）：上滑该距离内从透明渐变到不透明 */
const NAV_FADE_DISTANCE = 120

/** RN 端 NavBar 总高度：状态栏 + 44px 导航内容 + 1px 底部分隔线（border-bottom 实占布局，
 *  对齐 NavBar 组件 nav-bar__inner 的 height: 44px + .nav-bar 的 border-bottom） */
const RN_NAV_BAR_HEIGHT = STATUS_BAR_HEIGHT + 45

/** RN 端结构分端：RN 不支持 sticky/fixed，页面内滚动 + NavBar 覆盖吸顶；H5 保持页面级滚动 + sticky */
const IS_RN = process.env.TARO_ENV === 'rn'

/** 工具图标（scripts/gen_tool_icons.mjs 生成：FontAwesome 图标，统一品牌红 + 浅红圆角底） */
const TOOL_ICONS: Record<string, string> = {
  filter: iconFilter,
  'code-group-extension': iconCodeGroupExtension,
  'history-review': iconHistoryReview,
  'set-processing': iconSetProcessing,
  'draw-rule': iconDrawRule,
}

/** 推荐功能图标：数据工厂为 gen_tool_icons.py 生成；走势趋势为 gen_tool_icons.mjs 生成（FontAwesome chart-line），均统一品牌红 */
const RECOMMEND_ICONS: Record<string, string> = {
  'data-factory': iconDataFactory,
  trend: iconTrend,
}

interface DrawEntry {
  code: LotteryCode
  draw: LotteryDraw
}

interface AnalystRow extends Expert {
  posts: ForecastPost[]
}

/** 预测帖命中标记：优先帖子级 hitFlag，否则取方案级（对齐 Web PlatformAnalystForecast.getHitBadge） */
function resolvePostHitFlag(post: ForecastPost): string | null {
  if (post.hitFlag) return post.hitFlag
  const plans = post.planVOList || []
  for (const plan of plans) {
    const hf = String(plan.hitFlag || '').toLowerCase()
    if (hf === 'hit' || hf === 'success') return 'hit'
    if (hf === 'fail' || hf === 'miss') return 'miss'
  }
  return null
}

/** 首页（Tab1）：最新开奖（卡片头部为该彩种直播入口）+ 工具入口 + 专业数据榜（产品方案 §6.1） */
export default function HomePage() {
  const { isLoggedIn } = useAuth()
  const [draws, setDraws] = useState<DrawEntry[]>([])
  const [analysts, setAnalysts] = useState<AnalystRow[]>([])
  const [firstLoading, setFirstLoading] = useState(true)
  /** 登录后逐行补的关注态（key: userId 字符串），静默失败忽略 */
  const [followMap, setFollowMap] = useState<Record<string, boolean>>({})
  const [banners, setBanners] = useState<BannerItem[]>([])
  /** 轮播图接口是否已返回（区分"加载中"与"确认无 banner"，避免返回后 NavBar/布局跳变） */
  const [bannerLoaded, setBannerLoaded] = useState(false)
  /** NavBar 滚动渐变不透明度：0 全透明 → 1 不透明 */
  const [navOpacity, setNavOpacity] = useState(0)
  /** 轮播图高度 = 屏宽（1:1 正方形撑满） */
  const [bannerSize] = useState(() => Taro.getSystemInfoSync().windowWidth || 375)
  /** 轮播当前页（底部浮层标题/指示点跟随） */
  const [bannerIndex, setBannerIndex] = useState(0)
  /** 直播窗口状态（北京时间 21:00-22:00），驱动开奖卡片直播入口的可用配色 */
  const [isLiveWindow, setIsLiveWindow] = useState(() => getLiveWindowState().isLive)
  /** RN 端下拉刷新进行中（驱动 ScrollView refreshControl prop 的 RefreshControl 转圈） */
  const [refreshing, setRefreshing] = useState(false)
  /** 直播窗口轮询定时器（didShow 启动 / didHide 停止，Tab 页常驻不卸载） */
  const liveTimerRef = useRef<ReturnType<typeof setInterval> | null>(null)

  // 低频轮询刷新直播窗口状态（页面长驻跨过 21:00/22:00 边界时入口配色自动切换）。
  // Tab 页常驻不卸载，改用 didShow/didHide 启停：切走 Tab / 应用后台时不再空转
  useDidShow(() => {
    setIsLiveWindow(getLiveWindowState().isLive)
    liveTimerRef.current = setInterval(() => {
      setIsLiveWindow(getLiveWindowState().isLive)
    }, 30000)
  })
  useDidHide(() => {
    if (liveTimerRef.current) {
      clearInterval(liveTimerRef.current)
      liveTimerRef.current = null
    }
  })
  // 卸载兜底（Tab 页常驻一般不触发，防御性清理）
  useEffect(
    () => () => {
      if (liveTimerRef.current) clearInterval(liveTimerRef.current)
    },
    [],
  )

  const loadBanners = useCallback(async () => {
    try {
      const list = await fetchBannerList()
      setBanners(list)
    } catch {
      setBanners([]) // 轮播失败静默降级，不阻塞首页其它区块
    } finally {
      setBannerLoaded(true)
    }
  }, [])

  const loadDraws = useCallback(async () => {
    const results = await Promise.all(
      LOTTERY_LIST.map(async (item) => {
        try {
          const draw = await fetchLatestDraw(item.code)
          // 过滤掉无期号/无号码的无效数据（Web PRD §6.1）
          if (!draw?.drawNum || !draw.numbers?.length) return null
          return { code: item.code, draw }
        } catch {
          return null // 单彩种失败不影响其他卡片
        }
      }),
    )
    setDraws(results.filter((item): item is DrawEntry => !!item))
  }, [])

  const loadAnalysts = useCallback(async () => {
    try {
      const rows = await fetchExpertRank({ identity: 'M', rankType: '10', lotteryCode: DEFAULT_LOTTERY_CODE })
      const withPosts = await Promise.all(
        (rows || []).map(async (expert) => {
          try {
            const res = await fetchPredictionList({ userId: Number(expert.id), pageNum: 1, pageSize: 5 })
            return { ...expert, posts: res?.rows || [] }
          } catch {
            return { ...expert, posts: [] } // 预测帖加载失败不阻塞分析师行展示
          }
        }),
      )
      setAnalysts(withPosts)
    } catch {
      setAnalysts([])
    }
  }, [])

  const loadAll = useCallback(async () => {
    await Promise.all([loadDraws(), loadAnalysts(), loadBanners()])
    setFirstLoading(false)
  }, [loadDraws, loadAnalysts, loadBanners])

  useEffect(() => {
    loadAll()
  }, [loadAll])

  usePullDownRefresh(async () => {
    await loadAll()
    Taro.stopPullDownRefresh()
  })

  /** RN 端下拉刷新：首页 disableScroll 后 runtime-rn 不再注入页面级免 RefreshControl，
   *  改由页面内 ScrollView 透传 refreshControl（components-rn 会透传未声明的 props 到 RN ScrollView）；
   *  H5 端不走这里，仍由上面的 usePullDownRefresh 承接（refreshControl prop 走类型增强，无 as any） */
  const onRnRefresh = useCallback(async () => {
    setRefreshing(true)
    try {
      await loadAll()
    } finally {
      setRefreshing(false)
    }
  }, [loadAll])

  /** 元素引用稳定化：首页因 navOpacity 每几像素滚动就重渲染一次，
   *  内联重建会让 RN 原生 RefreshControl 每帧收到新 props；memo 后滚动期间 diff 直接跳过该子树 */
  const refreshControlEl = useMemo(
    () => <RefreshControl refreshing={refreshing} onRefresh={onRnRefresh} progressViewOffset={RN_NAV_BAR_HEIGHT} />,
    [refreshing, onRnRefresh],
  )

  /** scrollTop → NavBar 不透明度（NAV_FADE_DISTANCE px 内线性渐变；小变化跳过减少重渲染） */
  const updateNavOpacity = useCallback((scrollTop: number) => {
    const next = Math.min(1, Math.max(0, scrollTop / NAV_FADE_DISTANCE))
    setNavOpacity((prev) => (Math.abs(prev - next) < 0.02 ? prev : next))
  }, [])

  // H5：页面级滚动驱动渐变（RN 端页面已 disableScroll，由页面内 ScrollView 的 onScroll 驱动）
  usePageScroll((e) => updateNavOpacity(e?.scrollTop ?? 0))

  const onScroll = useCallback(
    (e: any) => updateNavOpacity(e?.detail?.scrollTop ?? 0),
    [updateNavOpacity],
  )

  /** 轮播点击：page 站内跳转；url 外链 H5 新标签打开，RN 走 Taro.openUrl（taro-rn 封装的 Linking，调起系统浏览器） */
  const onBannerClick = useCallback((item: BannerItem) => {
    if (item.linkType === 'page' && item.linkUrl) {
      goPageLink(item.linkUrl)
    } else if (item.linkType === 'url' && item.linkUrl) {
      if (process.env.TARO_ENV === 'h5') {
        window.open(item.linkUrl, '_blank', 'noopener,noreferrer')
      } else if (process.env.TARO_ENV === 'rn') {
        // openUrl 为 taro-rn 专有 API（@tarojs/taro 公共类型未声明，故 as any）
        ; (Taro as any).openUrl?.({ url: item.linkUrl })
      }
    }
  }, [])

  // 登录后逐行补关注态（SSR 等价物不存在，App 端首屏数据不含用户维度状态）
  useEffect(() => {
    if (!isLoggedIn) return
      ; analysts.forEach((expert) => {
        const key = String(expert.id)
        fetchIsFollowing(expert.id)
          .then((res) => {
            if (typeof res?.followed === 'boolean') {
              setFollowMap((prev) => (key in prev ? prev : { ...prev, [key]: res.followed }))
            }
          })
          .catch(() => { })
      })
  }, [isLoggedIn, analysts])

  const followedOf = useCallback(
    (expert: Expert) => followMap[String(expert.id)] ?? !!expert.isFollowed,
    [followMap],
  )

  const onFollowChange = useCallback((id: number | string, followed: boolean) => {
    setFollowMap((prev) => ({ ...prev, [String(id)]: followed }))
  }, [])

  const onToolClick = useCallback((key: string) => {
    if (key === 'history-review') {
      goHistoryReview()
      return
    }
    if (key === 'filter') {
      goFilterTool()
      return
    }
    if (key === 'code-group-extension') {
      goCodeGroupExtension()
      return
    }
    if (key === 'set-processing') {
      goSetProcessing()
      return
    }
    if (key === 'draw-rule') {
      goDrawRule('04')
      return
    }
    Taro.showToast({ title: homeLabels.tools.comingSoon, icon: 'none' })
  }, [])

  /** 推荐功能：走势趋势 → 走势 Tab；数据工厂暂为占位 */
  const onRecommendClick = useCallback((key: string) => {
    if (key === 'trend') {
      switchTab({ url: '/pages/trend/index' })
      return
    }
    Taro.showToast({ title: homeLabels.recommend.comingSoon, icon: 'none' })
  }, [])

  /** 轮播当前页（列表刷新后张数可能变少，钳位防越界） */
  const bannerActive = Math.min(bannerIndex, Math.max(0, banners.length - 1))

  /** 确认无轮播图（接口已返回且无数据）：NavBar 恒不透明 + 内容预留占位；加载中按有 banner 处理，避免返回后跳变 */
  const noBanner = bannerLoaded && banners.length === 0

  const renderFollow = (expert: Expert) => {
    const followed = followedOf(expert)
    return (
      <FollowButton
        key={`${expert.id}-${followed}`}
        userId={expert.id}
        isFollowed={followed}
        onChange={(next) => onFollowChange(expert.id, next)}
      />
    )
  }

  /** 首屏内容：H5 走页面级滚动（NavBar sticky 吸顶）；RN 由页面内 ScrollView 承载 */
  const content = firstLoading ? (
    <Skeleton rows={5} />
  ) : (
    <>
      {/* 顶部轮播图（/banner/list，1:1 正方形撑满屏宽；无数据或加载失败不渲染） */}
      {banners.length > 0 ? (
        <View className='banner-swiper-wrap'>
          <Swiper
            className='banner-swiper'
            height={bannerSize}
            autoPlay={banners.length > 1}
            interval={3500}
            loop={banners.length > 1}
            onChange={(e: any) => setBannerIndex(e?.detail?.current ?? 0)}
          >
            {banners.map((item) => (
              <Image
                key={item.id}
                className='banner-swiper__img'
                src={item.imageUrl}
                mode='aspectFill'
                onClick={() => onBannerClick(item)}
              />
            ))}
          </Swiper>
          {/* 底部浮层：当前页标题 + 播放进度指示点（pointer-events: none 透出，不拦截滑动手势） */}
          {banners[bannerActive]?.title || banners.length > 1 ? (
            <View className='banner-swiper__overlay'>
              {/* RN 端 Text 不支持 text-overflow/white-space 样式，省略号靠 numberOfLines 实现 */}
              <Text className='banner-swiper__title' numberOfLines={1}>
                {banners[bannerActive]?.title || ''}
              </Text>
              {banners.length > 1 ? (
                <View className='banner-swiper__dots'>
                  {banners.map((item, i) => (
                    <View
                      key={item.id}
                      className={`banner-swiper__dot${i === bannerActive ? ' banner-swiper__dot--active' : ''}`}
                    />
                  ))}
                </View>
              ) : null}
            </View>
          ) : null}
        </View>
      ) : null}

      {/* 推荐功能：数据工厂（占位）、走势趋势（走势 Tab） */}
      <Text className='section-title'>{homeLabels.recommend.title}</Text>
      <View className='recommend-card'>
        {homeLabels.recommend.entries.map((item) => (
          <View key={item.key} className='recommend-card__item' onClick={() => onRecommendClick(item.key)}>
            <Image className='recommend-card__icon' src={RECOMMEND_ICONS[item.key]} mode='aspectFit' />
            <View className='recommend-card__texts'>
              <Text className='recommend-card__label'>{item.label}</Text>
              <Text className='recommend-card__desc'>{item.desc}</Text>
            </View>
          </View>
        ))}
      </View>

      {/* 实用工具：每个工具独立卡片，3 列网格平铺（类似推荐功能，无描述文案） */}
      <Text className='section-title'>{homeLabels.tools.title}</Text>
      <View className='tools-grid'>
        {homeLabels.tools.entries.map((tool) => (
          <View key={tool.key} className='tools-grid__item' onClick={() => onToolClick(tool.key)}>
            <Image className='tools-grid__icon' src={TOOL_ICONS[tool.key]} mode='aspectFit' />
            <Text className='tools-grid__label'>{tool.label}</Text>
          </View>
        ))}
      </View>

      {/* 三彩种最新开奖 */}
      <Text className='section-title'>{lotteryLabels.latestDraw}</Text>
      {draws.length === 0 ? (
        <Empty text={lotteryLabels.latestDraw} />
      ) : (
        draws.map(({ code, draw }) => (
          <View key={code} className='draw-card'>
            <View className='draw-card__head'>
              <View className='draw-card__info'>
                <Text className='draw-card__name'>{draw.lotteryType || getLotteryLabel(code)}</Text>
                <Text className='draw-card__issue'>{lotteryLabels.issuePrefix(draw.drawNum)}</Text>
              </View>

              {/* 该彩种开奖直播直达入口（携带 code）：播放按钮元素 + 文案；
                  直播窗口内 primary 配色表示可用，非直播时段灰色（仍可点击进入直播页看倒计时） */}
              <View className='draw-card__live-entry' onClick={() => goLive(code)}>
                <View className={`draw-card__live-icon${isLiveWindow ? ' draw-card__live-icon--live' : ''}`}>
                  <Image className='draw-card__live-icon-img' src={iconPlay} mode='aspectFit' />
                </View>
                <Text className={`draw-card__live-text${isLiveWindow ? ' draw-card__live-text--live' : ''}`}>
                  {lotteryLabels.liveEntry}
                </Text>
              </View>
            </View>

            <NumberBalls numbers={draw.numbers} />

            {/* 开奖卡片 footer：历史开奖（该彩种开奖页）+ 画规 + 筛选/回查工具入口。
                按钮用 View 容器 + 内部 Text（RN 端 Text 的 border-radius 不裁剪背景、也不支持 flex 居中） */}
            <View className='draw-card__footer'>
              <View className='draw-card__footer-btn' onClick={() => goDraw(code)}>
                <Text className='draw-card__footer-btn-text'>{lotteryLabels.historyDraw}</Text>
              </View>
              <View className='draw-card__footer-btn' onClick={() => goDrawRule(code)}>
                <Text className='draw-card__footer-btn-text'>{lotteryLabels.drawRule}</Text>
              </View>
              <View className='draw-card__footer-btn' onClick={() => goFilterTool(code)}>
                <Text className='draw-card__footer-btn-text'>{lotteryLabels.filterTool}</Text>
              </View>
              <View className='draw-card__footer-btn' onClick={() => goHistoryReview(code)}>
                <Text className='draw-card__footer-btn-text'>{lotteryLabels.historyReview}</Text>
              </View>
            </View>
          </View>
        ))
      )}

      {/* 专业数据榜（identity=M，有数据才渲染） */}
      {analysts.length > 0 ? (
        <>
          <Text className='section-title'>{homeLabels.analyst.title}</Text>
          {analysts.map((analyst) => (
            <View key={analyst.id} className='analyst-card'>
              <View className='analyst-card__head'>
                <Avatar src={analyst.avatar} name={analyst.nickName} size={44} />
                <View className='analyst-card__info'>
                  <Text className='analyst-card__name'>{analyst.nickName}</Text>
                  <View className='analyst-card__stats'>
                    <Text className='analyst-card__stat'>{homeLabels.analyst.winRate}</Text>
                    <Text className='analyst-card__stat analyst-card__stat--rate'>{analyst.winRate}%</Text>
                    <Text className='analyst-card__stat'>
                      {homeLabels.analyst.lastDraw} {analyst.lastDrawNum}
                      {homeLabels.analyst.issueSuffix}
                    </Text>
                    <Text className='analyst-card__stat'>
                      {homeLabels.analyst.record} {analyst.record}
                    </Text>
                  </View>
                </View>
                {renderFollow(analyst)}
              </View>
              <View className='analyst-card__posts'>
                <Text className='analyst-card__posts-title'>{homeLabels.analyst.recentPosts}</Text>
                {analyst.posts.length === 0 ? (
                  <Text className='analyst-card__posts-empty'>{homeLabels.analyst.emptyPosts}</Text>
                ) : (
                  analyst.posts.map((post) => (
                    <View
                      key={post.id}
                      className='analyst-post'
                      onClick={() =>
                        goPostDetail({
                          partition: getSlugByLotteryCode(post.lotteryCode),
                          type: 'prediction',
                          id: post.id,
                        })
                      }
                    >
                      <View className='analyst-post__tags'>
                        <LotteryTag code={post.lotteryCode} />
                        <HitBadge hitFlag={resolvePostHitFlag(post)} hitDetail={post.hitDetail} />
                      </View>
                      <Text className='analyst-post__title'>
                        {post.title?.trim() || homeLabels.analyst.noTitle}
                      </Text>
                      <Text className='analyst-post__time'>{formatTime(post.createTime)}</Text>
                    </View>
                  ))
                )}
              </View>
            </View>
          ))}
        </>
      ) : null}
    </>
  )

  return (
    <View className={IS_RN ? 'home-page' : 'home-page home-page--h5'}>
      {/* 自定义顶部导航栏（navigationStyle: 'custom'）：居中标题；有轮播图时初始透明、上滑渐显，无轮播图时恒不透明 */}
      {IS_RN ? (
        <>
          {/* RN 不支持 sticky/fixed：页面 config 已 disableScroll，改页面内 ScrollView + NavBar 覆盖吸顶。
              NavBar overlay 悬浮不占布局：有轮播图时内容沉浸式顶到屏幕顶端（从透明 NavBar 下透出）；
              无轮播图时内容需预留 NavBar 占位，否则顶部内容被不透明 NavBar 遮住 */}
          <ScrollView
            scrollY
            className='home-scroll'
            onScroll={onScroll}
            refreshControl={refreshControlEl}
          >
            <View style={{ paddingTop: noBanner ? RN_NAV_BAR_HEIGHT : 0, paddingBottom: 24 }}>{content}</View>
          </ScrollView>
          <NavBar title={commonLabels.appName} fadeOpacity={noBanner ? 1 : navOpacity} overlay />
        </>
      ) : (
        <>
          <NavBar title={commonLabels.appName} fadeOpacity={noBanner ? 1 : navOpacity} />
          {content}
        </>
      )}
    </View>
  )
}
