.position-selector {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.position-row {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 12px;
}

.position-row__head {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.position-row__badge {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-primary);
  background: var(--color-primary-light);
  border-radius: 4px;
  padding: 2px 8px;
}

.position-row__count {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.position-row__balls {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
}

/* 两行五行；视觉球 32px，外层热区 ≥44px（产品方案 §3.2） */
.position-ball-wrap {
  width: 20%;
  min-height: 56px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.position-ball {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
}

.position-ball--active {
  background: var(--color-primary);
  border-color: var(--color-primary);
}

.position-ball__text {
  font-size: 15px;
  color: var(--color-text);
}

.position-ball__text--active {
  color: #fff;
  font-weight: 600;
}

.position-ball__marks {
  font-size: 10px;
  color: var(--color-warning);
  line-height: 1.2;
  min-height: 12px;
  margin-top: 2px;
}

.position-row__annot-hint {
  display: block;
  margin-top: 8px;
  font-size: 12px;
  color: var(--color-text-placeholder);
}

/* 标记菜单 */
.mark-menu {
  padding: 16px 16px var(--sa-16, calc(16px + env(safe-area-inset-bottom)));
}

.mark-menu__title {
  display: block;
  text-align: center;
  font-size: 15px;
  font-weight: 600;
  padding-bottom: 12px;
}

.mark-menu__option {
  min-height: 48px;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--color-border);
}

.mark-menu__option--disabled {
  opacity: 0.5;
}

.mark-menu__option-text {
  font-size: 15px;
  color: var(--color-text);
}

.mark-menu__option-text--disabled {
  color: var(--color-text-placeholder);
}

.mark-menu__option-hint {
  font-size: 12px;
  color: var(--color-text-placeholder);
}

.mark-menu__cancel {
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-top: 1px solid var(--color-border);
  margin-top: 8px;
}

.mark-menu__cancel-text {
  font-size: 15px;
  color: var(--color-text-secondary);
}
