.detail-page {
  min-height: 100vh;
  padding: 12px 0 var(--sa-96, calc(96px + env(safe-area-inset-bottom)));
}

/* 正文卡 */
.post-card {
  margin: 0 16px;
  padding: 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

/* 作者卡（吸顶于正文卡顶部，单列布局） */
.author-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--color-border);
}

.author-row__info {
  flex: 1;
  min-width: 0;
  margin-left: 10px;
}

.author-row__name {
  display: block;
  font-size: 15px;
  font-weight: 600;
  color: var(--color-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.author-row__role {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.post-card__more {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
}

.post-card__more-text {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-text-secondary);
  letter-spacing: 2px;
}

/* meta 行 */
.post-meta {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  margin-top: 14px;
}

.post-tag {
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  margin-right: 6px;
}

.post-tag--exchange {
  background: rgba(16, 185, 129, 0.1);
  color: var(--color-success);
}

.post-tag--prediction {
  background: rgba(184, 50, 55, 0.1);
  color: var(--color-primary);
}

.post-tag--dim {
  background: rgba(52, 152, 219, 0.1);
  color: var(--color-info);
}

.post-meta__issue {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-right: 8px;
}

.post-meta__time {
  font-size: 12px;
  color: var(--color-text-placeholder);
}

.post-title {
  display: block;
  margin-top: 10px;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.5;
  color: var(--color-text);
}

/* 「本期开奖」区 */
.draw-section {
  margin-top: 14px;
  padding: 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
}

.draw-section__label {
  display: block;
  margin-bottom: 8px;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-secondary);
}

.draw-section__hit {
  display: inline-block;
  margin-top: 8px;
  padding: 2px 10px;
  border-radius: 4px;
  background: rgba(16, 185, 129, 0.12);
  color: var(--color-success);
  font-size: 12px;
  font-weight: 600;
}

/* 预测方案卡 */
.plans-section {
  margin-top: 16px;
}

.section-title {
  display: block;
  margin-bottom: 10px;
  font-size: 16px;
  font-weight: 600;
  color: var(--color-text);
}

.plan-card {
  margin-bottom: 12px;
  padding: 12px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
}

.plan-card--hit {
  border-color: rgba(16, 185, 129, 0.4);
}

.plan-card--miss {
  border-color: rgba(239, 68, 68, 0.3);
}

.plan-card__header {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: flex-start;
}

.plan-card__info {
  flex: 1;
  min-width: 0;
}

.plan-card__title {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
}

.plan-card__meta-row {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  margin-top: 6px;
}

.plan-card__meta-item {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-right: 12px;
  line-height: 1.8;
}

.plan-card__badges {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-shrink: 0;
}

.plan-card__copy {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 0 10px;
  margin-right: 8px;
  border-radius: 4px;
  background: var(--color-primary-light);
  color: var(--color-primary);
  font-size: 12px;
  font-weight: 600;
}

.plan-card__lines {
  margin-top: 10px;
}

.plan-card__line {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 6px;
}

.plan-label {
  font-size: 13px;
  color: var(--color-text-secondary);
}

.plan-digit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 26px;
  height: 26px;
  margin: 2px 4px 2px 0;
  padding: 0 4px;
  border: 1px solid var(--color-border);
  border-radius: 50%;
  font-size: 13px;
  color: var(--color-text);
}

.plan-digit--hit {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: #fff;
}

/* 自由模式分组 */
.plan-card__data-list {
  margin-top: 10px;
}

.plan-card__data {
  margin-bottom: 8px;
}

.plan-card__data-head {
  display: block;
  margin-bottom: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-secondary);
}

.plan-card__data-body {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
}

.free-pair {
  display: inline-flex;
  flex-direction: row;
  margin-right: 8px;
}

.free-pair .plan-digit {
  margin-right: 0;
  border-radius: 0;
}

.free-pair .plan-digit:first-child {
  border-radius: 4px 0 0 4px;
}

.free-pair .plan-digit:last-child {
  border-radius: 0 4px 4px 0;
  margin-right: 0;
}

/* 正文 */
.content-section {
  margin-top: 14px;
}

.detail-body {
  font-size: 15px;
  line-height: 1.7;
  color: var(--color-text);
}

.detail-body--plain {
  display: block;
  white-space: pre-wrap;
  word-break: break-word;
}

/* 吸底操作栏右侧动作（收藏/分享） */
.bar-action {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 48px;
  min-height: 44px;
  margin-left: 4px;
}

.bar-action__text {
  font-size: 13px;
  color: var(--color-text-secondary);
}

/* 底部弹层动作列表 */
.sheet {
  padding: 16px 16px var(--sa-16, calc(16px + env(safe-area-inset-bottom)));
}

.sheet__title {
  display: block;
  text-align: center;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 8px;
}

.sheet__action {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  border-bottom: 1px solid var(--color-border);
}

.sheet__action-text {
  font-size: 15px;
  color: var(--color-text);
}

.sheet__cancel {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  margin-top: 8px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.sheet__cancel-text {
  font-size: 15px;
  color: var(--color-text-secondary);
}
