.expert-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

/* 资料卡 */
.profile-card {
  margin: 16px;
  padding: 24px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.profile-card__top {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
}

.profile-card__info {
  flex: 1;
  min-width: 0;
  margin-left: 16px;
}

.profile-card__name-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
}

.profile-card__name {
  font-size: 20px;
  font-weight: 700;
  margin-right: 8px;
}

.tag {
  font-size: 11px;
  border-radius: 999px;
  padding: 1px 8px;
  margin-right: 6px;
}

.tag--verified {
  color: var(--color-warning);
  border: 1px solid var(--color-warning);
}

.tag--data {
  color: var(--color-success);
  border: 1px solid var(--color-success);
}

.profile-card__stats {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  margin-top: 10px;
}

.profile-card__stat {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-right: 16px;
  padding: 8px 0;
}

.profile-card__stat--link {
  color: var(--color-primary);
}

.profile-card__actions {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 44px;
  margin-top: 12px;
}

/* 三项统计卡 */
.stats-row {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin: 0 16px;
}

.stat-card {
  flex: 1;
  min-width: 0;
  padding: 16px 12px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.stat-card__label {
  display: block;
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.stat-card__value {
  font-size: 20px;
  font-weight: 700;
}

.stat-card__value--accent {
  color: var(--color-primary);
}

.stat-card__value-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
}

.streak-pill {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--color-primary-light);
  color: var(--color-primary);
  font-size: 12px;
  font-weight: 700;
  margin-left: 4px;
}

.star {
  font-size: 16px;
  color: var(--color-border);
}

.star--on {
  color: var(--color-warning);
}

.stat-card__rating-num {
  font-size: 14px;
  font-weight: 700;
  margin-left: 6px;
}

/* 历史成绩回顾 */
.history-section {
  margin: 16px;
  padding: 20px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.history-section__head {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.history-section__title {
  font-size: 17px;
  font-weight: 700;
}

.history-section__filter {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 999px;
  border: 1px solid var(--color-primary);
}

.history-section__filter-text {
  font-size: 13px;
  color: var(--color-primary);
  font-weight: 600;
}

.segment {
  display: flex;
  flex-direction: row;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
  padding: 4px;
  margin-bottom: 16px;
}

.segment__item {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  border-radius: var(--radius-sm);
}

.segment__item--active {
  background: var(--color-bg-card);
}

.segment__item--disabled {
  opacity: 0.5;
}

.segment__text {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.segment__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

.segment__text--disabled {
  color: var(--color-text-placeholder);
}

/* 成绩卡片 */
.cycle-card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 14px 16px;
  margin-bottom: 12px;
}

.cycle-card__main {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.cycle-card__info {
  flex: 1;
  min-width: 0;
}

.cycle-card__period {
  display: block;
  font-size: 14px;
  font-weight: 600;
}

.cycle-card__code {
  display: block;
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-top: 4px;
}

.cycle-card__side {
  flex-shrink: 0;
  display: flex;
  flex-direction: row;
  align-items: center;
}

.cycle-card__result {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-primary);
  background: var(--color-primary-light);
  border-radius: 999px;
  padding: 4px 14px;
}

.cycle-card__result--miss {
  color: var(--color-text-secondary);
  background: var(--color-bg);
}

.cycle-card__toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding-left: 12px;
}

.cycle-card__toggle-text {
  font-size: 13px;
  color: var(--color-info);
}

.cycle-card__issues {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--color-border);
}

.issue-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  padding: 6px 0;
}

.issue-row__no {
  width: 48px;
  font-size: 13px;
  font-weight: 700;
}

.issue-row__balls {
  display: flex;
  flex-direction: row;
  gap: 8px;
}

.ball {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  font-size: 13px;
  font-weight: 700;
  color: #fff;
}

.ball--miss {
  background: var(--color-danger);
}

.ball--hit {
  background: #f6c844;
  color: #6c4f00;
}

/* 筛选弹层 */
.panel {
  padding: 24px 20px var(--sa-20, calc(20px + env(safe-area-inset-bottom)));
}

.panel__title {
  display: block;
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 16px;
}

.panel__group {
  margin-bottom: 16px;
}

.panel__label {
  display: block;
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.panel__chips {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 999px;
  background: var(--color-bg);
}

.chip--active {
  background: var(--color-primary-light);
}

.chip__text {
  font-size: 13px;
  color: var(--color-text-secondary);
}

.chip__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

.panel__footer {
  margin-top: 8px;
}

.panel__btn {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.panel__btn--primary {
  background: var(--color-primary);
}

.panel__btn-text {
  font-size: 15px;
  color: var(--color-text);
}

.panel__btn-text--primary {
  color: #fff;
  font-weight: 600;
}
