import { useCallback, useRef, useState } from 'react'
import type { PageResult } from '@/types'

interface UsePagedListOptions<T> {
  /** 拉取一页数据；pageNum 从 1 开始 */
  fetchPage: (pageNum: number) => Promise<PageResult<T>>
  pageSize?: number
}

/**
 * 上拉加载 + 下拉刷新统一 hook（产品方案 §3.3）：
 * - refresh 重置到第 1 页；loadMore 追加下一页
 * - hasMore 依据 total 判断；加载中去重
 */
export function usePagedList<T>({ fetchPage, pageSize = 10 }: UsePagedListOptions<T>) {
  const [list, setList] = useState<T[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(false)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState<string>('')
  const pageNumRef = useRef(0)
  const loadingRef = useRef(false)

  const load = useCallback(
    async (pageNum: number, replace: boolean) => {
      if (loadingRef.current) return
      loadingRef.current = true
      if (replace) setRefreshing(true)
      else setLoading(true)
      setError('')
      try {
        const res = await fetchPage(pageNum)
        pageNumRef.current = pageNum
        setTotal(res.total || 0)
        setList((prev) => (replace ? res.rows : [...prev, ...res.rows]))
      } catch (err: any) {
        setError(err?.message || '加载失败')
      } finally {
        loadingRef.current = false
        setLoading(false)
        setRefreshing(false)
      }
    },
    [fetchPage],
  )

  const refresh = useCallback(() => load(1, true), [load])
  const loadMore = useCallback(() => {
    const next = pageNumRef.current + 1
    if (pageNumRef.current > 0 && list.length >= total) return
    return load(next, false)
  }, [load, list.length, total])

  return {
    list,
    total,
    loading,
    refreshing,
    error,
    pageNum: pageNumRef.current,
    hasMore: list.length < total,
    refresh,
    loadMore,
    setList,
    pageSize,
  }
}
